quests[11000] = { id = 11000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schänder der Seelen", description = "Der Zauberfoliant ist der Schlüssel zu Skullocs Untergang.\n\nUm das Ritual zu beginnen, müsst Ihr am Hügel des Seelenschänders laut aus dem Buch vorlesen. Daraufhin werden der Geist des Seelenschänders sowie die Geister seiner Opfer erscheinen. Sie werden versuchen, den Seelenschänder zu vernichten. Ihr müsst sie so lange daran hindern, bis Skulloc vollständig in diese Welt übergetreten ist.\n\nDurchquert den Dolchrachenklamm Richtung Norden. Ihr findet den Grabhügel auf der anderen Seite des Zirkels des Blutes auf der rechten Seite vor Gruuls Unterschlupf.\n\nBringt mir Skullocs Seele!", sourceObjective = "Beschafft Euch Skullocs Seele und bringt ihn zu Mog'dorg dem Weisen auf dem Turm beim Zirkel des Blutes im Schergrat.", progress = "Habt Ihr Skullocs Seele schon geraubt?", completion = "Es ist also vorüber. Ihr habt uns von den Fesseln der Sklaverei durch die Söhne von Gruul befreit. Ihr habt den Klan der Blutschläger vor der sicheren Auslöschung bewahrt.\n\nEs gibt keine Worte um zu beschreiben, wie tief ALLE Oger des Schergrats, Blutschläger wie Speerspießer, in Eurer Schuld stehen, {name}.\n\nSchaut dort, wie all die Oger sich versammeln um Euch Tribut zu zollen! Sollen Gruul und seine Marionette, der alte König Maulgar, sich ruhig in ihrem Unterschlupf verkriechen. Geht zu den Ogern als ihr neuer König!", sourceObjectiveStatus = "unverified-source-field" }
quests[11001] = { id = 11001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet den Rabengott", description = "Wir haben bei der Vernichtung des Rabengottes keine Zeit zu verlieren. Ihr müsst den mit Essenz erfüllten Mondstein zu einem Ort von großer Macht bringen, um den Gott aus der relativen Sicherheit des Smaragdgrünen Traums zu locken.\n\nSteigt in die Sethekkhallen hinab und setzt den Mondstein in die Fänge der Rabenklaue ein. Ihr findet den Raum vor der Halle des Klauenkönigs.\n\nAnzu muss glauben, dass seine Anhänger sich versammelt haben, um ihn wieder in dieser Welt willkommen zu heißen. Zeigt keine Gnade, sobald er sich manifestiert hat!", sourceObjective = "Tötet den Rabengott und kehrt dann zu Morthis Flügelraunen bei der Zuflucht des Cenarius zurück.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Was gibt es neues aus den Sethekkhallen? Habt Ihr Anzu besiegt?", completion = "Schön, Euch wiederzusehen, {name}. Euer Sieg über den Rabengott ist weit mehr als nur ein Test oder ein Aufnahmeritual.\n\nIhr habt Euch als würdig bewiesen, das Wissen, das die Druiden der Klaue seit unzähligen Generationen bewahren, zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11002] = { id = 11002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magtheridons Untergang", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Allianz!\n\nBringt Magtheridons Kopf zu Danath Trollbann in der Ehrenfeste.", sourceObjective = "Bringt Magtheridons Kopf zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, {name}. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Belagerung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[11003] = { id = 11003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magtheridons Untergang", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Horde!\n\nBringt Magtheridons Kopf zu Nazgrel in Thrallmar.", sourceObjective = "Bringt Magtheridons Kopf zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, {name}. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Besetzung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[11004] = { id = 11004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwelt", description = "Himmelskommandant Adaris wurde bei einem Überfall der Skettis schwer verletzt. Seitdem hat er immer und immer wieder sein Bewusstsein verloren.\n\nIch befürchte, dass er Opfer einer Fieberphantasie wurde. In seinen wenigen wachen Momenten, bat er mich darum, ein Elixier aus Schattenstaub herzustellen, wie ihn die Arakkoa bei sich tragen. Er scheint zu glauben, dass er dank des Elixiers in eine Art \"Schattenwelt\" sehen könne, in welcher die wahren Anführer der Arakkoa hausen.\n\nIch schenke diesem Unsinn natürlich keinen Glauben, fürchte jedoch, dass er nicht eher ruhen wird, bis er eines dieser Elixiere in Händen hält. Werdet Ihr uns helfen?", sourceObjective = "Severin möchte, dass Ihr nach Skettis reist und 6 Einheiten Schattenstaub von den dort lebenden Arakkoa sammelt.", progress = "Habt Ihr den Staub, {name}?", completion = "Ich danke Euch, {name}. Ich werde dem Kommandanten eine kleine Menge zukommen lassen... damit er seinen Willen bekommt. Ihr könnt den Rest behalten, vielleicht findet Ihr ja eine Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[11005] = { id = 11005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse der Krallenpriester", description = "Danke, dass Ihr mir im Fieberwahn zugehört habt. Schon seit geraumer Zeit versuchen wir die Kommandokette der Skettis aufzudecken und sie zu zerschlagen. Wir wussten von der Existenz dreier Kleriker, den Krallenpriestern, jedoch haben wir niemals einen von ihnen zu Gesicht bekommen. Nun wissen wir warum.\n\nSprecht mit Severin und beschafft Euch mehr von seinem Elixier. Verwendet das Elixier, um die drei Krallenpriester, Ishaal, Skizzik und Zellek ausfindig zu machen und zu töten. Gerüchten zur Folge findet man sie im Ala'rakversteck, am östlichen Ufer des Schattenwindsees.", sourceObjective = "Beschafft Euch von Severin ein Elixier der Schatten und verwendet es, um Krallenpriester Ishaal, Krallenpriester Skizzik und Krallenpriester Zellek in Skettis ausfindig zu machen und sie zu töten. Kehrt nach Abschluss Eurer Aufgabe zu Kommandant Adaris zurück.", completion = "Ihr habt Euch mit Bravour geschlagen, {name}. Durch den Verlust der Krallenpriester wurde dem Feind ein empfindlicher Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11006] = { id = 11006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Schattenstaub", progress = "Der Kommandant scheint doch nicht aus einem Fieberwahn heraus gesprochen zu haben. Bringt mir mehr Staub und ich werde ein weiteres Elixier für Euch herstellen.", completion = "Ihr könnt mir auch weiterhin noch Staub bringen. Ich werde so viele Elixiere für Euch herstellen, wie Ihr benötigt.\n\nAuf Befehl des Kommandanten." }
quests[11007] = { id = 11007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kael'thas und die tiefgrüne Sphäre", description = "Die Luft um Euch herum ist von einem Summen erfüllt - einem freundlichen Summen. Die Naaru wissen von Eurem Sieg. Vielleicht sind sie der Grund für Euer Bedürfnis, die Sphäre inmitten der immer noch zuckenden Überreste von Kael'thas Sonnenwanderer aufzuheben. Welche Geheimnisse mögen darin stecken?\n\nVielleicht weiß A'dal in Shattrath mehr über diesen Gegendstand.", sourceObjective = "Bringt die tiefgrüne Sphäre zu A'dal in Shattrath.", progress = "Ihr habt meinen Ruf vernommen? Ja...", completion = "<A'dals Gedanken vermischen sich mit den Euren.>\n\nDie Sphäre... Sonderbar. Wusstet Ihr, dass er überlebt hat? Ja. Hier drin, in der Sphäre selbst. Ganz sicher verstümmelt. Er gehorcht nun einer höheren Macht. Nein, nicht Illidan.\n\nHöher.\n\nKil'jaeden der Betrüger kommt...\n\nNicht hierher...\n\n<A'dal führt Euren Geist an einen anderen Ort.>\n\nAzeroth. Unbekannt.\n\nRuht Euch aus. Eure Brüder und Schwestern werden die Festung der Stürme wieder übernehmen.\n\n<A'dal summt eine Kriegshymne.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11008] = { id = 11008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer über Skettis", description = "Glaubt Ihr, dass Ihr das Zeug dazu habt, ein Teil der Himmelswache zu sein? Wir werden überprüfen müssen, wie gut Ihr in der Luft zurechtkommt.\n\nDie Arakkoa züchten eine gigantische Menge von ihren Kampfvögeln, die sie auf unsere Späher hetzen! Ich möchte, dass Ihr diese Sprengladungen nehmt und ihre Brutstätten über den Siedlungen der Arakkoa zerstört. Macht aber einen Bogen um die monströsen Kaliri, welche die Brutstätten bewachen. Sie werden Euch vom Reittier holen, bevor Ihr wisst, wie Euch geschieht!", sourceObjective = "Haltet nach monströsen Kalirieiern oben in den Siedlungen von Skettis Ausschau und benutzt die Sprengladungen der Himmelswache, um sie in die Luft zu sprengen. Kehrt danach zu Himmelsoffizier Doryn zurück.", progress = "Habt Ihr Euren Auftrag schon erledigt?", completion = "Ausgezeichnete Arbeit, {name}! Das wird diesen Vogelwesen zeigen, wer die wahren Herren der Lüfte sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[11009] = { id = 11009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerhimmel", description = "Jetzt, da Ihr uns aus der Knechtschaft befreit habt, können wir mit der Wiedervereinigung der Klans beginnen. Es wird einige Zeit dauern; lange geschürter Zorn kühlt nur langsam wieder ab.\n\nEs ist umso eiliger, dass Ihr nach Ogri'la, hoch oben im Westen, reist. Verteidigt es und uns so gut, wie Ihr könnt. Schützt uns vor den Mächten, wie es einst die Gronn taten: Astrale, Dämonen und noch viel schlimmer, der schwarze Drachenschwarm, erwarten Euch.\n\nSolltet Ihr den Himmel der Oger gefunden haben, ersucht Chu'a'lor um Rat für die weitere Vorgehensweise.", sourceObjective = "Mog'dorg der Weise hat Euch gebeten, mit Chu'a'lor in Ogri'la im Schergrat zu sprechen.", completion = "Mog'dorg hat eine Nachricht voraus geschickt, um mich über Euer Kommen zu informieren. Ich bin froh, dass Ihr hier seid.\n\nNach dem Fall der Söhne des Gruul, ist es nur noch eine Frage der Zeit - es dürfte nicht sehr lange dauern - bevor die unterschiedlichen Bewohner dieser Bergterrasse und die des Nordens beginnen, Jagd auf unsere Ogerbrüder dort unten zu machen.\n\nDies gilt es zu verhindern und ich vertraue auf Eure Unterstützung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11010] = { id = 11010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomberangriff", description = "Ihr habt ein fliegendes Reittier... ja und! Glaubt Ihr denn, dass Ihr das Zeug dazu habt, es gekonnt einzusetzen?\n\nDas Konstruktionslager: Wut und das Konstruktionslager: Terror, im Norden und im Süden, sind mir schon seit langem ein Dorn im Auge und obendrein bedrohen sie das friedliche Ogri'la. Mit all diesen Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nehmen, gibt es einfach kein Hindurchkommen und unser Unterfangen ist zum Scheitern verurteilt.\n\nWürdet Ihr Euch gerne unter Beweis stellen? Nehmt diese Bomben und vernichtet ihre Munitionsvorräte. Lasst Euch aber nicht auch noch vom Himmel herunterholen!", sourceObjective = "Himmelsoffizier Vanderlip hat Euch mit der Bombardierung von 15 Stapeln mit Teufelskanonenkugeln beauftragt. Kehrt zu ihr beim Außenposten der Himmelswache auf dem Schergrat zurück, wenn Ihr den Auftrag erledigt habt.", progress = "Habt Ihr schon ihre Stapel mit Teufelskanonenkugeln vernichtet?", completion = "Gut, gut, scheinbar seid Ihr doch härter im Nehmen als ich dachte. Ausgezeichnete Arbeit. Möglicherweise hatte der alte Keller doch Unrecht, was Euch anbelangt.\n\n<Himmelsoffizier Vanderlip grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11011] = { id = 11011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Wachsamkeit", description = "Euer Sieg über Anzu, den Rabengott, ist eine wahrhaft heldenhafte Leistung. Ich fürchte allerdings, dass er nicht aufgeben und weiterhin versuchen wird, in die Scherbenwelt zurückzukehren.\n\nSolange seine Gefolgsleute am Leben sind, wird er sich immer wieder erheben. Daher solltet Ihr den mit Essenz erfüllten Mondstein stets bei Euch haben, falls Anzu sich erneut regt.", sourceObjective = "Sprecht mit Morthis Flügelraunen, um einen mit Essenz erfüllten Mondstein zu erhalten.", completion = "Behaltet den Mondstein bei Euch, {name}. Wenn Ihr glaubt, dass Anzu seine Kräfte sammelt, um in diese Welt zurückzukehren, verwendet den Stein um ihn zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11012] = { id = 11012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutschwur der Netherschwingen", sourceObjective = "Unser Land ist verloren. Man entführt unsere Kinder in der Nacht, versklavt sie - oder schlimmer...\n\n<Mordenais Stimme wird angespannt.>\n\nEs ist an der Zeit, mein Freund. Zeit, uns wieder das zu nehmen, was einst unser war! Ihr habt Euch als tapferer Kämpfer und verständnisvolle Seele erwiesen.\n\nWerdet Ihr schwören, dem Drachenschwarm der Netherschwingen beim Kampf um unser Land und den Wiederaufbau unserer Heimstätten zu helfen? Werdet Ihr schwören, über den Schwarm zu wachen, damit unser Fleisch und Blut aufs Neue zum Leben erwachen kann? Schwört und lasst uns im Namen unserer Heimat und unserer Familien kämpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11013] = { id = 11013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste der Illidari", description = "Die Netherschwingenscherbe... Was einst eine Feste der Zuflucht für die Netherschwingen war, ist nun das Zuhause des Drachenmalklans. Die Orcs haben vielleicht die Kontrolle über unser Land gewonnen, unsere Magie ist dort jedoch noch stark. Stark genug, um Eure wahre Identität zu verschleiern und um Euch in die Ränge des Drachenmalklans einzuschleusen.\n\nIch habe dieses Schreiben für Euch aufgesetzt, überreicht es ihrem Anführer, Oberanführer Mor'ghor. Fliegt den Fängen unseres Feindes entgegen, reist zum Basislager des Drachenmals und beginnt Euer neues Leben als Höllenorc Illidan Sturmgrimms.", sourceObjective = "Reist zur Netherschwingenscherbe und überreicht Oberanführer Mor'ghor beim Basislager des Drachenmals das Empfehlungsschreiben der Illidari.", progress = "<Mor'ghor grunzt.>\n\nIhr seid spät...", completion = "<Mor'ghor überfliegt das Schreiben und lacht.>\n\nEin Todesritter? Ihr könnt einem Todesritter nicht mal das Wasser reichen, Wurm.\n\n<Mor'ghor mustert Euch scharf.>\n\nNun gut... Ihr könntet es vielleicht noch zum Peon schaffen. Im schlimmsten Fall werfe ich Euch in die Grube und lasse Euch dort verrotten...", sourceObjectiveStatus = "unverified-source-field" }
quests[11014] = { id = 11014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Höhle des Löwen", description = "<Mor'ghor zerknüllt das Empfehlungsschreiben und wirft es beiseite.>\n\nAlso Grunzer, eins nach dem anderen. Wenn Ihr meiner teuren Armee des Drachenmals beitreten wollt, dann müsst Ihr arbeiten. Jeder arbeitet hier auf der Scherbe. Sucht Euch Arbeit und seht zu, dass Ihr Euch nicht zu dämlich anstellt. Eventuell werde ich Euch später mit interessanteren Dingen beauftragen.\n\nSprecht mit Zuchtmeister Varkule Drachenodem, er steht in der Mitte des Lagers. Nach Einschätzung Eurer Fertigkeiten, wird er Euch eine entsprechende Arbeit zuteilen.\n\nUnd jetzt verschwindet!", sourceObjective = "Sprecht mit Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals.", completion = "Varkule findet schon was für Euch, Grunzer. Euch steht eine Aufgabe zu, die Euren Fertigkeiten am besten gerecht wird und unserer Kristallförderung zu Gute kommt. Ihr müsst Euren Arbeitsauftrag einmal am Tag ausfüllen.\n\nJa, es gibt da einen Haufen Drecksarbeit zu erledigen, aber auch die Ahnen haben mal als Peon begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11015] = { id = 11015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle der Netherschwingen", description = "Ihr taugt zu nichts, was? In Ordnung, auch Vollidioten wie Ihr können uns hier noch zur Hand gehen. Sucht auf der Scherbe einfach nach Kreaturen und tötet sie. Manchmal befinden sich auf ihren Körpern Kristalle der Netherschwingen. Sammelt und bringt sie mir, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 30 Kristalle der Netherschwingen bringt.", progress = "Kristalle der Netherschwingen werden für vielerlei Dinge verwendet. Hauptsächlich zur Herstellung von Waffen und Rüstungen...", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11016] = { id = 11016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balg eines Netherminenschinders", description = "Ein Kürschner, ja? Nun, Ihr werdet hier mehr als genug Häutbares finden! Sucht in der Nähe der Kristallformationen nach Schindern. Tötet sie und nehmt ihre Bälge an Euch. Vielleicht sind die ein oder anderen sogar etwas wert, bringt mir genau diese.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 35 Bälge eines Netherminenschinders bringt.", progress = "Wir verwenden die Bälge von Schindern zum Ausfüttern von Rüstungen und die Herstellung von Planen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11017] = { id = 11017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherstaubpollen", description = "Ein Blümchenpflücker?! Köstlich... bedauerlicherweise benötigen unsere Magier und Schamanen Eure Dienste. Die Netherstaubbüsche, die hier auf der Scherbe wachsen, besitzen spezielle Pollen, die bei magischen Angelegenheiten wohl recht nützlich sind. Bringt mir das Zeug, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Netherstaubpollen bringt.", progress = "Wie ich schon sagte, Netherstaubpollen werden von unseren Zauberern verwendet.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11018] = { id = 11018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netheriterz", description = "Ein Minenarbeiter!\n\n<Varkule nickt Euch zu.>\n\nEin Orc ganz nach meinem Geschmack! So hat Varkule auch einmal angefangen - mit Bergbau! Es gibt doch nichts Besseres als runter in die Mine zu gehen und richtig schmutzig zu werden, nicht wahr?\n\nGeht jetzt und sucht nach Netheritablagerungen. Holt alles, was wertvoll ist, heraus und bringt mir das Erz.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Einheiten Netheriterz bringt.", progress = "Gug dort drüben verwendet das Erz zum Verstärken unserer Waffen und Rüstungen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11019] = { id = 11019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund unter Feinden", sourceObjective = "Ihr habt doch nicht etwa geglaubt, dass wir Euch den Armeen der Höllenorcs ganz alleine überlassen würden, oder?\n\n<Yarzills Augen flackern in einem durchscheinenden Blau.>\n\nGenau, wir sind hier an Eurer Seite, {name}. Bei jedem Dienst, den Ihr den Höllenorcs bei Eurem Versuch, die Weiten der Netherschwingen zurückzuerobern, erweist, werden wir dafür sorgen, dass sie einen ausreichenden Rückschlag erleiden.\n\nIhr müsst Euch sehr unauffällig verhalten, um keinerlei Aufmerksamkeit während Euren Sabotageeinsätzen auf Euch zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11020] = { id = 11020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein langsamer Tod", description = "Die Anhänger des Drachenmals haben bei fast allen Kristallformationen hier oben Peons stationiert. Ein bloßes Töten, würde Euch bei weitem zu viel unerwünschte Aufmerksamkeit einbringen. Wir können ihre Reihen aber auch auf eine andere Art und Weise lichten, ohne bei dem misstrauischen Mor'ghor Verdacht zu erwecken.\n\nReist in die Wildnis des Schattenmondtals und tötet die besudelten Tiere. Nehmt ihre verderbten Teufelsdrüsen an Euch. Wendet die Teufelsdrüsen in der Nähe der Peons auf den Hammel an, den ich Euch geben werde. Ein Biss und sie sind tot!", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr Yarzills Hammel zusammen mit den Teufelsdrüsen verwendet, um 12 Peonlager des Drachenmals zu vergiften.", progress = "Es ist eine schmutzige Arbeit, {name}.", completion = "<Yarzill flüstert ganz leise.>\n\nAusgezeichnete Arbeit, {name}. Verhaltet Euch fürs Erste ruhig. Kommt morgen wieder zu mir, dann können wir das Ganze noch einmal machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11021] = { id = 11021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishaals Almanach", description = "Dieser geheimnisvolle Foliant lag bei Krallenpriester Ishaals Leichnam. Die darin abgebildeten arkanen Symbole und Schaubilder von Himmelskörpern sind Euch völlig fremd.\n\nSämtliche Aufzeichnungen wurden in einer für Euch unverständlichen Sprache verfasst; vermutlich eine uralte Form der Arakkoaschriftsprache. Vielleicht solltet Ihr damit zu Himmelskommandant Adaris gehen.", sourceObjective = "Bringt Ishaals Almanach zu Himmelskommandant Adaris im Norden von Skettis.", progress = "Ihr wollt mir etwas zeigen?", completion = "Was habt Ihr mir da gebracht? Die Sprache dieses Folianten ist mir fremd, {name}... mein Blutverlust... muss meinen Geist verschleiert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11022] = { id = 11022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Mog'dorg", description = "<König/Königin> {name}! Bevor Ihr uns verlasst und nach Ogri'la geht, sprecht mit Mog'dorg dem Weisen!", sourceObjective = "Sprecht mit Mog'dorg dem Weisen. Er steht oben auf dem Turm auf der Ostseite des Zirkels des Blutes im Schergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11023] = { id = 11023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und wieder ein Bombenangriff!", description = "Diese Flakgeschütze bereiten uns noch immer Sorgen, {name}.\n\nVersteht mich bitte nicht falsch - Ihr habt das letzte Mal hervorragende Arbeit geleistet, aber das ändert leider nichts an der Tatsache, dass diese verdammten Dämonen ihre Munitionsvorräte schneller wieder aufzufüllen vermögen, als wir sie vernichten können. Unsere Männer da hineinzuschleusen ist momentan also ein mehr als riskantes Unterfangen, ganz zu schweigen von dem Risiko, das die Dämonen für Ogri'la darstellen.\n\nWas sagt Ihr? Wollt Ihr es noch einmal versuchen?", sourceObjective = "Himmelsoffizier Vanderlip hat Euch mit der Bombardierung von 15 Stapeln Teufelskanonenkugeln beauftragt. Kehrt zu ihr zum Außenposten der Himmelswache hoch oben im Schergrat zurück, wenn Ihr den Auftrag erledigt habt.", progress = "Wie steht es mit dem Bombenangriff?", completion = "Hervorragend, {name}! Ich würde Euch ja sofort wieder in die Luft schicken und ein paar Bomben werfen lassen, aber unsere Richtlinien hier schreiben vor, dass unsere Piloten ausreichend Ruhe und Erholung erhalten müssen. Es tut mir leid, ich mache die Regeln nicht, aber lasst Euch versichern, dass ich sie durchsetzen werde!\n\nSehen wir uns morgen wieder, Sportskanone?", sourceObjectiveStatus = "unverified-source-field" }
quests[11024] = { id = 11024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Verbündeter im unteren Viertel", description = "Im unteren Viertel gibt es einen Arakkoa namens Rilak... ihm kann Vertrauen geschenkt werden. Nehmt das Buch... und bringt es zu ihm.\n\n<Adaris gibt Euch das Buch wieder und verliert daraufhin das Bewusstsein.>", sourceObjective = "Bringt Ishaals Almanach zu Rilak dem Erlösten im unteren Viertel in Shattrath.", progress = "Ihr seid mit dem Geruch Skettis' behaftet! Was hat das zu bedeuten?", completion = "Das kann nicht sein... dies war einst Eigentum eines Krallenpriesters. Wie ist es nur in Eure Hände gelangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11025] = { id = 11025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kristalle", description = "Beim richtigen Umgang mit den Kristallen der Berge, weisen diese seltsame Kräfte auf, wie zum Beispiel die Klarheit des Geistes, die wir hier in Ogri'la entdeckt haben.\n\nAlle Kreaturen oben auf den Bergen begehren danach und benutzen die Splitter, um ihre eigenen Ziele voranzutreiben. Der Wert dieser Kristalle hat sogar eine regelrechte Wirtschaft aufkommen lassen.\n\nUm uns helfen zu können, müsst Ihr zunächst etwas über die Apexissplitter lernen. Bringt mir ein paar Exemplare. Nicht nur die Kreaturen hier besitzen welche, gelegentlich findet man sie auch bei den großen Kristallen, dort, wo die Hetzer graben.", sourceObjective = "Chu'a'lor möchte, dass Ihr 5 Apexissplitter einsammelt. Bringt sie zu ihm in Ogri'la hoch oben im Schergrat.", progress = "Wenn Ihr mehr über die Splitter und Kristalle lernt, werdet Ihr uns und unsere Ogerbrüder dort unten besser beschützen können.\n\nDie Splitter selbst wurden nach einer uralten und mittlerweile ausgelöschten Arakkoazivilisation benannt, die einst auf den Spitzen dieser Berge lebte.\n\nNun, habt Ihr die Splitter bei Euch?", completion = "<Chu'a'lors linker Kopf beginnt zu sprechen.>\n\nDiese sind genau richtig.\n\nDenkt daran, {name}, der Wert dieser Splitter liegt nicht in ihrem Verkaufspreis. Es ist nicht einmal das, was sie für Euch tun können, sobald sie ordnungsgemäß zusammengeschmiedet wurden... auch wenn sich darüber streiten lässt.\n\n\n\nDer wahre Wert liegt in dem Unterfangen, das es auf sich zu nehmen gilt, um in den Besitz dieser Splitter zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11026] = { id = 11026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannt die Dämonen", description = "Ihr seid genau zur rechten Zeit hier eingetroffen! Wir brauchen dringend Unterstützung. Als Gegenleistung werden wir Euch etwas sehr seltenes und von beiderseitigem Wert für Euch und für uns überlassen.\n\nWir sind keine gewalttätigen Oger mehr, aber die nahegelegenen Dämonen drohen uns und die Himmelswache zu überrennen. Das Problem mit Dämonen ist, hat man sie erst einmal getötet, tauchen sie wenig später in einem neuen Körper wieder auf!\n\nWenn Ihr allerdings mit diesem Kristall ein Bannportal beschwört und ein Dämon in dessen Nähe stirbt, wird seine Essenz in das Portal gezogen und er in seine Heimatebene verbannt!", sourceObjective = "Kronk möchte, dass Ihr den Bannkristall einsetzt, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror hoch oben im Schergrat zu bannen. Meldet Euch anschließend wieder bei ihm.", progress = "Wir nehmen an, Ihr habt den Bannkristall dazu benutzt, eine ganze Reihe dieser Dinger der Brennenden Legion zum Packen zu bewegen?", completion = "Das wird ihnen eine Lehre gewesen sein! Kommen wir nun zu Eurer Belohnung.\n\nDie Dämonen des Konstruktionslagers: Wut im Norden haben an ihrer südlichen Grenze einen besonderen Transporter errichtet. Sie verwenden dieses experimentelle Transporttor, um den Einfluss des Lagers weiter auszudehnen. Wir brauchen Euch wohl nicht erst erklären, was passieren wird, wenn sie sich zu weit ausbreiten.\n\nAlso, wenn wir Ihr wären, würden wir diese Rune der Dunkelheit zu Gahk schaffen und ihn Fragen, wie Ihr helfen könnt. Geht es langsam mit ihm an, {name}, er ist ebenfalls neu hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[11027] = { id = 11027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr die Rune der Dunkelheit?" }
quests[11028] = { id = 11028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Countdown des Schicksals", description = "Dieser Almanach prophezeit die Rückkehr von Terokk, dem mächtigsten und furchtbarsten Skettiskönig der Arakkoageschichte.\n\nIch habe dies immer für eine Legende gehalten, {name}. Die Wiederkehr der Krallenpriester und Eure Entdeckung dieses Folianten belehren mich jedoch eines Besseren.\n\nMit jedem Tag wächst die Macht Terokks und seine Ankunft naht. Die einzige Chance, die Ihr habt, ist ihn vorzeitig in unsere Welt zu holen. Geht zurück nach Skettis und sprecht mit Adaris über das Ganze. Lasst uns hoffen, dass er die Weisheit besitzt, um die richtige Entscheidung zu treffen.", sourceObjective = "Kehrt zu Himmelskommandant Adaris zurück und berichtet ihm von den Neuigkeiten über Terokks Rückkehr.", completion = "Die Arakkoa möchten Terokk zurück aus dem Jenseits der Zeit holen und Rilak... möchte einen Weg finden, um diesen Vorgang zu beschleunigen? Hat er denn seinen Verstand verloren?\n\n<Adaris legt sich geschwächt nieder.>\n\nIhr habt Eure Pflicht erfüllt, {name}. Es ist an der Zeit, dass Ihr die Sache meinen Männern überlasst. Das ist jetzt eine rein militärische Angelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11029] = { id = 11029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schäbige Verkleidung", description = "Öffnet das Päckchen, {name}. Es ist eine Verkleidung. Sie sieht nicht sehr überzeugend aus, oder?\n\nIch fertige sie für astrale Schmuggler an, auf der Suche nach seltenen Büchern. Es gibt einen Schreiber der Arakkoa, der auf der zentral gelegenen Insel in Skettis lebt, die als Terokks Ruh bekannt ist; sein Name ist Sahaak. Er ist alt und fast blind.\n\nVerwendet die Verkleidung, um mit ihm zu sprechen und besorgt Euch das Buch, den Stammbaum der Feinde. Seid auf der Hut, {name}. Andere Arakkoa lassen sich von der Verkleidung nicht täuschen.", sourceObjective = "Verwendet die schäbige Arakkoaverkleidung, um den Stammbaum der Feinde von Sahaak zu beschaffen. Kehrt anschließend zu Hazzik zurück.", progress = "Das Buch, {name}. Habt Ihr es?", completion = "Ausgezeichnet! Das Buch beinhaltet eine Aufstellung der Nachfahren von Terokks alten Feinden. Es wurde vorhergesagt, dass ihr Tod Terokks Rückkehr ankündigen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11030] = { id = 11030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Junge möchte der Himmelswache beitreten", description = "Wir haben ein kleines Problem, {class}: Wir haben eine Menge Söhne. Seit die Himmelswache bei uns in der Nähe stationiert wurde, wünschen sie sich nichts sehnlicher, als der Wache beizutreten.\n\nAls stolzer Vater möchten wir natürlich, dass sie zum Zeitpunkt ihrer Bewerbung alle Vorteile haben, die sie kriegen können. Würdet Ihr also für uns die Teufelskristallschmiede in einem der beiden Lager im Norden oder im Süden aufsuchen und ein magisches Fläschchen für unsere Söhne beschaffen? Ihr könnt ihren grünen Rauch kaum verfehlen.\n\nWir denken, die Herstellung eines Fläschchens erfordert zehn Apexissplitter. Gerne würden wir Euch Splitter mitgeben, aber leider haben wir keine mehr zur Hand.", sourceObjective = "Torkus möchte, dass Ihr ihm ein instabiles Fläschchen der Bestie bringt. Bringt es zu ihm in Ogri'la hoch oben im Schergrat.", progress = "Habt Ihr das magische Fläschchen schon bekommen? Es würde Torkus Junior alles bedeuten.", completion = "Ihr seid ein Lebensretter, {name}!\n\nUnsere Jungs werden von dieser Neuigkeit begeistert sein!\n\nOk, eines geschafft und eines fehlt noch. Wir haben Euch doch bestimmt von dem anderen Fläschchen erzählt, das sie benötigen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11031] = { id = 11031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Erzmagier", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11032] = { id = 11032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Beschützer", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11033] = { id = 11033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Assassine", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11034] = { id = 11034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Bewahrer", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11035] = { id = 11035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatten am Horizont", description = "Am nordöstlichen Ende dieser Insel gibt es ein Dock, das dem Verpacken und dem Transport der Kristalle und Relikte der Netherschwingen dient. Transporter des Drachenmals transportieren die Güter vom Dock zu der Festung des Drachenmals, während die Ahnen des Drachenmals den Boden vor möglichen Angreifern schützen.\n\nUm dem Drachenmal einen Schlag zu versetzen, bleibt nur ein Angriffspunkt offen: der Himmelspfad des Drachenmals.\n\nFliegt zu den zerschlagenen Inseln des Himmelspfads des Drachenmals und lauert den Transportern auf, die diesen Weg einschlagen. Bringt unsere gestohlenen Relikte wieder in Sicherheit!", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 10 Relikte der Netherschwingen sicherstellt.", progress = "Tote Orcs singen nicht, {name}. Stellt sicher, dass keiner der Transporter des Drachenmals entkommt.", completion = "<Yarzill flüstert.>\n\nIhr habt den Netherschwingen einen großen Dienst erwiesen, {name}. Der Fall des Drachenmals rückt in greifbare Nähe. Von innen heraus breitet sich nun eine Krankheit aus - eine unheilbare Krankheit...\n\nSolltet Ihr wieder an Arbeit bei dem Himmelspfads des Drachenmals interessiert sein, so kommt morgen wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11036] = { id = 11036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außerirdische Früchte!", description = "Ich muss ganz ehrlich zugeben, dass ich nicht die leiseste Ahnung habe, wozu diese Lieferung dienen soll, aber Raketenchef Doppeldeckers Anweisungen waren sehr genau - nur die besten Früchte, konserviert, um eine lange Reise zu überstehen und gut versiegelt sollen sie sein.\n\nEs gab noch weitere Anweisungen, irgendetwas über Schwerelosigkeit hier und Niedrigdruck da. Ich gebe nicht mal vor, alles zu verstehen, aber der Preis stimmt, also kriegt er seine Supernahrung. Bringt diese Kiste zu ihm in der Area 52. Nachdem Ihr den Nethersturm betreten habt, folgt der Straße, bis Ihr die Stadt seht.", sourceObjective = "Bringt die konservierten Früchte zu Raketenchef Doppeldecker in Area 52.", progress = "Ist das die Lieferung vom alten Orok?", completion = "<Der Raketenchef überprüft den Inhalt der Kiste.>\n\nSieht soweit gut aus. Wieder etwas, dass ich von der Liste streichen kann. Nun müssen wir noch nur dafür sorgen, dass die Rakete vom Boden abhebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11037] = { id = 11037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Vision", description = "{name}, ich hatte eine höchst ungewöhnliche Vision, auf die ich mir keinen Reim machen kann. Ich sah einen Pfeil, einen gigantischen Pfeil, der sich auf einem Feuerschweif gen Himmel erhob. Für einen geübten Magier wäre es ein Leichtes etwas derartiges zu erschaffen, doch ein Gefühl sagt mir, dass dieses Objekt nicht das Produkt von Magie ist.\n\nEs wird anders sein, als alles, dass die Völker von Azeroth je erschaffen haben. Ihr müsst diejenigen finden, die an diesem Wunderwerk arbeiten, {name}. Gewährt ihnen Eure Hilfe, denn ohne sie, werden sie versagen.", sourceObjective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", completion = "<Der Raketenchef hört Euch aufmerksam zu, als Ihr ihm von der Vision des Sehers erzählt.>\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch die Rakete hinter mir an! Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11038] = { id = 11038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für Exarch Orelis", description = "Vor nicht allzu langer Zeit entsandte Hohepriesterin Ishanah eine kleine Gruppe von Anachoreten unter dem Kommando von Exarch Orelis in den Nethersturm. Sie hatten den Auftrag, die Aktivitäten von Kael'thas und seinen Gefolgsleuten zu untersuchen, doch bisher haben wir keinerlei Nachricht von ihnen erhalten.\n\nIch habe die Befürchtung, dass unsere Präsenz im Zielgebiet nicht stark genug ist, um diesen Auftrag erfolgreich abzuschließen. Sicherlich würde der Exarch von Eurem Wissen und Eurer Erfahrung profitieren. Wäret Ihr bereit zur Area 52 zu reisen und ihn zu unterstützen?", sourceObjective = "Sprecht mit Exarch Orelis in Area 52.", completion = "So, Ihr seid also hierher gekommen, um unsere Untersuchungen über Kael'thas Pläne zu unterstützen? Eure Hilfe ist uns sehr willkommen. Der Nethersturm ist voll von Agenten der Blutelfen, die nichts unversucht lassen, um das Land ins Chaos zu stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11039] = { id = 11039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Spionagemeister Thalodien", description = "Vor einiger Zeit schickte Voren'thal ein kleine Einheit in den Nethersturm, um Kael'thas Aktivitäten genauer zu beobachten. Unser Anführer hat vollstes Vertrauen in die Fähigkeiten von Spionagemeister Thalodien und seinen Männern und hat sich daher entschlossen, seiner Bitte um Verstärkung nachzukommen.\n\nThalodiens Bericht fiel recht knapp aus, doch geht daraus eindeutig hervor, dass er eine Entdeckung von größter Wichtigkeit gemacht hat. Erstattet ihm in der Area 52 Meldung und unterstützt ihn soweit es Euch möglich ist, {name}.", sourceObjective = "Meldet Euch bei Spionagemeister Thalodien in Area 52.", completion = "<Einen Augenblick lang huscht ein Ausdruck der Enttäuschung über das Gesicht des Spionagemeisters.>\n\nIch hatte wenigstens auf eine ganze Einsatzgruppe gehofft, aber wenn Voren'thal es für sinnvoll hielt, Euch alleine zu entsenden, werde ich meine Pläne entsprechend anpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11040] = { id = 11040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile für den Raketenchef", description = "Wie oft ich mit einem Goblin zusammengearbeitet habe, kann ich an einer Hand abzählen. Normalerweise konkurrieren wir mit ihnen, aber als ich Raketenchef Doppeldeckers Anfrage erhielt, konnte ich sie nicht einfach so ablehnen.\n\nDiese Kiste ist voller Einzelteile für die ich hier keine Verwendung habe, aber die für das Projekt des Raketenchefs sehr nützlich sein könnten. Wäret Ihr so freundlich und würdet Sie bei ihm abgeben, wenn Ihr an der Area 52 vorbeikommt?\n\nWer weiß, vielleicht schaffen es einige gnomische Teile, seine Erfindung vor der Zerstörung zu bewahren!", sourceObjective = "Bringt Bossis Ersatzteile zu Raketenchef Doppeldecker in Area 52.", progress = "Diese Kiste sieht aus, als stamme sie von einem Goblinmeisteringenieur. Hat Bossi Euch geschickt?", completion = "Ich weiß nicht einmal, was einige dieser Teile bewirken! Einige von ihnen werden mir sicherlich sehr nutzen. Ich hätte niemals gedacht, dass ich mal lernen müsste, wie ein Gnom zu denken!", sourceObjectiveStatus = "unverified-source-field" }
quests[11041] = { id = 11041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unerledigte Aufgabe...", description = "Im Namen unseres großen Meisters... zum Ruhme Illidans!\n\nIm Auftrag von Oberanführer Mor'ghor soll das große Plateau der Netherschwingenscherbe gesichert werden. Da fast alle Drachen der Netherschwingen eingefangen oder vom Land vertrieben wurden, nehmen die Felsklauen langsam überhand und bedrohen unsere Kristallernte.\n\nVernichtet sie alle, ihre Höhlenmutter und ihren Gefährten, Arvoar.\n\nMor'ghor befiehlt es so!\n\n<Es scheint ganz so, als hätte der Orc beim Absichern des Plateaus versagt. Es ist an der Zeit, dass Ihr Euch bei Mor'ghor als würdig erweist!>", sourceObjective = "Tötet 10 Felslandschinder und Barash die Höhlenmutter. Kehrt nach erfolgreicher Erledigung zu Oberanführer Mor'ghor beim Basislager des Drachenmals zurück.", progress = "Wer wagt es, an Mor'ghor heranzutreten? Ich hoffe für Euch, dass es von Wichtigkeit ist.", completion = "Ihr habt also bei den Überresten einer meiner Aufseher eine Anordnung gefunden und die Sache selbst in die Hand genommen? Ihr habt es geschafft, Mor'ghor zu beeindrucken. Gut gemacht...", sourceObjectiveStatus = "unverified-source-field" }
quests[11042] = { id = 11042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verblüffende Vision", description = "Mich verfolgt eine seltsame Vision, {name}. Ich sehe eine riesige Rauchwolke, die gen Himmel steigt, und ein gigantisches Feuer, welches sich noch weit höher erhebt. Es ist weder ein natürliches Phänomen, noch ein Werkzeug des Bösen; so viel ist sicher.\n\nIch habe keine Vorstellung davon, wie es aussieht, ich weiß nur, dass es das Werk Vieler ist. Dennoch, ohne weitere helfende Hände, wird diese Vision wohl nie Realität werden.\n\nReist in den Nethersturm, {class}. Findet die Erschaffer dieser Erscheinung und bietet ihnen Eure Hilfe an.", sourceObjective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", completion = "<Der Raketenchef hört Euren Ausführungen über die Vision des Sehers aufmerksam zu.>\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch das Ungetüm hinter mir an. Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11043] = { id = 11043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Greif", description = "Wie ich hörte, unterhalten die Wildhammerzwerge in ihrer Festung im südlichen Schattenmondtal einen Greifenhorst. Könntet Ihr, wenn Ihr Euch dorthin begebt, in meinem Namen mit ihnen sprechen? Ich habe da einige Ideen, wie man ihre Greifen noch verbessern könnte!\n\nWarum sie nur mit einer Rüstung ausstatten, wenn man sie noch mit einem Höhenmesser, einem Rückspiegel und einer Rakete bestücken kann? Stellt Euch nur vor, welche Geschwindigkeiten ein Greif mit einer, auf seinem Rücken festgeschnallten, Rakete erreichen würde! Ich nenne meine Erfindung den Turbogreifen 8000!", sourceObjective = "Sprecht mit Brunn Flammenbart in der Wildhammerfeste.", completion = "<Brunns Gesicht errötet, bis es nicht länger von seinem Bart zu unterscheiden ist.>\n\nEr möchte WAS mit meinen Greifen anstellen?\n\nWenn diese kleine Ratte auch nur versucht, irgendetwas anderes als einen Sattel auf meinen Greifen zu befestigen, reise ich persönlich zum Schergrat und stopfe ihm mit seinen Raketen das Maul!", sourceObjectiveStatus = "unverified-source-field" }
quests[11044] = { id = 11044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen voller Zerstörung", description = "Eine Vision voller Zerstörung reißt mich oft aus dem Schlaf. - Ein Regen aus grünem Feuer, der auf die Erde herabregnet und die tapferen Verteidiger einer mächtigen Festung verbrennt. Seit Wochen schon verfolgt mich dieser Traum, doch erst kürzlich ist mir seine Bedeutung offenbart worden.\n\nWeit im Osten, im Schattenmondtal, erwehren sich die Wildhammerzwerge den ständigen Angriffen der Brennenden Legion und zahlloser anderer Feinde. Sie kämpfen tapfer, doch wenn sie nicht bald Entsatz erhalten, werden ihre Feinde triumphieren. {name}, Ihr müsst ihnen zur Seite stehen. Helft ihnen in ihrem verzweifelten Kampf.", sourceObjective = "Sprecht mit Schwadronskommandant Nuainn in der Wildhammerfeste.", completion = "Eine Vision sagt Ihr? Es interessiert mich nicht, ob er es in einer Vision gesehen, in einem Brief gelesen oder es aus dem Mund eines Grubenlords vernommen hat, aber er hat den Nagel auf den Kopf getroffen! Was führt Euch hierher, Freund? Oh, und wir sind für jede Unterstützung dankbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[11045] = { id = 11045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorus der Richter", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Zorus der Richter versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihm jede Hilfe willkommen ist.\n\nSolltet Ihr ins Tal reisen, haltet Ausschau nach Zorus bei der Wildhammerfeste, sie liegt zentral im Süden des Tals.", sourceObjective = "Sprecht mit Zorus dem Richter in der Wildhammerfeste.", completion = "Fantei spricht die Wahrheit, Eure Hilfe kommt mir sehr gelegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11046] = { id = 11046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefapothekerin Hildagard", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Chefapothekerin Hildagard versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihr jede Hilfe willkommen ist.\n\nFalls Ihr Euch jemals dorthin begebt, sucht Hildagard beim Dorf Schattenmond auf, es liegt im nordwestlichen Teil des Tals.", sourceObjective = "Sprecht mit Chefapothekerin Hildagard in Schattenmond.", completion = "Fantei hat ein gutes Gedächtnis. Es ist schon Monate her, dass ich in Shattrath war, um Zutaten zu kaufen. Allerdings hat er Recht. Ich könnte etwas Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11047] = { id = 11047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte des Gesellen", description = "Als ein Windreitermeisterlehrling gehört es zu meinen Aufgaben, die Tiere zu versorgen, wenn sie nicht gerade fliegen. Das Problem ist, dass die Windreiter sich kaum erholen können, da wir über so wenige von ihnen verfügen.\n\nIch fürchte, dass wenn wir nicht bald Ersatz erhalten, sie sich alle zu Tode fliegen werden. Im westlichen Schattenmondtal, im Dorf Schattenmond, gibt es einen großen Stall. Dama Wildmähne überwacht dort die Ausbildung und Versorgung der dortigen Windreiter.\n\nWürdet Ihr in meinem Namen mit ihr sprechen und ihr von unserer Situation berichten?", sourceObjective = "Sprecht mit Dama Wildmähne im Dorf Schattenmond.", completion = "<Dama hört sich Agadais Bitte an.>\n\nIch kann nicht dafür garantieren, dass wir über genügend Windreiter verfügen, aber ich werde sehen, was ich tun kann. In der momentanen Situation haben wir Schwierigkeiten, die Nachfrage der verschiedenen Käufer und Außenposten abzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11048] = { id = 11048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroghans Bericht", description = "Meine ursprünglichen Befehle sahen vor, dass ich für kurze Zeit in Garadar bleibe und ich mich anschließend bei Blutwache Gulmok im Dorf Schattenmond melden sollte. In meiner Zeit hier ist mir klar geworden, dass Garadar von einer langfristigen Zusammenarbeit mit der Horde profitieren würde.\n\nIch weiß, dass Blutwache Gulmok alle verfügbaren Truppen braucht, aber er wird auch einsehen müssen, dass meine Mission hier noch nicht zu Ende ist. Reist nach Schattenmond, im nordwestlichen Teil des Schattenmondtals, und informiert Blutwache Gulmok über meine verspätete Ankunft.", sourceObjective = "Sprecht mit Blutwache Gulmok im Dorf Schattenmond.", completion = "<Gulmok beginnt zu murren, als er von Kroghans Entscheidung hört.>\n\nIch verstehe durchaus seinen Standpunkt, doch unsere Schützengräben besetzen sich nicht von selbst! Die Legion bombardiert uns Tag und Nacht mit Höllenbestien. Wenn Kroghan sich verspätet, könnt Ihr ja seinen Platz auf dem Schlachtfeld einnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11049] = { id = 11049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Eierjagd", description = "Solltet Ihr bei Euren Erkundungen auf Eier der Netherschwingen stoßen, bringt sie zu mir.\n\nEines ist sicher, ein Ei der Netherschwingen ist ein seltener Fund. Lasst den Kopf nicht hängen, falls Ihr keine Eier finden könnt. Die Anhänger des Drachenmals waren beim Einsammeln recht gründlich. Sie haben fast alle aufgespürt und an unbekannte Stellen versendet.\n\nMan findet die Eier im Besitz von Kreaturen der Insel, in der Nähe von Kristallformationen, in den Minen oder auch in Netheritansammlungen oder Netherstaubbüschen.\n\nHaltet Euch bedeckt. Mor'ghor soll wenn möglich nichts von Eurem Unterfangen erfahren.", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ein Ei der Netherschwingen einsammelt.", progress = "Was macht die Eierjagd?", completion = "Neltharaku wird höchst erfreut sein, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11050] = { id = 11050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer her mit den Eiern", progress = "Diese Eier dürfen auf keinen Fall in die falschen Hände geraten, {name}. Wenn Ihr noch mehr Eier findet, bringt sie mir.\n\nVerhaltet Euch auf jeden Fall unauffällig und erregt bloß keinen Verdacht!", completion = "Ihr seid ein wahrer Held, {name}." }
quests[11051] = { id = 11051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannt mehr Dämonen", description = "Wenn wir die Dämonen richtig einschätzen, was sehr wahrscheinlich ist, da wir sie ausgiebig studiert haben, werden sie versuchen, den Schaden an ihrem kostbaren Transporter so schnell wie möglich zu reparieren.\n\nAlso, wenn Ihr Eure Chance auf eine weitere Rune der Dunkelheit wahrnehmen möchtet, nehmt den Bannkristall und erledigt dort draußen noch mehr Dämonen für uns. Schließlich wollt Ihr uns doch dabei helfen, die Bedrohung durch die Dämonen in den Griff zu kriegen, nicht wahr?\n\nWir sagten Chance, weil der von uns angewandte Herstellungsprozess nicht immer einwandfrei funktioniert. Manchmal kommt eine Rune der Dunkelheit dabei heraus, dann wieder etwas völlig anderes.", sourceObjective = "Kronk möchte, dass Ihr den Bannkristall einsetzt, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror hoch oben im Schergrat zu bannen. Meldet Euch anschließend wieder bei ihm.", progress = "Jemand mit Eurer Erfahrung dürfte keine Probleme damit haben, ein paar Dämonen zu bannen. Ihr habt doch keine Schwierigkeiten damit, oder {race}?", completion = "Wir wünschten uns, der Herstellungsprozess für Runen der Dunkelheit wäre narrensicher, {name}. Unglücklicherweise ist er das nicht. Nehmt bitte diesen Sack und seht mal, was wir heute hergestellt haben. Wir haben es nicht übers Herz gebracht, selbst nachzusehen.\n\nWenn Ihr eine Rune der Dunkelheit erhaltet, vergesst nicht, Gahk aufzusuchen und sie bei ihm gegen eine kristallgeschmiedete Rune der Dunkelheit einzutauschen. Mit ihr könntet Ihr Shartuuls Transporter erneut ausschalten.\n\nOh, und {name}, denkt daran, morgen wiederzukommen und den Bannkristall abzuholen. Es sind genug Dämonen da, die gebannt werden möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11052] = { id = 11052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akamas Versprechen", description = "<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, {name}. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.", sourceObjective = "Bringt das Medaillon von Karabor zu A'dal in Shattrath.", progress = "<A'dal bemerkt Euch und umarmt Euch mit einem warmen Licht. Er scheint zu wissen, dass Ihr etwas für ihn habt.>", completion = "<Als Ihr A'dal das Medaillon übergebt, verschwindet es mit einem Lichtblitz in seinem Geist.>\n\n<Für einen kurzen Moment erscheint eine Szene vor Euch... vielleicht aus der Zukunft. Ihr seht, wie Akama und Maiev aus dem Kerker des Wächters heraustreten und sich zum Schwarzen Tempel durchschlagen. Eine dritte, in Schatten gehüllte Gestallt hilft ihnen dabei. Als Ihr genauer hinschaut, erkennt Ihr, dass Ihr diese Gestalt seid.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11053] = { id = 11053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Aufseher!", description = "Es ist selten, dass ein Peon so lange überlebt wie Ihr. Es ist allerdings noch seltener, dass sich ein Peon vom Abschaum abhebt und in einen neuen Rang aufsteigt.\n\n<Varkule klatscht.>\n\nDer Oberanführer hat nach Euch verlangt, Grunzer. Sicherlich erwartet Euch ein neuer Rang.", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "Ich habe Eure Handlungen mit einem wachsamen Auge verfolgt, {name}. Ihr habt bewiesen, dass Ihr ein unschätzbarer Gewinn für das Drachenmal seid. Daher werde ich Euch zum Aufseher befördern. Ein neuer Rang bedeutet natürlich auch neue Verantwortungen, denen Ihr gerecht werden müsst.\n\nErhebt Euch, Aufseher {name}! Erhebt Euch und sucht diejenigen auf, die Eure Hilfe hier im Basislager brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11054] = { id = 11054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsehen und Ihr: Die richtige Wahl treffen", description = "Ihr seid also der neue Aufseher, was? Tja, es gibt da eine Sache, die jeder gute Aufseher braucht: die richtige Ordnungswaffe. Bevor Ihr dort hinausgehen und diesen Peons etwas Verstand einprügeln könnt, braucht Ihr Eure \"Waffe\". Jeder Aufseher muss die Materialien zur Herstellung seiner eigenen \"Waffe\" sammeln und Ihr seid da keine Ausnahme.\n\nIch benötige Knotenhautleder und den gehärteten Balg von Tyrantus. Ihr findet Tyrantus in der Biokuppel Fernfeld, welche in der nördlichen Gegend des Nethersturms zu finden ist.", sourceObjective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 10 Einheiten Knotenhautleder und 1 gehärteten Balg von Tyrantus bringt.", progress = "Es gilt Peons zur Ordnung zu rufen, {name}! Beeilt Euch!", completion = "Ahh! Vielleicht habt Ihr ja doch das Zeug zum Aufseher. Diese übergroße Echse war schon das Leid vieler Orcs!\n\n<Chefvorarbeiter Lehmklump beginnt mit der Herstellung der Waffe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11055] = { id = 11055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schuhmerang: Das Mittel gegen den wertlosen Peon", description = "Dies hier ist Euer Schuhmerang. Es gibt viele andere, aber dieser ist Eurer.\n\nAls Aufseher werdet Ihr diesen Schuhmerang verwenden, um Furcht in die Herzen aufsässiger Peons zu pflanzen. Der richtige Einsatz des Schuhmerangs wird für Gehorsam und Unterwürfigkeit sorgen.\n\nGeht weit hinaus zu den Kristallfeldern und diszipliniert jeden Peon, den Ihr beim Faulenzen erwischt. Zeigt ihnen die Macht des Schuhmerangs!", sourceObjective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 faule Peons des Drachenmals zur Ordnung ruft. Gebt anschließend auch Euren Schuhmerang wieder zurück.", progress = "Der Trick liegt im Handgelenk, {name}.", completion = "Ein Tag harter Arbeit! Es zahlt sich aber aus, oder? Beim Anblick der schuftenden Taugenichtse bei den Kristallen wird einem richtig Warm um's Herz... Nun ja, das ist alles für heute. Kommt morgen wieder, dann könnt Ihr ein weiteres Mal den Schuhmerang schwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11056] = { id = 11056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazziks Handel", description = "Erwähnt unsere Unterhaltung nicht. Adaris würde nichts davon gutheißen.\n\nIch gehöre der niedrigsten Kaste der Arakkoa an, {name}. Während Terokks Herrschaft hätte man mich den dunklen Mächten geopfert, die von den Krallenpriestern verehrt werden. Sollte was Ihr sagt, wahr sein und sollten die Krallenpriester wirklich Terokks Rückkehr herbeisehnen, dann müsst Ihr dies unbedingt verhindern - ganz egal, was Euer Anführer sagt!\n\nIch habe etwas für Euch, das Ihr sehr nützlich finden werdet. Bei meiner alten Behausung im oberen Shil'akversteck liegt ein Päckchen. Bringt es mir.", sourceObjective = "Sucht nach Hazziks Päckchen bei seiner Behausung im östlichen Skettis und kehrt damit zu ihm zurück.", progress = "{name}, Ihr seid zurück! Ich dachte schon, Ihr hättet mich im Stich gelassen.", completion = "Ausgezeichnet, {name}. Ihr werdet sehen, dass ich mein Wort halte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11057] = { id = 11057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwierigkeiten in der Tiefe", description = "Wir wissen Euren Eifer, uns hier in Ogri'la unterstützen zu wollen, sehr zu schätzen, {class}. Doch bevor wir Euer großzügiges Angebot annehmen können, müssen wir Euch zunächst um einen Gefallen bitten.\n\nUnsere Brüder dort unten sind Sklaven der Söhne von Gruul. Bitte, sprecht mit Mog'dorg dem Weisen. Er ist der Anführer einer Widerstandsbewegung der dort heimischen Oger gegen die Gronn.\n\nIhr findet ihn auf dem Turm, auf der östlichen Seite der Arena des Zirkels des Blutes.", sourceObjective = "Chu'a'lor hat Euch gebeten, mit Mog'dorg dem Weisen zu sprechen. Ihr findet ihn auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11058] = { id = 11058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Apexisrelikt", description = "Vor langer Zeit lebte hier eine Sekte der Arakkoa, die Apexis. Überreste ihrer seit langem ausgestorbenen Zivilisation sind auch heute noch allgegenwärtig. Wir nennen sie Apexisrelikte.\n\nDas Einzige, was wir mit Sicherheit wissen, ist, dass sie bei richtiger Benutzung einen Segen gewähren. Jedes Relikt repräsentiert eine farbige Sequenz, welche, wenn man die Kristalle in der richtigen Reihenfolge drückt, zu einer Serie von Stufen führen, eine schwieriger als die andere.\n\nEs wird ein Apexissplitter benötigt, um das Relikt zu aktivieren. Kehrt zurück, wenn Ihr mehr über die Apexisschwingungen erfahren habt.", sourceObjective = "Kehrt zu Chu'a'lor in Ogri'la hoch oben im Schergrat zurück, sobald Ihr eine Aura der Apexisschwingung von einem Apexisrelikt erlangt habt.", completion = "<Chu'a'lors Köpfe nicken Euch anerkennend zu.>\n\nIhr habt einen scharfen Verstand, {name}. Wir haben erheblich länger gebraucht, um das Relikt erfolgreich zu benutzen.\n\nNun, da Ihr wisst wie, könnt Ihr es so oft Ihr wollt verwenden. Denkt jedoch daran, dass für die Aktivierung eines Relikts immer ein Apexissplitter erforderlich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11059] = { id = 11059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter des Monuments", description = "Ihr habt erfolgreich herausgefunden, wie man die Ein-Personen-Relikte benutzt. Aber wie Ihr wahrscheinlich schon bemerkt habt, umgeben die kleineren noch größere Relikte.\n\nDiese großen Apexismonumente funktionieren auf die exakt gleiche Weise, allerdings werden wesentlich mehr Apexissplitter benötigt, um sie zu aktivieren und vier Personen um sie zu bedienen.\n\nViel größere Sorgen bereiten uns die Wächter, die bei der Benutzung eines Relikts beschworen werden. Diese Kristallkonstrukte haben sich vor langer Zeit gegen ihre Arakkoameister gewendet und gefährden nun Ogri'la.\n\nWir möchten Euch bitten, einen von ihnen zu zerstören und uns einen Beweis Eurer Tat zu bringen.", sourceObjective = "Chu'a'lor hat Euch gebeten, ihm den Kopf eines Apexiswächters als Beweis Eurer Tat zu bringen. Kehrt mit dem Beweis zu ihm nach Ogri'la hoch oben im Schergrat zurück.", progress = "Wir verabscheuen Gewalt, aber wenigstens ist das Konstrukt, das Ihr vernichten sollt, kein lebendiges Wesen.\n\nWo wir schon davon sprechen, habt Ihr den Kopf?", completion = "<Chu'a'lor mustert Euch voller Respekt.>\n\nEure und die geistige Gewandtheit Eurer Freunde ist wahrlich beeindruckend. Dafür, dass Ihr uns und unsere Lebensweise verteidigt habt, stehen wir, nein, stehen ganz Ogri'la und die Himmelswache in Eurer Schuld.\n\nDenkt daran {name}, Ihr könnt jederzeit mit einer Gruppe zurückkehren, um die großen Apexismonumente zu benutzen. Bringt aber genügend Apexissplitter mit, um sie aktivieren zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11060] = { id = 11060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kristallgeschmiedete Rune der Dunkelheit", progress = "Die Dämonen machen das Konstruktionslager: Wut größer. Bald sie zu stark sind und uns vernichten werden. Ihr sie zuerst schlagen müsst!\n\nShartuuls Transporter sein Schlüssel zu Sieg, aber er werden beschützt von magischem Schild und mächtigen Dämon, einem Zerrütter. Wir mächtiger Hexenmeister und wir Euch herstellen werden eine besondere Rune der Dunkelheit, mit der Ihr Zerrütter kontrollieren könnt. {race} geben GahkRune der Dunkelheit, wir geben {race} kristallgeschmiedete Rune der Dunkelheit.\n\nIhr übernehmen den Zerrütter und übernehmen Herrschaft über so viele aus dem Portal kommende Dämonen wie möglich, um sie aufzuhalten!", completion = "Kleiner {race}, nicht vergessen, wenn Ihr einen Zerrütter kontrollieren, Ihr müssen seinen Hammer dazu benutzen, um die Schilde von Warptor zu zerschlagen und den gefangenen Dämonen freizulassen.\n\nDann Ihr müssen zerschlagen diesen Dämon und ihn beherrschen. Dann kommen neuer Dämon, den Ihr auch beherrschen müssen, bis der Aufseher der Eredar auftauchen.\n\nDann Ihr auch ihn erschlagen werdet!!!" }
quests[11061] = { id = 11061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflichten eines Vaters", description = "Was das andere magische Fläschchen angeht, man bekommt es ausschließlich an einem Ort: der Landeplatz von Bash'ir. Es handelt sich um einen Stützpunkt der Astralen und sie sind Fremden gegenüber nicht gerade freundlich eingestellt, daher könnte es etwas gefährlich werden.\n\nSicherlich fragt Ihr Euch jetzt, wo man diesen Landeplatz von Bash'ir findet? Steigt auf Euer fliegendes Reittier und reist in Richtung Nord, Nordosten, bis Ihr ein gutes Stück hinter dem Konstruktionslager: Wut seid, dann müsstet Ihr den besagten Landeplatz sehen. Die Kristallschmiede von Bash'ir befindet sich in der nordöstlichen Ecke des Stützpunkts.\n\nDanke für Eure Hilfe, {name}. Es bedeutet unseren Söhnen alles!", sourceObjective = "Torkus möchte, dass Ihr ihm ein instabiles Fläschchen des Zauberhexers bringt. Bringt es zu ihm in Ogri'la hoch oben im Schergrat.", progress = "Dieses Fläschchen des Zauberhexers wird meine Jungs sicherlich noch intelligenter machen, als sie es ohnehin schon sind. Damit sollten ihnen die täglichen Pflichten in der Himmelswache der Sha'tari etwas leichter fallen.", completion = "Wir können Euch gar nicht genug danken, {name}!\n\nSo instabil diese zwei Fläschchen auch sein mögen, mit ihrer Hilfe können wir nun einen unserer Jungs nach Norden zum Außenposten der Himmelswache schicken.\n\nWartet einen kleinen Augenblick, während wir einen von ihnen rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11062] = { id = 11062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Außenposten der Himmelswache", description = "{name}, wir haben uns gefragt, ob Ihr vielleicht nach Norden aufbrechen würdet, um unseren Freunden beim Außenposten der Himmelswache einen Besuch abzustatten?\n\nKommandant Keller und seine Himmelswache führen zu unserem Schutz diverse Unternehmungen durch und erst kürzlich bat er uns, jeden vorbeizuschicken, der Willens ist, sie bei ihrer Arbeit zu unterstützen.\n\nDas wäret dann wohl Ihr!\n\nBrecht so schnell wie möglich dorthin auf und übermittelt ihnen unsere besten Grüße.", sourceObjective = "Chu'a'lor möchte, dass Ihr mit Himmelskommandant Keller beim Außenposten der Himmelswache hoch oben im Schergrat sprecht.", completion = "Willkommen im Außenposten der Himmelswache. Wisst Ihr, ich habe den gesamten Posten mit meinen eigenen Händen errichtet.\n\nSchon richtig gehört, alles was Ihr hier vor Euch seht!\n\n<Dem Himmelskommandanten scheint es ernst zu sein.>\n\nIhr müsst ja ganz schön scharf auf einen Kampf sein, wenn Ihr extra hierher gekommen seid, um mit mir zu sprechen. Es war nett vom alten Chu'a'lor, Euch vorbeizuschicken. Wir können hier immer etwas Frischfleisch gebrauchen.\n\nWenn es Euch nichts ausmacht, würde ich vorschlagen, Ihr unterhaltet Euch ein wenig mit meinem Himmelsoffizier Vanderlip. Stört Euch nicht an ihrem Gebaren, ihre Zunge ist womöglich schärfer als das Breitschwert, das sie bei sich trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11063] = { id = 11063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich Flügel verdienen...", sourceObjective = "Ihr möchtet also zu den Himmelsteilern gehören, ja? Ihr habt Euch mit Sicherheit als fähiger Anhänger des Drachenmals bewiesen, aber in den Lüften der Scherbenwelt ist dies bedeutungslos. Es gibt eine Frage zu klären: KÖNNT IHR FLIEGEN?\n\nUnd ich frage nicht etwa, ob Ihr auf einen Netherdrachen steigen und wie diese Transportertrottel eine Ladung Kristalle zu der Festung liefern könnt. Ich rede davon, der Beste zu sein... der Toporc...\n\nDort drüben im Westen gibt es sechs Reiter. Besiegt sie alle und ich werde Euch Flügel der Himmelsteiler geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11064] = { id = 11064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Murg \"Grufti\" Moorbiss", description = "Lasst Euch von dem grauen Haar nicht täuschen, Grunzer. Ich bin trotz allem ein zehnmal so guter Reiter! Glaubt bloß nicht, dass dieser Totgesagte keine Tricks mehr im Ärmel hat.\n\nVersucht mir zu folgen und nicht von Eurem Reittier geworfen zu werden, das ist alles. Wenn Ihr das fertig bringt, wird Grufti seine Niederlage eingestehen.\n\nWir heben ab, sobald Ihr bereit seid.", sourceObjective = "Folgt Murg \"Grufti\" Moorbiss und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Murg \"Grufti\" Moorbiss besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ein Kinderspiel? Was ist nur aus den Helden geworden... Ich bin mir sicher, dass die anderen Reiter eine größere Herausforderung sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11065] = { id = 11065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigt ein paar Ätherrochen!", description = "Hey da, wollt Ihr der Himmelswache und Ogri'la etwas aushelfen?\n\nHört mir doch erstmal zu, bevor Ihr einfach davonrennt, <Junge/Mädel>. Wir benötigen dringend mehr Reittiere. Die Missionen und Bombenangriffe auf den Landeplatz von Bash'ir haben uns so manches Reittier gekostet.\n\nDie Ätherrochen, die beim Vortexgipfel und am Kristallrücken herumfliegen, sollten für unsere Zwecke genügen. Ihr müsst sie nicht einmal hierher zurückbringen. Bändigt sie einfach und bindet sie irgendwo an, wir holen sie dann später ab.\n\nSeid Ihr dieser Aufgabe gewachsen?", sourceObjective = "Himmelswache Khatie möchte, dass Ihr 5 Ätherrochen bändigt. Kehrt zu ihr beim Außenposten der Himmelswache hoch oben im Schergrat zurück, wenn Ihr den Auftrag erledigt habt.", progress = "Habt Ihr schon ein paar Ätherrochen gebändigt? Ihr seht so aus, als könntet Ihr mit einem Lasso umgehen. Sicher habt Ihr Euren Auftrag schnell abgeschlossen.", completion = "Juhuu! Gute Arbeit, {name}! Diese Rochen werden ein paar hervorragende Reittiere abgeben!\n\nBleibt ruhig noch ein wenig, die Himmelswache der Sha'tari kann Männer mit Euren Talenten immer gut gebrachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11066] = { id = 11066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigt noch mehr Ätherrochen!", description = "Sicherlich werdet Ihr uns dabei helfen, noch ein paar mehr Ätherrochen zu bändigen! Soweit ich das beurteilen kann, liegt Euch so etwas im Blut!\n\nDas ganze wäre für eine gute Sache, denn so kriegen wir nicht nur frische Reittiere, sondern Ihr helft uns auch noch Ogri'la zu beschützen, wofür Euch die Oger sicher dankbar sein werden.\n\nNicht vergessen, die Ätherrochen fliegen beim Vortexgipfel und am Kristallrücken im Nordosten herum.\n\nSchafft Ihr es, noch ein paar mehr für mich zu bändigen?", sourceObjective = "Himmelswache Khatie möchte, dass Ihr 5 Ätherrochen bändigt. Kehrt zu ihr beim Außenposten der Himmelswache hoch oben im Schergrat zurück, wenn Ihr den Auftrag erledigt habt.", progress = "Ihr leistet hervorragende Arbeit für uns, {name}! Ich möchte Euch nur wissen lassen, dass wir Eure Bemühungen, uns mit frischen Reittieren zu versorgen, sehr zu schätzen wissen!", completion = "Ihr erstaunt mich immer wieder! Ich sage Euch was, warum lasst Ihr das Lasso nicht für heute ruhen und wir sehen uns morgen wieder?\n\n<Khatie lacht.>\n\nNochmals vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11067] = { id = 11067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Trope der Rußhuster", description = "Das Drachenmal behandelt einen richtig, {name}. Selbst so ein ausgelaugtes und gezeichnetes Wesen wie ich bekommt seine Chance. Wenn Ihr Euch den Himmelsteilern als würdig erweisen wollt, dann müsst Ihr mich besiegen.\n\nIch werde Euch wie einen Schwarm lästige Fliegen abschütteln...\n\nWir heben ab, sobald Ihr bereit seid.", sourceObjective = "Folgt Trope dem Rußhuster und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Trope den Rußhuster besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Interessant... Euer nächstes Rennen wird sich zweifellos als viel schwieriger erweisen. Corlok ist kein Weichei.", sourceObjectiveStatus = "unverified-source-field" }
quests[11068] = { id = 11068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Corlok der Veteran", description = "Ihr fordert MICH heraus? Jetzt muss ich aber lachen!\n\nIst das Euer Ernst? Na gut! Achtet lediglich darauf, nicht zu sterben. Ihr schafft das doch, nicht zu sterben, oder?? Auch wenn ich Schädel nach Euch werfe und in Kreisen um Euch und Eure erbärmlichen Flugkünste fliege?\n\nLasst mich einfach wissen, wann's losgehen kann, dann heben wir ab.", sourceObjective = "Folgt Corlok dem Veteranen und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Corlok den Veteranen besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Die nächsten zwei Reiter sind die besten Piloten, die die Zwerge und Orcs von Azeroth zu bieten hatten. Ihr habt keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11069] = { id = 11069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Schwadronskommandant Ichman", description = "Drei Jahre habe ich in diesem Loch zugebracht. Drei Jahre lang war ich Kriegsgefangener des verdammten Frostwolfklans. Ich musste in ihrem Turm sitzen und ihr endloses Gejammer über die Brücke nach Dun Baldar ertragen. Wie \"unfair\" es doch sei, dass bla, bla, bla, bla... Im Krieg gibt es keine Gerechtigkeit! Zur Hölle mit ihnen allen!\n\nIn dem Augenblick, in dem ich befreit wurde, habe ich diesen Ort für immer verlassen und bin hierher gekommen, um ein neues Leben zu beginnen. Mulv und ich konkurrieren jetzt um den Platz des Toporcs. Sollte das auch Euer Ziel sein, dann müsst Ihr erstmal an mir vorbei, Anfänger.\n\nEs geht los, wenn Ihr bereit seid.", sourceObjective = "Folgt Schwadronskommandant Ichman und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Ichman besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ich glaube es nicht! Mulverick ist Eure nächste Herausforderung. Dieses Rennen werdet Ihr auf keinen Fall überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11070] = { id = 11070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Schwadronskommandant Mulverick", description = "Drei Jahre lang Blut, Schweiß und Tränen. Hauptsächlich Tränen... Es ist erstaunlich, wie viele Tränen selbst ein hartgesottener Soldat vergießt, wenn es im Krieg zur Sache geht.\n\n\"Sie springen mit ihren Pferden in unseren Turm!\" \"Warum muss die feindliche Basis so gut verteidigt sein?\" \"Verdammt, der Feind hat die Heilerhütte erobert, ich mache mich vom Acker!\"\n\nVerdammte Feiglinge...\n\nKaum war das Dunkle Portal offen, hab' ich die Möglichkeit beim Schopfe gepackt und mich aus dem Land der Weicheier verabschiedet. Jetzt arbeite ich als Toppilot für die Jungs des Drachenmals. Wenn Ihr also der Toporc werden wollt, müsst Ihr mich erst einmal schlagen.\n\nEs geht los, sobald Ihr bereit seid.", sourceObjective = "Folgt Schwadronskommandant Mulverick und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Mulverick besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Nun Grunzer, es sieht ganz so aus, als gäbe es jetzt nur noch Euch und den Hauptmann. Viel Glück! Ihr werdet es brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11071] = { id = 11071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Hauptmann Himmelsdonner", description = "Ihr wagt es Himmelsdonner herauszufordern? Die Welt um Euch herum wird in Dunkelheit versinken, wenn meine Meteore den Horizont zerreißen.\n\nIhr habt keine Chance, Soldat. Scheinbar ist es jedoch Euer Wunsch zu sterben...\n\nIch werde bei Eurem morbiden Vorhaben mitspielen. Vielleicht kann ich anderen Narren, die nach der gleichen Verrücktheit streben, zumindest eine Lehre erteilen.\n\nWir reiten los, wenn Ihr bereit seid!", sourceObjective = "Folgt Hauptmann Himmelsdonner und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Hauptmann Himmelsdonner besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ich hätte es mir nie träumen lassen, dass es jemanden gibt, der talentiert genug ist und Himmelsdonner besiegen kann. Wisst Ihr was das bedeutet, ja? Ihr seid jetzt der Toporc! Ihr müsst Euren Titel verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11072] = { id = 11072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindesblut", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Karrog der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Benutzt sie bei den Beschwörungskreisen, die es in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mitzunehmen.", sourceObjective = "Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11073] = { id = 11073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Fall", description = "Ich... ich habe bezüglich Eures Verhaltens gegenüber dem Arakkoagefangenen ein Auge zugedrückt, {name}. Es sieht ganz so aus, als hätte Euch Euer Instinkt nicht getäuscht. Es war richtig, mit ihm zusammenzuarbeiten.\n\nBitte versteht... Ich hätte mich in der jetzigen Lage inmitten eines Aufruhrs wiedergefunden, hätte ich Eure Bemühungen, Terokk in diese Welt zu bringen, gebilligt.\n\nNehmt die Gegenstände, die Hazzik für Euch zusammengestellt hat und führt Euren Plan weiter fort. Ich werde meinen Männern befehlen, Euch Rückendeckung zu geben, wenn es an der Zeit dafür ist. Ich rate Euch, auch selbst Verstärkung mit Euch zu bringen. Ich fürchte Ihr habt nur diese eine Chance.", sourceObjective = "Bringt die Zeitverlorene Opfergabe, die Hazzik angefertigt hat, zu dem Schädelhaufen im Zentrum von Skettis. Beschwört Terokk und bezwingt ihn. Habt Ihr Eure Aufgabe erfüllt, kehrt zu Himmelskommandant Adaris zurück.", completion = "Ihr habt uns alle sehr stolz gemacht, {name}. Ich werde die Kunde von Euren Taten in Shattrath verbreiten. Die Himmelswache steht für immer in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11074] = { id = 11074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Nachfahren", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Garogg der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Verbrennt sie bei den Beschwörungskreisen, die es überall in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mit Euch zu bringen.", sourceObjective = "Sammelt zeitverlorene Schriftrollen von den zeitverlorenen Arakkoa in Skettis ein und bringt sie zu den Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört und bezwingt die Nachfahren der Gegner Terokks und kehrt zu Hakkiz mit Akkarais Kralle, Garokks Stachel, Vekkaz' Schuppe und Gezzaraks Klaue zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11075] = { id = 11075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Netherschwingenminen", description = "Wir benötigen Eure Hilfe bei den Netherschwingenminen, Aufseher {name}.\n\nVor zwei Tagen machten wir eine düstere Entdeckung und daraufhin kamen unsere Minenarbeiten zum Stillstand. Ein Minenarbeiter arbeitete in den Tiefen der Mine und hieb seine Hacke in eine ungewöhnliche Kristallformation. Unglücklicherweise war diese Kristallformation mit einem sehr verärgerten Netherdrachen verbunden. Die Bestie erwachte aus ihrem Schlaf und tötete all unsere Arbeiter.\n\nErstattet bei der Herrin der Minen Bericht. Man erwartet Euch beim Eingang der Minen, südwestlich von hier.", sourceObjective = "Sucht die Herrin der Minen auf der Netherschwingenscherbe auf.", completion = "Die Minenarbeiter leisten harte Arbeit, aber keiner von ihnen wagt es, einen Schritt tiefer in die Minen zu setzen. Sie sterben lieber, als dass sie sich tiefer in die Minen zwingen lassen! Es wird Eure Aufgabe sein, die von ihnen vernachlässigten Pflichten zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11076] = { id = 11076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dinge in den Griff bekommen...", description = "Die Mühen unserer harten Arbeit liegen überall in diesen Minen verstreut. Wagenladungen voller Fracht bedecken jeden Zentimeter dieser Mine! Auf Grund der Plage kommen wir nur an nichts von alledem heran.\n\nGenau hier kommt Ihr ins Spiel, {name}. Eure tägliche Arbeit bei der Mine wird aus dem Einsammeln der von den Minenarbeitern und Tiefenminenarbeitern zurückgelassenen Fracht bestehen.\n\nSammelt die Fracht der Netherminen ein und kehrt zu mir oder meiner Schwester zurück.", sourceObjective = "Die Herrin der Minen bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Kisten mit Fracht der Netherminen einsammelt.", progress = "Habt Ihr die Fracht eingesammelt?", completion = "Gut gemacht, {name}. Kommt morgen für einen weiteren Einsatz in den Tiefen der Mine wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11077] = { id = 11077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachen sind unsere geringste Sorge", description = "Als der Drache erwachte, schreckte er in diesen Minen noch ganz andere bösartige Kreaturen auf. Insbesondere zwei Arten sind dem Drachenmal ein Dorn im Auge: Netherminenschinder und Netherminenhetzer. Ihr müsst uns helfen, sie alle zu töten. Ich bitte Euch lediglich einmal pro Tag um Eure Mithilfe.\n\nGeht hinein und vernichtet so viele, wie Ihr nur könnt!", sourceObjective = "Der Vorarbeiter des Drachenmals bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Netherminenschinder und 5 Netherminenhetzer tötet.", completion = "Das sollte für heute reichen, Aufseher. Kommt morgen für eine weitere Aufräumrunde wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11078] = { id = 11078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Himmel beherrschen", description = "Während Ihr herumgeflogen seid, sind Euch sicherlich die Drachen aufgefallen. Schätze, ihr Zorn blieb Euch bisher erspart. Helft uns, diese Biester ein für alle Mal zu erledigen, {name}!\n\nNachtreißer und Obsidia beherrschen dieses Plateau, während Insidion und Zornschwinge den Himmel über den Terrassen im Nordosten für sich beanspruchen. Jeder der Drachen hat ein Nest in seinem Revier gebaut. Ich frage mich, ob Ihr und Eure Freunde genug Mut aufbringt, die Drachen herunterzulocken, indem Ihr eines ihrer Eier aufbrecht.\n\nBringt mir ihre Zähne als Beweis. Es kann nur einer den Himmel beherrschen, entweder sie oder wir!", sourceObjective = "Himmelskommandant Keller hat Euch gebeten, Drachenzähne zu sammeln und sie zu ihm beim Außenposten der Himmelswache hoch oben im Schergrat zurückzubringen.", progress = "Wie geht es voran, {name}? Ich brauche Euch sicherlich nicht extra zu sagen, wie wichtig die ganze Angelegenheit für unsere Luftüberlegenheit ist.", completion = "Ja! Diese Zähne sehen scharf aus, als könnten sie beinahe alles wie Butter durchschneiden!\n\nErlaubt mir, Euch und Eure Freunde dazu zu ermuntern, weiterhin so gute Arbeit zu leisten! Diese Drachen sind gefährliche Raubtiere, die unseren Himmel lange genug unsicher gemacht haben.\n\nEuch sind sicherlich die Drachenschuppen aufgefallen. Wie ich hörte, kann man aus ihnen einen mächtigen Umhang herstellen, sofern man eine Schuppe von jedem der Drachen besitzt. Sollte Euch der Umhang nicht zusagen, bin ich jederzeit bereit, ihn gegen einen Apexiskristall einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11079] = { id = 11079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Teufelspeitsche für Gahk", description = "Gahk manchmal glauben, es nicht gut ist, schlau zu sein. Ghak möchten nicht so viel nachdenken müssen. Ich wollen, dass Ihr große Dämonen totschlagen!\n\nSie haben einige Anführer und jeder von ihnen haben Peitschen, um den mickrigen Dämonen Verstand einzuprügeln. Gahk wollen so eine Peitsche!\n\nDazu Ihr herausfordern müssen einen Dämonenanführer in Konstruktionslager. Einen solchen Ihr finden bei brennenden, grünen kristallinen Teufelsprisma. Benutzen viele Apexissplitter, um sie zu rufen. Sie hören auf Namen wie Galvanoth, Braxxus, Zarcsin und der Verbrenner der Mo'arg.", sourceObjective = "Gahk hat Euch darum gebeten, Ihm eine Teufelspeitsche zu beschaffen. Bringt sie zu ihm in Ogri'la hoch oben im Schergrat.", progress = "Ihr haben Peitsche?", completion = "Gahk mögen Peitsche. Vielleicht Ghak nehmen Peitsche und bearbeiten ein paar Dämonen!\n\nMich sagen zu {race}, dass {race} kann jederzeit beschwören Dämonenanführer, solange {race} haben viele Freunde und 'ne Menge Splitter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11080] = { id = 11080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strahlung des Relikts", description = "Nachdem Ihr die erleuchtenden Schwingungen der Apexisrelikte am eigenen Leib erfahren habt, ist es an der Zeit, ein tieferes Verständnis für die Funktionsweise der Relikte zu bekommen. Wir würden von Euren Beobachtungen profitieren.\n\nJe mehr Eure Fähigkeiten wachsen, Euch auf die Kräfte der Relikte einzustellen, desto mehr Wissen werdet Ihr über sie erlangen. Ist es erst einmal soweit, wird Euch ein Strahlungsausstoß des Relikts Euren Erfolg anzeigen.\n\nKehrt zu uns zurück, wenn Ihr eine solche Strahlungsaura erlangt habt.", sourceObjective = "Chu'a'lor hat Euch gebeten, zu ihm in Ogri'la hoch oben im Schergrat zurückzukehren, sobald Ihr eine Aura der Apexisstrahlung von einem Apexisrelikt erlangt habt.", completion = "Euer Geschick im Umgang mit den Relikten erstaunt uns immer wieder, {name}. Dürften wir Euch vorschlagen, mindestens einmal am Tag den Gebrauch der Relikte zu üben, damit Euer Verstand seine Schärfe bewahrt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11081] = { id = 11081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Aufstand der Finsterblut", description = "Dieses Schriftstück beschreibt einen von den Zerschlagenen der Finsterblut geplanten Aufstand. Scheinbar diente der Drache der allgemeinen Zerstreuung, um von ihrer Flucht abzulenken. Beim Betrachten der überall in der Mine herumliegenden Leichen, könnte man von einem Fehlschlag ihres Plans ausgehen.\n\nBringt die Fluchtpläne zur Herrin der Minen.", sourceObjective = "Bringt die Fluchtpläne der Finsterblut zur Herrin der Minen.", progress = "Was ist das?", completion = "Ausgezeichnete Arbeit, Aufseher. Man wird Mor'ghor von Euren herausragenden Taten für das Drachenmal berichten.\n\nLasst uns jetzt wieder auf diese Hunde der Finsterblut zu sprechen kommen. Sie planen ihre Flucht, ja? Sie wagen es, sich dem einzig wahren Fürsten der Scherbenwelt zu widersetzen? Ihre Meister werden dafür bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11082] = { id = 11082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Wahrheit", description = "Diese Minenarbeiter sind viel zu dumm, als dass sie irgendeinen Fluchtplan aushecken könnten. Wir müssen die Quelle des Übels finden und bestrafen. Wagt Euch in die Tiefen der Minen und sucht nach den Aufpassern der Finsterblut. Wenn sie nicht schon von den Bewohnern der Minen überwältigt wurden, so halten sie sich zweifellos versteckt.\n\nSolltet Ihr einen von ihnen ausfindig machen, verhört ihn so lange, bis er das wahre Gehirn, das hinter diesem Fluchtplan steckt, preisgibt. Kehrt mit der Identität des Verräters und der Hand des Aufpassers zu mir zurück.", sourceObjective = "Findet einen Aufpasser der Finsterblut und verhört ihn. Kehrt mit den Informationen der Finsterblut und mit der Hand des Aufpassers zur Herrin der Minen zurück.", progress = "Nun? Warum dauert das so lange?", completion = "Nichts zu sagen? Vielleicht erinnert er sich ja, wenn er auf dem Boden dieser verfluchten Mine zu Tode blutet... Vergesst nie, was es bedeutet, die Mächte Illidans herauszufordern!", sourceObjectiveStatus = "unverified-source-field" }
quests[11083] = { id = 11083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückt und verwirrt", description = "Sorgt Euch nicht wegen diesem Drachen, {name}. Wir haben bereits Pläne für ihn...\n\nTiefer in der Mine gibt es eine verrückte Schar der Finsterblut. Nachdem der Drache ausgebrochen ist, wurde ihnen der Weg zum Ausgang versperrt. Nach zwei Tagen der Abgeschiedenheit scheinen sie auf irgendeine Art und Weise jegliche Würde verloren zu haben.\n\nSie haben sich dem Kannibalismus und der Gewalt verschrieben. Dieser Wahnsinn ist hier alles andere als erwünscht. Findet und tötet sie. Alle!", sourceObjective = "Ronag der Sklaventreiber in den Netherschwingenminen im Schattenmondtal möchte, dass Ihr den verrückten Großknecht der Finsterblut und 5 verrückte Minenarbeiter der Finsterblut tötet.", completion = "Ja, ich verstehe das nicht... Man würde doch meinen, dass sie nach zwei Tagen nicht derart ausgehungert sein können. Finsterblut...\n\n<Ronag schüttelt den Kopf.>\n\nSowas von dämlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[11084] = { id = 11084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid gegrüßt, Hauptmann!", description = "Nun sieh einer an... Ihr lebt also noch. Das trifft sich gut, denn Mor'ghor hat nach Eurer sofortigen Anwesenheit in seinem Turm verlangt. Los mit Euch!", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "<Mor'ghor nickt.>\n\nGanz recht, ich habe Hauptmann gesagt. Ihr habt Euch eine weitere Beförderung verdient, {name}.\n\nIhr arbeitet wirklich wie keiner der Höllenorcs, die ich bis jetzt gesehen habe. Macht weiter so, dann schafft Ihr es vielleicht eines Tages zum Oberanführer.\n\nZieht jetzt los und übernehmt das Kommando. Ich schlage vor, dass Ihr versucht, Euch Eure Flügel der Himmelsteiler zu verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11085] = { id = 11085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Skettis", description = "Seid gegrüßt, {name}. Ich danke Euch, dass Ihr mir zur Hilfe gekommen seid.\n\nIch war auf einer Erkundungsmission, als mich die riesigen Vögel der Arakkoa von meinem Netherrochen rissen.\n\nVerschwinden wir von hier, solange es noch geht!", sourceObjective = "Begleitet die gefangene Himmelswache in Sicherheit und meldet Euch anschließend bei Himmelsoffizier Doryn.", completion = "Danke, dass Ihr unseren Späher gerettet habt, {name}. Jeden Tag verlieren wir gute Leute und es kommen beileibe nicht genug Rekruten nach, um sie alle zu ersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11086] = { id = 11086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwächt das Portal des Zwielichts", description = "Als Hauptmann des Drachenmals liegt es in Eurem Verantwortungsbereich, sämtliche Unternehmungen der Brennenden Legion in der Scherbenwelt auszulöschen. Es ist Eure Pflicht, die zum Schweigen zu bringen, die sich Fürst Illidan widersetzen!\n\nDie Dämonen versuchen törichterweise das Portal auf der Zwielichthöhe im Westen von Nagrand zu stabilisieren. Sie müssen für ihren Verrat bezahlen. Ihr werdet der Orc sein, der für die Begleichung ihrer Schulden sorgt.\n\nReist zur Zwielichthöhe und vernichtet die dortigen Bewohner. Ihr seid dafür verantwortlich, täglich mindestens einen Angriff auf ihre Stellungen durchzuführen.", sourceObjective = "Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 Agenten der Todesschatten tötet.", completion = "Ausgezeichnete Arbeit, Hauptmann! Fürst Illidan wird von Euren Heldentaten erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[11087] = { id = 11087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flagge von Hyjal", description = "Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.\n\nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.", sourceObjective = "Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11089] = { id = 11089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelenkanone Reth'hedrons", description = "Reth'hedron herrscht jetzt über die Zwielichthöhe in Nagrand. Ein Eredar von solch großer Macht, der auf diese Welt losgelassen wurde, verheißt nichts Gutes für die Illidari. Ach, uns fehlt es einfach an den benötigten Ressourcen, um Reth'hedron vernichten zu können. Schon gar nicht mit dem Krieg, den diese Bastarde zum Schwarzen Tempel getragen haben. Nein... ich habe einen besseren Plan.\n\nIhr werdet Reth'hedron unterdrücken, ihn zurück durch das Portal des Zwielichts verbannen. Für diesen Zweck muss eine Seelenkanone angefertigt werden.\n\nKehrt zu mir mit den Materialien auf der Liste zurück.", sourceObjective = "Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 2 Teufelsstahlbarren, 1 Adamantitrahmen, 1 Khoriumkraftkern und 1 makellose arkane Essenz bringt.", progress = "Habt Ihr die benötigten Bauelemente für die Anfertigung der Seelenkanone?", completion = "<Balthas fügt die Elemente, die Ihr ihm gebracht habt, geschickt zusammen.>\n\nIhr seid jetzt bereit für den zweiten Teil des Plans, Hauptmann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11090] = { id = 11090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterdrückt den Unterdrücker", description = "<Balthas hält ein fremdartiges Gerät in die Höhe.>\n\nDies ist eine Seelenkanone. Die Auswirkungen können bei der richtigen Abstimmung verheerend sein. Diese ist auf mein Blut abgestimmt. Dasselbe Blut, das auch durch die Adern von Reth'hedron fließt - meinem Bruder. Ja, seine falsche Loyalität wird sein Ende sein.\n\nNehmt die Kanone und fliegt zur Zwielichthöhe im westlichen Nagrand. Findet Reth'hedron und feuert! Ihr müsst auf Eurem Reittier bleiben und Euch in Reichweite befinden, damit die Auswirkungen erfolgreich sind. Behauptet Euch ihm gegenüber und er wird keine andere Wahl haben als zu fliehen!", sourceObjective = "Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal hat Euch den Auftrag gegeben, die Seelenkanone auf Reth'hedron den Unterdrücker in Nagrand anzuwenden.\n\nBringt auch die Seelenkanone wieder zurück.", progress = "Ist es vollbracht?", completion = "Er wird zurückkehren, aber für den Moment hat der Krieg der Legion gegen Fürst Illidan eine Schwäche erfahren. Man wird ihm von Euren Taten berichten, Hauptmann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11091] = { id = 11091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Dank an Euch", description = "Die in unserem Namen auf Euch genommenen Anstrengungen ehren uns. Es gibt da jemanden, den Ihr unbedingt kennenlernen solltet.\n\nJho'nass ist unser bester Rüstmeister. Er verwaltet eine ganze Reihe von auserlesenen Waren, die nur den engsten Verbündeten von Ogri'la zum Kauf angeboten werden.\n\nIhr seid ein solcher Verbündeter, {name}.\n\nWenn Ihr etwas Zeit erübrigen könnt, solltet Ihr ihn unbedingt aufsuchen. Soweit wir wissen, hat er, als Zeichen unserer Dankbarkeit, eine Kleinigkeit für Euch vorbereitet.", sourceObjective = "Chu'a'lor hat vorgeschlagen, dass Ihr mit Jho'nass in Ogri'la hoch oben im Schergrat sprecht.", completion = "Hey, Mann, das ist toll! Wir haben viel von Euren guten Taten gehört. Das ist fantastisch. Wir haben da so ein Gefühl, dass Ihr für Ogri'la alles zum Guten wenden werdet. Ihr werdet uns beschützen und alles wird heiter und sonnig!\n\nHier, nehmt das. Es ist ein kleines Überlebenspaket, dass wir zum Dank für Euch zusammengestellt haben.\n\nWerft doch bitte einen Blick auf unsere Waren. Wir haben eine reichhaltige Auswahl der erlesensten Gegenstände, von denen Euch sicherlich das eine oder andere Stück interessieren wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11092] = { id = 11092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück auf, Kommandant!", description = "Hauptmann {name}!\n\n<Zuchtmeister Varkule grüßt Euch.>\n\nOberanführer Mor'ghor möchte, dass Ihr Euch umgehend bei ihm meldet!", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "Fürst Illidan hat mich höchstpersönlich mit Eurer Beförderung zum Kommandanten beauftragt! So etwas hat es noch nie gegeben. Ihr seid der Erste des Drachenmals, der solch einen Rang außerhalb des Schwarzen Tempels erlangt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11093] = { id = 11093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Netherrochen", description = "Hat man einen Netherrochen erst einmal richtig gezähmt, dann ist er ein loyales und gehorsames Reittier. Unglücklicherweise beansprucht der Krieg bei Skettis unsere Netherrochen über Gebühr.\n\nTäglich müssen wir dutzende von Einsätzen fliegen, sodass die armen Tiere kaum zur Ruhe kommen. Und seit uns auch noch das Futter ausgegangen ist, können die armen Biester froh sein, wenn sie einer der Vogelmenschen erledigt, bevor es der Hunger tut.\n\nWenn Ihr uns zur Hand gehen wollt, nehmt Euch einen unserer Rochen und führt ihn in die Wälder im Süden aus. Sie essen das Fleisch der dort lebenden Schattenwindhetzer, vorausgesetzt, man hat sie gerade frisch erlegt.", sourceObjective = "Benutzt den Netherrochenkäfig in den Wäldern südlich des Schattenwindlagers und erlegt in der Nähe des hungrigen Netherrochens einige Schattenwindhetzer. Kehrt anschließend zu Deesak dem Tierführer der Himmelswache zurück.", progress = "Ihr seid also zurück! Hat sich der Rochen auch gut benommen?", completion = "Vielen Dank {name}, dass Ihr Euch um den Rochen gekümmert habt. Mit vollem Magen fliegen diese Burschen gleich viel besser. Schließlich sollen unsere Jungs nicht abgeschossen werden, nur weil ihre Netherrochen zum Fliegen zu schwach waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11094] = { id = 11094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Kommandant {name}, stillgestanden! Ihr werdet mit einem Bataillon von Himmelsteilern losziehen und den Außenposten der Seher am Fuße der Netherschwingenfelder ausradieren. Ist das Sanktum der Sterne erst einmal zerstört, stehen uns die Verbindungswege zu unseren Posten bei der Stätte der Mondfinsternis und bei der Stätte der Illidari erneut wieder offen.\n\nLos jetzt! Benutzt diese Leuchtpistole, um den Himmelsteilern das Zeichen zum Angriff zu geben!", sourceObjective = "Überbringt Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals.", progress = "Beruhigt Euch, Kind.", completion = "Es war gut, dass Ihr zu uns gekommen seid. Vielleicht können wir diesen Angriff des Drachenmals zu unserem Vorteil nutzen und den Spieß umdrehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11095] = { id = 11095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Hobb", description = "Das Drachenmal wagt es nur dann, uns anzugreifen, wenn unsere Abwehr geschwächt ist. Sie hätten einige Niederlagen hinzunehmen, wenn wir auf ihre Angriffe vorbereitet wären.\n\nIch möchte, dass Ihr sie zu uns führt, {name}.\n\n<Thelis nickt.>\n\nJa... in eine Falle. Nehmt die Leuchtpistole, die Euch ihr Oberanführer gegeben hat, und bringt sie zu Kommandant Hobb. Er steht direkt außerhalb dieses Gebäudes Wache.", sourceObjective = "Bringt die Leuchtpistole des Drachenmals zu Kommandant Hobb beim Sanktum der Sterne im Schattenmondtal.", progress = "<Hobb nickt.>", completion = "<Hobb grinst.>\n\nDie tödlichste Falle aller Zeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[11096] = { id = 11096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "So, Ihr wollt also der Himmelswache beitreten? Nun, ich weiß, dass Ihr fliegen könnt, aber vermögt Ihr auch zu kämpfen?\n\nDie Himmelswache hat einst geschworen, Shattrath vor allen drohenden Gefahren, egal ob nah oder fern, zu schützen. Die bei der Hügelwand im Norden lebenden Oger der Gordunni stellen eine unmittelbare Bedrohung für uns dar.\n\nEs erwies sich als sehr schwer für unsere Bodentruppen, die Oger zu erreichen. Hier kommen wir ins Spiel. Seht was Ihr tun könnt, um die Oger im Zaum zu halten.", sourceObjective = "Tötet bei der Hügelwand 20 Oger der Gordunni und kehrt anschließend zu Yuula in Shattrath zurück.", completion = "Gute Arbeit, Fliegerass! Ich habe das Gefühl, dass Ihr hier sehr gut hineinpasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11097] = { id = 11097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die tödlichste Falle aller Zeiten", description = "Nehmt diese Medaillen der Seher. Mor'ghor wird einen Siegesbeweis sehen wollen, wenn all das hier vorüber ist. Er wird sie als Beute von den gefallenen Soldaten der Seher wiedererkennen.\n\nJetzt gilt es noch das Leuchtsignal abzufeuern, um die Räuber des Drachenmals herbeizurufen. Sobald Ihr bereit seid, werden wir sie niederschmettern. Gebt mir einfach den Befehl.", sourceObjective = "Helft Kommandant Hobb und den Sehern bei der Verteidigung des Sanktums der Sterne. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Seher zurück.", progress = "Habt Ihr sie mit Euren Fäusten zerschmettert, Kommandant?", completion = "<Mor'ghor lacht.>\n\nHAHA! Ich habe gewusst, dass ich auf Euch zählen kann, Kommandant! Ich möchte, dass Ihr das Sanktum der Sterne mindestens einmal pro Tag überfallt. Sie werden keine andere Wahl haben und das Schattenmondtal verlassen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11098] = { id = 11098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Skettis!", description = "Die Hügelwand ist nur eine der vielen Fronten, an denen wir eingesetzt werden. Eine nicht unmittelbare, aber dennoch sehr große Bedrohung lauert hinter den Skethylbergen, in Form der Arakkoastadt Skettis.\n\nVor einigen Monaten entdeckten unsere Späher dort einen massiven Anstieg der Arakkoaaktivitäten. Daraufhin erfolgte eine ganze Reihe von Angriffen auf Shattrath. Seitdem haben wir einige unserer Streitkräfte außerhalb ihrer Stadt stationiert.\n\nNehmt diese Sprengladungen und bringt sie zu Himmelsoffizier Doryn beim Schattenwindlager außerhalb von Skettis. Sagt ihm einfach, Ihr wäret <der neue Rekrut/die neue Rekrutin>.", sourceObjective = "Bringt das Paket mit Sprengladungen zu Himmelsoffizier Doryn beim Schattenwindlager außerhalb von Skettis.", progress = "Ihr habt etwas für mich?", completion = "Danke für den Nachschub, wir werden ihn zu verwenden wissen! Ein neuer Rekrut? Dann wollen wir doch mal sehen, aus welchem Holz Ihr geschnitzt seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[11099] = { id = 11099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Kommandant {name}, stillgestanden! Ihr werdet mit einem Bataillon von Himmelsteilern losziehen und den Außenposten der Aldor nordwestlich unseres geliebten Schwarzen Tempels ausradieren. Ist der Altar der Sha'tar erst einmal zerstört, stehen uns die Verbindungswege zu unseren Posten bei der Echsennarbe erneut wieder offen.\n\nLos jetzt! Benutzt diese Leuchtpistole, um den Himmelsteilern das Zeichen zum Angriff zu geben!", sourceObjective = "Überbringt Anachoret Ceyla beim Altar der Sha'tar die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals.", progress = "Beruhigt Euch, Kind.", completion = "Es war gut, dass Ihr zu uns gekommen seid. Vielleicht können wir diesen Angriff des Drachenmals zu unserem Vorteil nutzen und den Spieß umdrehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11100] = { id = 11100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Arcus", description = "Das Drachenmal wagt es nur dann, uns anzugreifen, wenn unsere Abwehr geschwächt ist. Sie hätten einige Niederlagen hinzunehmen, wenn wir auf ihre Angriffe vorbereitet wären.\n\nIch möchte, dass Ihr sie zu uns führt, {name}.\n\n<Ceyla nickt.>\n\nJa... in eine Falle. Nehmt die Leuchtpistole, die Euch ihr Oberanführer gegeben hat, und bringt sie zu Kommandant Arcus. Er steht direkt außerhalb dieses Gebäudes Wache.", sourceObjective = "Bringt die Leuchtpistole des Drachenmals zu Kommandant Arcus beim Altar der Sha'tar im Schattenmondtal.", progress = "<Arcus nickt.>", completion = "<Arcus grinst.>\n\nDie tödlichste Falle aller Zeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[11101] = { id = 11101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die tödlichste Falle aller Zeiten", description = "Nehmt diese Medaillen der Aldor. Mor'ghor wird einen Siegesbeweis sehen wollen, wenn all das hier vorüber ist. Er wird sie als Beute von den gefallenen Soldaten der Aldor wiedererkennen.\n\nJetzt gilt es noch das Leuchtsignal abzufeuern, um die Räuber des Drachenmals herbeizurufen. Sobald Ihr bereit seid, werden wir sie niederschmettern. Gebt mir einfach den Befehl.", sourceObjective = "Helft Kommandant Arcus und den Aldor bei der Verteidigung des Altars der Sha'tar. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Aldor zurück.", progress = "Habt Ihr sie mit Euren Fäusten zerschmettert, Kommandant?", completion = "<Mor'ghor lacht.>\n\nHAHA! Ich habe gewusst, dass ich auf Euch zählen kann, Kommandant! Ich möchte, dass Ihr den Altar der Sha'tar mindestens einmal pro Tag überfallt. Sie werden keine andere Wahl haben und das Schattenmondtal verlassen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11102] = { id = 11102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomberangriff", description = "Ihr könnt also wie eine Krähe herumfliegen... ja und! Schon mal etwas am Boden ausradiert, während Ihr geflogen seid? Lust, es mal zu probieren?\n\nDas Konstruktionslager: Wut und das Konstruktionslager: Terror, im Norden und im Süden, sind mir schon seit langem ein Dorn im Auge und eine Gefahr für Ogri'la. Mit all diesen Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nehmen, gibt es einfach kein Hindurchkommen und unser Unterfangen ist zum Scheitern verurteilt.\n\nWürdet Ihr Euch gerne unter Beweis stellen? Nehmt diese Bomben und vernichtet ihre Munitionsvorräte. Lasst Euch aber nicht auch noch vom Himmel herunterholen!", sourceObjective = "Himmelsoffizier Vanderlip hat Euch mit der Bombardierung von 15 Stapeln mit Teufelskanonenkugeln beauftragt. Kehrt zu ihr beim Außenposten der Himmelswache hoch oben im Schergrat zurück, wenn Ihr den Auftrag erledigt habt.", progress = "Habt Ihr schon ihre Stapel mit Teufelskanonenkugeln vernichtet?", completion = "Gut, gut, scheinbar seid Ihr doch härter im Nehmen als ich dachte. Ausgezeichnete Arbeit. Möglicherweise hatte der alte Keller doch Unrecht, was Euch anbelangt.\n\n<Himmelsoffizier Vanderlip grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11103] = { id = 11103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Weise", progress = "Man kann die Kräfte Eures Ringes neu formen, doch wird es nicht einfach, Eure Auswahl rückgängig zu machen. Seid Ihr sicher, dass Ihr seine momentane Form durch eine andere ersetzen möchtet?", completion = "Es ist ein Leichtes, die Sande der Zeit vorwärts fließen zu lassen. Man kann den Fluss auch umkehren, doch ist dies mit großen Mühen verbunden." }
quests[11104] = { id = 11104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Weise", progress = "Man kann die Kräfte Eures Ringes neu formen, doch wird es nicht einfach, Eure Auswahl rückgängig zu machen. Seid Ihr sicher, dass Ihr seine momentane Form durch eine andere ersetzen möchtet?", completion = "Es ist ein Leichtes, die Sande der Zeit vorwärts fließen zu lassen. Man kann den Fluss auch umkehren, doch ist dies mit großen Mühen verbunden." }
quests[11105] = { id = 11105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Held" }
quests[11106] = { id = 11106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Verteidiger" }
quests[11107] = { id = 11107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verneigt Euch vor dem Hochlord", description = "Ich bin der Überbringung einer an Euch gerichteten Nachricht nicht einmal würdig, Sire. Bitte verzeiht dieses ungebührliche Benehmen. Oberanführer Mor'ghor möchte, dass Ihr Euch umgehend bei ihm meldet!", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "Ihr seid der erste Hochlord des Drachenmals, {name}. Der Meister hat beschlossen höchstpersönlich hierher zu kommen, um Euch zu befördern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11108] = { id = 11108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürst Illidan Sturmgrimm", description = "Kommt, Hochlord {name}. Illidan höchstpersönlich erwartet Euch!", sourceObjective = "Trefft Euch mit Illidan Sturmgrimm. Solltet Ihr überleben, sucht Barthamus im unteren Viertel von Shattrath auf.", completion = "Ich war der Erste, wisst Ihr. Das verlassene Kind eines Monsters...\n\n<Barthamus schüttelt seinen Kopf.>\n\nWir haben Euch alles zu verdanken, {name}. Ganz allein habt Ihr das Reich des Drachenmals zerschmettert und dabei genug Informationen gesammelt, die meine Brüder mehr als ein Leben lang beschäftigen werden.\n\nEs ist zwar nicht viel, aber es gibt da etwas, das wir Euch anbieten können... Ein jeder meines Schwarms hat sich dazu bereit erklärt, Euch bei Euren Abenteuern in der Scherbenwelt zu begleiten. Fragt sie einfach und sie werden mit Euch einen Bund eingehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11109] = { id = 11109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorus, der kobaltblaue Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11110] = { id = 11110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfas, der lila Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11111] = { id = 11111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyxien, der onyxfarbene Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11112] = { id = 11112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suraku, der azurblaue Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
