quests[11114] = { id = 11114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoya, der viridiangrüne Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11115] = { id = 11115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal von Vashj" }
quests[11116] = { id = 11116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: (QUEST FLAG)", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr für den Schlüssel der Stürme als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!\n\nWenn Ihr dies erledigt habt, werdet Ihr den Schlüssel der Stürme bekommen.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11117] = { id = 11117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt die wilden Wolpertinger!", description = "Da, jetzt. Habt Ihr's gehört? Diese Geräusche in den Hügeln. Das sin' die Wolpertinger! Gerissene Biester sin' das, angelockt vom Duft des Braufests. Ich würd' mir ja gern' ein paar davon fangen, aber ich hab' mir mein Bein aufgeschlagen und kann diese Viecher einfach nich' einholen. Tja, da könnt Ihr mir helfen!\n\nNehmt dieses Netz und werft's über diese kleinen Teufel. Bringt mir fünf der Biester und ich werd' Euch für Eure Mühe belohnen! Oh, eine Sache noch - um die Viecher überhaupt sehen zu können, müsst Ihr gut was intus haben! Hopfen und Malz, ab in den Hals!", sourceObjective = "Goldark Spatzenjäger möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr einen ordentlichen Rausch braucht, um die Biester sehen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11118] = { id = 11118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parade der rosa Elekks", description = "Sich zu betrinken, ist eine altehrwürdige Tradition auf dem Braufest - es ist schon fast eine Bedingung! Die Sache ist die. Mir wurde berichtet, dass die Feierlichkeiten in ganz Azeroth von Halluzinationen überschattet werden! Das können wir nicht zulassen!\n\nNormale Waffen können diesen Elekks nichts anhaben - sie gehen einfach durch sie hindurch. Nehmt daher dieses fantastische Stück gnomischer Maschinenbaukunst, reist zu den anderen Biergärten und zappt sie ins Nichts. Vergesst nicht, Ihr müsst betrunken sein, um sie sehen zu können!", sourceObjective = "Reist zu den Biergärten außerhalb von Sturmwind, Darnassus und der Exodar, zappt an jedem Ort drei Elekks und kehrt anschließend zu Goldark Spatzenjäger zurück. Um die rosa Elekks sehen zu können, müsst Ihr betrunken sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11119] = { id = 11119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Landeplatz von Bash'ir!", description = "Hey, <Junge/Mädel>! Auf der Suche nach etwas Spaß?\n\nAlle paar Stunden starten meine Äthertechniker einen Angriff auf den Landeplatz von Bash'ir tief im Nordosten des Schergrats. Sie bestehen darauf, dass sie Bash'irs Kristallschmiede nur 'erforschen', aber egal wie man es dreht, es ist eigentlich nichts anderes, als ein Überfall. Wir benutzen die Kristallschmiede, um uns mit neuer Ausrüstung zu versorgen und meistens bleibt noch genug übrig, um einen guten Gewinn herauszuschlagen.\n\nGeht 'runter zur Landebahn und sprecht mit dem Äthertechnikerlehrling. Er wird Euch sagen können, wann der nächste Einsatz stattfindet.", sourceObjective = "Himmelskommandant Keller hat Euch gebeten, mit dem Äthertechnikerlehrling beim Außenposten der Himmelswache im Schergrat zu sprechen.", completion = "Egal, was Keller dazu meint, ich bevorzuge es, unsere Einsätze als Forschungsexkursionen zu betrachten.\n\nEs stimmt allerdings, dass wir dort Vorräte für die Himmelswache beschaffen, jedenfalls, wenn wir lange genug dort bleiben können.\n\nIhr seht so aus, als wäret Ihr bereit, uns den Rücken gegen die Astralen freizuhalten. Wenn Ihr uns die Astralen lange genug vom Leib haltet, werden wir Euch alle zusätzlich an der Kristallschmiede hergestellten Gegenstände zum Verkauf anbieten, also bringt Eure Apexissplitter und Kristalle mit!\n\nWir ziehen in 0 |4Minute:Minuten; los.", sourceObjectiveStatus = "unverified-source-field" }
quests[11120] = { id = 11120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parade der rosa Elekks", description = "Schaut doch, wir verdienen hier unser Geld. Betrunkene Leute? Das ist ein ziemlich gutes Geschäft. Es gibt da allerdings eine Sache, die einem die Umsätze völlig vermiest - Halluzinationen. Ich sag's Euch, meine Jungs berichten mir, dass die Saufbo-, äh, ehrenwerten Kunden überall rosa Elekks sehen.\n\nIch kann keine beunruhigten Kunden gebrauchen. Hier, nehmt das, reist zu den anderen Biergärten und kümmert Euch für mich um die Angelegenheit, ja? Achtet darauf, dass Ihr betrunken seid!", sourceObjective = "Reist zu den Biergärten außerhalb von Silbermond, Donnerfels und Unterstadt, zappt an jedem Ort drei Elekks und kehrt anschließend zu Glodrak Jägerspatz zurück. Um die rosa Elekks sehen zu können, müsst Ihr betrunken sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11122] = { id = 11122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin und zurück", description = "Ihr wollt also beim Braufest aushelfen? Ich habe die perfekte Aufgabe für Euch. Ich werde Euch auf einen meiner Rennwidder setzen und nach Kharanos reiten lassen. Es gibt da ein paar Fässchen, die ich abholen muss. \n\nFlynn Feuerbräu wartet auf einem Hügel neben einem Stapel mit Fässchen. Sobald Ihr nahe genug seid, wird er Euch ein Fässchen zuwerfen. Dann eilt Ihr wieder hierher zurück und werft es Pol Bernruh zu. Ihr könnt immer nur ein Fässchen gleichzeitig tragen. \n\nSeid Ihr bereit?", sourceObjective = "Holt ein Fässchen von Flynn Feuerbräu in Kharanos und bringt es zu Pol Bernruh zurück. Macht das Ganze dreimal, bevor Euer Widder verschwindet.", completion = "Vielen Dank für Eure Hilfe! Solange das Braufest noch im Gange ist und die Dunkeleisenzwerge immer wieder angreifen, brauche ich Hilfe bei der Auslieferung der Fässchen. Wenn Ihr Euch noch mehr Marken verdienen wollt, dann kommt jeden Tag wieder zu mir.\n\nSo, jetzt muss ich Euch erst einmal für Eure Arbeit bezahlen. Hier sind Eure Biermarken, viel Spaß auf dem Braufest!", sourceObjectiveStatus = "unverified-source-field" }
quests[11123] = { id = 11123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Der arme James, er ist nie ganz über die Zerstörung des Gasthauses Zur süßen Ruh und den Tod seiner Familie hinweggekommen. Die Jungs und ich versuchen unser Bestmögliches, um die Schweinehunde, die dafür verantwortlich sind, zu finden.\n\nIch habe unseren besten Ermittlungsbeamten, Inspektor Tarem, zu den Ruinen geschickt. Einer allein wird mit dieser Aufgabe aber wohl kaum fertig werden. Wir würden es wirklich zu schätzen wissen, wenn Ihr Tarem helfen würdet. Beim Licht, wir würden alle gern da draußen sein und mithelfen.\n\nDie Hauptstraße führt Euch direkt zum Gasthaus, aber seid vorsichtig, auf Eurer Reise seid Ihr auf Euch selbst gestellt. Meine Soldaten können Euch keinen Schutz bieten.", sourceObjective = "Sprecht mit Inspektor Tarem beim Gasthaus Zur süßen Ruh.", completion = "Es freut mich, dass Hauptmann Mumm endlich auch andere mit dieser Untersuchung beauftragt.\n\nIch habe diesen Bereich mit reflektierendem Puder abgestaubt. Verdächtige Gegenstände und Hinweise werden dadurch sichtbar. Ihr könnt Euch also wesentlich leichter auf Eure Bemühungen konzentrieren. Seht Euch alles an, was der Staub zum Leuchten gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11124] = { id = 11124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Wenn Ihr der Straße vom Dorf aus nach Süden und dann westlich in Richtung Brachland folgt, werdet Ihr auf die Ruinen des Gasthauses Zur süßen Ruh stoßen.\n\nTheramore hat einen Ermittlungsbeamten entsendet, um herauszufinden, von welchem Schicksal das Gasthaus heimgesucht wurde. Normalerweise würden wir uns aus dieser Sache heraushalten, aber wir haben von Orgrimmar den Befehl erhalten, bei dieser Untersuchung Hilfestellung zu leisten.\n\nNehmt jegliche Hilfe entgegen, die der Ermittler von Theramore zu bieten hat. Wenn Ihr wollt, könnt Ihr ihm auch den ein oder anderen Hinweis geben. Eure wahren Ergebnisse darf aber nur ich erfahren.", sourceObjective = "Sprecht mit Inspektor Tarem beim Gasthaus Zur süßen Ruh.", completion = "<Der Inspektor betrachtet Euch mit Misstrauen.>\n\nMan hat mir gesagt, dass Ihr mir bei dieser Untersuchung... helfen werdet. Nun gut.\n\nIch habe dieses Puder verwendet, um die Ruinen nach Hinweisen abzusuchen, die uns beim Identifizieren der Täter behilflich sein könnten. Der Staub bringt alles zum Leuchten, was bei dem Überfall eine Rolle gespielt hat. Nur zu, untersucht alles, was verdächtig erscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[11126] = { id = 11126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter unter uns", description = "Schön Euch zu sehen, {class}. Ich bin nach Theramore gekommen, um bei der Lösung des Problems mit den Deserteuren zu helfen. Einige der Männer haben nicht nur ihren Posten verlassen, nein, sie haben sich zurück in die Stadt geschlichen.\n\nDiese Agenten der Deserteure verbreiten Lügen und Propaganda. Sie erhoffen sich davon, andere von ihrer Sache zu überzeugen, damit sie sich ihnen anschließen.\n\nSie sind nahezu bei jedem Wachposten der Stadt und bei den Docks. Findet sie, entlarvt sie und diskreditiert sie. Im Moment würde alles andere nur dazu führen, dass sie an Sympathie gewinnen.", sourceObjective = "Konfrontiert 5 Aufwiegler der Deserteure und kehrt zu Calia Hastings nahe der Docks in Theramore zurück.", completion = "Gut gemacht, {name}. Ich glaube, wir haben sie überrascht. Ihre Agenten wähnten sich innerhalb der Stadt vermutlich in Sicherheit.\n\nMit der Zeit werden die Aufwiegler zurückkehren und ihre Lügen wieder verbreiten. Wir werden die Zeit, die Ihr uns verschafft habt, nutzen, um die Deserteure weiter auszusperren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11128] = { id = 11128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propagandakrieg", description = "Die Agenten der Deserteure haben weitaus mehr getan, als nur die Wachen zu beschwatzen. Wir haben eine Reihe von Handzetteln gefunden, die die Deserteure scheinbar auf einem Schiff zu den Docks geschmuggelt haben.\n\nDas Schiff, auf dem die Handzettel geladen waren, liegt noch immer in Theramore bei dem am weitesten entfernten Dock vor Anker. Wenn Ihr Euch heimlich an Bord schleichen und das restliche Propagandamaterial in Beschlag nehmen könntet, würden die Agenten ihre wichtigste Waffe verlieren. Seid auf der Hut! Das Schiff ist mit erfahrenen Freibeutern bemannt und die Fracht befindet sich womöglich in der Kabine des Kapitäns.", sourceObjective = "Bringt das Propagandamaterial der Deserteure zu Calia Hastings nahe der Docks in Theramore.", progress = "Konntet Ihr die Propagandahandzettel finden und in Beschlag nehmen?", completion = "<Die SI:7-Agentin nickt zustimmend.>\n\nAusgezeichnet. Jetzt müssen wir die Deserteure nur noch diskreditieren, damit sie in Theramore nie wieder Fuß fassen können. Ich weiß auch schon wie.", sourceObjectiveStatus = "unverified-source-field" }
quests[11129] = { id = 11129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyle wird vermisst!", description = "Helft mir, {name}! Mein geliebter Hund Kyle ist mir weggelaufen. Ich weiß nur, dass er irgendwo in der Nähe des Dorfes der Bluthufe einsam und hungrig herumstreunt.\n\nWürdet Ihr ihn für mich finden und füttern? Wenn er erst einmal etwas gefressen hat, wird er sich wieder beruhigen und nach Hause zurückkehren.\n\nUm ihn zu füttern, müsst Ihr etwas zu Essen finden. Schreiterfleisch mag er besonders gerne. Geht einfach Richtung Osten, dort solltet Ihr genügend Schreiter finden. Erlegt einen und bringt sein saftiges Fleisch zu Kyle. Wenn Ihr Kyle im Dorf antrefft, müsst Ihr das Fleisch nur auf den Boden legen und er wird zu Euch kommen.", sourceObjective = "Ahab Weizhuf beim Dorf der Bluthufe in Mulgore möchte, dass Ihr seinen geliebten Hund Kyle den Wilden füttert.\n\nFüttert Kyle mit zartem Schreiterfleisch und kehrt anschließend zu Ahab Weizhuf zurück.", completion = "Gut gemacht, {name}! Nachdem er gefressen hatte, kam Kyle sofort nach Hause und hat sich schlafen gelegt. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11130] = { id = 11130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es glitzert!", description = "Nur keine Scheu, <Mann/Süße>! Lasst den alten Gaunah mal einen Blick auf Eure Klunker werfen...\n\nHmm. Ja, nicht schlecht, aber das Zeug könnte besser sein. Viel, viel besser.\n\n<Gaunah kommt näher und flüstert.>\n\nSchätze von unschätzbarem Wert lassen sich überall finden, {name}, man muss nur wissen wo! Heute ist Euer Glückstag! Ich kenne da einen Typen, der Euch zu mehr Reichtümern verhelfen kann, als Ihr jemals tragen könntet.\n\nStattet meinem alten Kumpel Budd in der Nähe von Zul'Aman einen Besuch ab und zeigt ihm das hier. Sagt ihm, dass der alte Gaunah Euch geschickt hat, dann wird er Euch bei seinem neuen Projekt mit einsteigen lassen.", sourceObjective = "Gaunah möchte, dass Ihr Gaunahs Notiz zu Budd in den Geisterlanden, direkt außerhalb von Zul'Aman, bringt.", progress = "<Budd beäugt die Notiz misstrauisch.>\n\nWas habt Ihr da, {class}?", completion = "<Budd liest die Notiz.>\n\nAhh! Ein Freund von Gaunah? Willkommen!\n\nIhr kommt genau richtig, mein Freund. Wie es das Schicksal so will, habe ich gerade erst meine Kollegen verloren. Tragisch, wirklich, aber außergewöhnliche Belohnungen haben oft ihren Preis. Lasst uns nicht zu sehr ans Negative denken!\n\nIhr habt sicherlich schon von meinen zahlreichen Ausbeuten und Entdeckungen gehört. Nun, das war alles nichts im Vergleich zu dem hier! Ich sage es Euch, wir sind nahe dran, hier in Zul'Aman Geschichte zu schreiben. Ihr hattet das Glück, rechtzeitig zu kommen, um auf der untersten Ebene dabei zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[11131] = { id = 11131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht das Feuer!", description = "Ihr müsst uns helfen! Der kopflose Reiter greift das Dorf an. Überall brennen Feuer! Die Kinder sind nicht mehr in Sicherheit!\n\nBitte, {name}, schließt Euch der Brandwache an. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund, der näher bei den Flammen steht, weiterreichen. Wenn Ihr alle Feuer löscht, könnt Ihr uns vielleicht noch retten!", sourceObjective = "Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", progress = "{name}, Ihr hattet geschworen, die Kinder zu retten!", completion = "Oh, vielen Dank! Möge das Licht Eure guten Taten segnen, gutherziger Herr. Der kopflose Reiter wirft zwar noch immer seinen bedrohlichen Schatten voraus, aber das Dorf ist jetzt erst einmal vor seinen Flammen sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[11132] = { id = 11132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versprechen, Versprechen...", description = "Meine Theorien bestätigen die Gerüchte, dass in Zul'Aman sagenhafte Schätze zu finden sind. Das bedeutet Reittiere und Anwesen für alle!\n\nNun ja, eins nach dem anderen. Ihr müsst Euch Euren Anteil natürlich verdienen...\n\nUnsere anfänglichen Bemühungen haben uns hier doch nicht so weit gebracht, wie ich es mir erhofft hatte. Tatsächlich sieht es so aus, dass meine Karte, und die Tagelöhner, denen ich sie geliehen habe, verschwunden sind. Sie sind aufgebrochen, um einen Troll namens Nalorakk zu jagen. Ich kann zwar die Gruppe ersetzen, aber ich brauche diese Karte!\n\nSolltet Ihr diese Aufgabe bewältigen, dann wird man von Euch sagen, dass Ihr derjenige wart, der Budd Winterhäldler geholfen hat, die Geheimnisse von Zul'Aman zu lüften!", sourceObjective = "Budd Winterhäldler in den Axthügeln möchte, dass Ihr bei Hohepriester Nalorakks Terrasse in Zul'Aman nach seiner Karte sucht.", progress = "Ah, wenn das nicht {name} ist!\n\nHabt Ihr meine Karte ausfindig gemacht?", completion = "<Budd scheint etwas geschockt zu sein.>\n\nOh? Ihr habt sie gefunden?\n\nÄhm, ich meine, natürlich habt Ihr das! Gut gemacht, {class}.\n\nLasst mal sehen, ob ich etwas Kleines für Euch habe... ahh, ja, das könnte passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11133] = { id = 11133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskreditierung der Deserteure", description = "Ich habe die Handzettel, die Ihr den Söldnerkumpanen der Deserteure beim Dock abgenommen habt, verfälscht. Jeder, der diese Zettel jetzt lesen wird, erhält mit Sicherheit einen ganz anderen Eindruck von den Deserteuren und ihren Absichten.\n\nWenn wir genug davon an die Wachen verteilen, wird es den Deserteuren einfach zu peinlich sein, hier jemals  wieder Fuß zu fassen.\n\n<Calia überreicht Euch einen Stapel verfälschte Handzettel.>\n\nFangt doch schon einmal an, während ich den nächsten Schritt plane.", sourceObjective = "Calia Hastings möchte, dass Ihr verfälschte Handzettel an 6 Wachen von Theramore verteilt. Erstattet ihr anschließend Bericht nahe der Docks in Theramore.", progress = "Ich dachte, ich hätte Gelächter bei den Kasernen gehört. Habt Ihr die Handzettel verteilt, die ich Euch gegeben habe?", completion = "<Calia kichert, als Ihr von der Reaktion der Wachen auf das Propagandamaterial berichtet.>\n\nGenau wie ich gehofft hatte! Ich bin mir sicher, dass jeder Agent der Deserteure, der versucht Theramore zu infiltrieren, sofort ausgelacht wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[11134] = { id = 11134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Deserteure", description = "Jetzt, da wir die Deserteure aus Theramore vertrieben haben, ist es an der Zeit, unseren Plan zu Ende zu bringen. Meine Kontakte vor Ort haben mir berichtet, dass die Operationsbasis der Deserteure ein Schiff ist, das bei einer kleinen Insel südöstlich der Docks vor Anker liegt.\n\nDie Festnahme ihres Anführers, Gavis Grauschild, wird die anderen entmutigen. Macht ihn innerhalb des Schiffs ausfindig und überzeugt ihn davon, zu kapitulieren. Es würde mich nicht überraschen, wenn er sich mit einem spektakulären Kampf zur Wehr setzt, aber aufgibt, sobald er verstanden hat, dass er nicht gewinnen kann.", sourceObjective = "Nehmt Gavis Grauschild gefangen und erstattet anschließend Bericht bei Calia Hastings nahe der Docks in Theramore.", completion = "Gavis' Forderung ist nicht so haarsträubend wie sie scheint. Wenn man sie richtig behandelt, gelingt es Lady Jaina vielleicht sogar die Deserteure wieder in unsere Gemeinschaft zu integrieren. Doch diese Entscheidung obliegt alleine ihr.\n\nEs war mir eine große Freude mit Euch zu arbeiten, {name}! Ohne Eure Hilfe wäre die gesamte Operation sicherlich nicht halb so glatt gelaufen. Ich werde Euch in meinem Bericht an Sturmwind lobend erwähnen, so dass alle wissen, dass es Euer Einsatz war, der der Bedrohnung durch die Deserteure ein Ende gesetzt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11135] = { id = 11135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kopflose Reiter", description = "Der kopflose Reiter wurde zwar vertrieben, aber solange die Schlotternächte noch andauern, wird er wiederkehren. {name}, befreit uns von diesem Leid und dem wahnsinnigen Treiben des Kopflosen. Stellt Euch dem Reiter, wenn er und sein Kopf vereint sind, und vernichtet ihn!\n\nEr haust tief im unglückseligen Kreuzgang des Scharlachroten Klosters in Tirisfal. Findet seinen Kürbisschrein und sprecht diese Worte:\n\n Erhebe dich, Reiter\n Deine Zeit ist gekommen\n Heut' Nacht sei dein Leben\n Auf ewig genommen!\n\nGeht, {name}. Möge das Licht Euch immer beistehen.", sourceObjective = "Sucht nach dem Kürbisschrein des kopflosen Reiters.", completion = "Der Ursprung dieses Schreins ist unbekannt, aber es besteht kein Zweifel, wem hier gehuldigt wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[11136] = { id = 11136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Berichte", description = "Unsere Spähpatrouillen haben in letzter Zeit Beunruhigendes zu Tage gefördert. Sie berichten von Männern mit roten Kopftüchern der Defias, die entlang der Schreckensmoorküste nördlich von Theramore umherwandern.\n\nWrackteile in dieser Gegend lassen darauf schließen, dass es sich um Überlebende eines Schiffbruchs handelt, aber uns mangelt es an Informationen. Hauptmann Wymor bei der Späherwacht, einem Wachturm nördlich der Stadt, sucht nach einem Helfer, der diesen Berichten nachgeht.", sourceObjective = "Erstattet Hauptmann Wymor bei der Späherwacht Bericht.", completion = "<Der Hauptmann versucht ganz offensichtlich Eure Fähigkeiten einzuschätzen.>\n\nIhr habt also von dem Schiffswrack an der Küste gehört? Gut, ich könnte noch etwas Hilfe gebrauchen, um meinen Verdacht gegenüber den Überlebenden zu bestätigen. Willkommen an Bord, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11137] = { id = 11137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in den Düstermarschen?", description = "Meine Späher haben von einem Schiffswrack nahe des Strands im Nordosten berichtet. Schiffswracks sind hier draußen zwar nichts Ungewöhnliches, aber den Berichten zufolge tragen die Überlebenden auch alle rote Kopftücher!\n\nDie Defias sind Handwerker und Zunftgenossen, keine Seefahrer. Was haben sie bei einem Schiffswrack auf einem Kontinent, der sie nicht interessiert, zu suchen?\n\nMan sagt, ihr Anführer residiert auf einer großen Insel, die nicht weit von der Küste entfernt, nordöstlich des Turms liegt. Tötet ihn und nehmt alle Dokumente an Euch, die Ihr in seinem Besitz findet.", sourceObjective = "Besorgt Euch die Befehle der Defias von Garn Mathers und bringt sie zu Hauptmann Wymor bei der Späherwacht.", progress = "Konntet Ihr ihren Anführer finden?", completion = "<Hauptmann Wymor nimmt die Befehle von Euch entgegen und liest sie.>\n\nWas in aller Welt könnte mit 'Kostbare Fracht' gemeint sein? Die Defias haben zwar kleinere Schmuggeleien im Land von Sturmwind betrieben, aber dies hier ist ganz offensichtlich eine Nummer zu groß für sie. Die Sprache in diesen Befehlen lässt auf einen wohlhabenden oder adligen Herren schließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11138] = { id = 11138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "Die von Euch erlangten Befehle weisen darauf hin, dass die Defias besonders erpicht darauf sind, ihre Fracht auszumachen und zu bergen.\n\nDer SI:7 arbeitete rund um Theramore eine Zeit lang mit dem Bergungstaucher Renn McGill zusammen. Als er von dem Schiffswrack erfuhr, machte sich Renn sofort auf den Weg nach Norden, um in der Nähe der Inseln, die von den Defias besetzt werden, zu tauchen.\n\nWenn wir vor den Defias an die Fracht gelangen wollen, werden wir seine Hilfe benötigen. Haltet in den Gewässern nordöstlich einer kleinen Insel nach ihm Ausschau. Sie liegt im Norden der Insel, die Ihr zuvor schon einmal besucht habt.", sourceObjective = "Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe der Schreckensmoorküste.", progress = "Seid gegrüßt, {class}. Was führt Euch hierher?", completion = "<Renn sieht sich die Befehle an.>\n\nEs war also eine kostbare Fracht an Bord! Wir müssen sie finden, bevor sie von den Defias geborgen wird. Diese Kerle sind zwar keine Taucher, aber wir werden Teile ihrer Ausrüstungen benötigen, wenn Ihr mir bei der Bergung der Fracht behilflich sein wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11139] = { id = 11139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauchausrüstung aus zweiter Hand", description = "Zwischen hier und der Insel Alcaz liegen zahlreiche Wrackteile auf dem Meeresgrund. Die Defias haben bereits Taucher entsandt, die die Gewässer absuchen. Mit Hilfe einiger ihrer Ausrüstungsteile könnten wir Euch so ausstatten, dass Ihr Euch der Jagd anschließen könnt. Ihr müsstet allerdings erst einen Weg finden, wie Ihr an diese \"Leihgabe\" kommt.\n\nSucht diese Insel nach einer Kiste mit einer Tauchausrüstung und etwas zum Reparieren ab. Wenn Ihr das Material gefunden habt, bringt es zu mir und ich werde es in null Komma nichts einsatzbereit machen!", sourceObjective = "Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in den Düstermarschen.", progress = "Mal sehen, was Ihr Euch von den Defias \"borgen\" konntet.", completion = "Na super, die Ausrüstung ist in einem weitaus schlimmeren Zustand, als ich befürchtet hatte... und das Werkzeug!\n\nNun gut, ich habe Euch versprochen, das Ganze wieder funktionstüchtig zu machen, also fange ich mal besser mit der Arbeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[11140] = { id = 11140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Nun, ich konnte die Ausrüstung so reparieren, dass Ihr eine Weile damit tauchen könnt. Allerdings würde ich das Ganze nicht allzu lange auf die Probe stellen.\n\nDie Wrackteile des Schiffs sind auf dem Meeresgrund zwischen der Ostküste dieser Insel und der Insel Alcaz verstreut. Solange dieser Tauchhelm funktioniert, solltet Ihr versuchen, Teile des Wracks auszumachen. Verwendet diese Bergungsausrüstung, um die Wrackteile nach Spuren der Fracht zu durchsuchen. Gebt Acht, dass Ihr der Insel Alcaz nicht allzu nahe kommt. Diese Hydras sind gefährlich.", sourceObjective = "Bringt 6 geborgene Geldkassetten zu Renn McGill in den Düstermarschen.", progress = "Konntet Ihr bei Eurer Suche nach Wrackteilen etwas über die Fracht der Defias herausfinden?", completion = "<Renn durchstöbert den Inhalt der Geldkassetten, die Ihr geborgen habt.>\n\nGute Arbeit. Mal sehen, ob wir Eure 'Kostbare Fracht' hier drin finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[11141] = { id = 11141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina muss davon erfahren", description = "Ihr müsst Lady Jaina sofort von Eurem Fund berichten! Wenn die Defias einen Gefangenen an Bord hatten, dann stellt sich die Frage, wer es war und ob diese Person noch am Leben ist!\n\nEines ist jedoch sicher, {name}. Die Defias würden all diese Schwierigkeiten nicht aus bloßer Gehässigkeit auf sich nehmen. Ihr Gefangener muss jemand von Wichtigkeit sein. Lady Jaina kann mit Sicherheit mehr als jeder andere mit diesen Fundstücken anfangen. Ihr findet sie hoch oben im Magierturm im Zentrum von Theramore.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", completion = "Ihr und Renn habt ausgezeichnete Arbeit geleistet. Danke, dass Ihr diese Informationen ans Licht und sofort zu mir gebracht habt. Es bestehen keine Zweifel, die Defias haben einen finsteren Plan ausgeheckt und wollen gegen Sturmwind und seine Verbündeten vorgehen. Der Aufwand dieses Unterfangens übersteigt alle bisherigen Operationen der Defias. Sie müssen irgendwo einen wohlhabenden Gönner haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11142] = { id = 11142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtet die Insel Alcaz", description = "Scheinbar hatte Renn mit seinen Vermutungen über die Insel Alcaz Recht. Wir müssen diese Insel beobachten. Um dort hinein zu kommen, bräuchten wir allerdings eine ganze Brigade von Soldaten.\n\nTheramores Verteidigung könnte einen derartigen Schlag nicht überstehen, also habe ich mich mit Cassa Purpurschwinge, dem Greifenmeisterlehrling von Theramore, abgesprochen. Sie wird uns eines ihrer Tiere für die Beobachtung der Insel Alcaz aus der Luft überlassen.\n\nDie Insel birgt den Schlüssel zu den Plänen der Defias. Wir müssen herausfinden, was sie mit dem Gefangenen vorhaben... und vielleicht auch wer es ist.", sourceObjective = "Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten. Sprecht mit Lady Jaina Prachtmeer in Theramore, wenn Ihr die Beobachtung abgeschlossen habt.", completion = "<Lady Jaina hört sich Euren Bericht über die Beobachtung aufmerksam an.>\n\nEin Runenkreis, Drachkin? Die Defias haben mit Sicherheit unabhängige Magier in ihren Reihen, aber niemanden, der mächtig genug wäre, um von derartigen Dingen Gebrauch zu machen!\n\nWarum sollten schwarze Drachkin Interesse an einer Insel voller Naga haben? Es gibt viele unbeantwortete Fragen, aber eines ist sicher: die Defias haben einen mächtigen Verbündeten aus den oberen Rängen der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[11143] = { id = 11143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entscheidende Grimmweis", description = "Ich habe mich mit Inspektor Tarem über die Beweise, die Ihr bei den Ruinen des Gasthauses Zur süßen Ruh gefunden habt, unterhalten. Er ist sich sicher, dass die Hufabdrücke und der Schild auf den Taurenklan der Grimmtotem hindeuten.\n\nBedenkt man die jüngsten Berichte über die zunehmenden Aktivitäten der Grimmtotem in den Marschen, so handelt es sich sicherlich nicht um einen Zufall. Bitte geht und sprecht mit Hauptmann Darill, er ist so eine Art Experte in Sachen Grimmtotem. Folgt der Straße aus dem Dorf Richtung Norden zur Nordwacht. Es ist der zweite Außenposten entlang der Straße.", sourceObjective = "Erstattet Hauptmann Darill bei der Nordwacht Bericht.", completion = "Hauptmann Mumm vermutet, dass die Grimmtotem hinter der Zerstörung des Gasthauses Zur süßen Ruh stecken? Sie würden zwar auf meiner Liste der Verdächtigen nicht ganz oben stehen, aber wenn Hauptmann Mumm Euch hierher geschickt hat, um dieser Spur nachzugehen, dann wird er schon seine Gründe haben. Wie dem auch sei, die Grimmtotem sind uns schon seit einer ganzen Weile ein Dorn im Auge und wir freuen uns über jede Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11144] = { id = 11144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestätigung des Verdachts", description = "Die Grimmtotem sind vielleicht der kriegerischste Klan der Tauren, aber sie sind keineswegs unorganisiert. Sollten sie das Gasthaus Zur süßen Ruh wirklich in Brand gesteckt haben, dann nur auf Befehl von einem der Klanältesten.\n\nIm Nordwesten liegt eine große Siedlung der Grimmtotem, das Dorf der Schwarzhufe. Sie haben sie als Ausgangsbasis für ihre Angriffe auf den Turm genutzt, ich bin mir jedoch ganz sicher, dass Ihr dort auch die Befehle finden werdet. Sucht bei den Ältesten im Dorf nach dem Verbleib der Pläne.", sourceObjective = "Bringt die Schlachtpläne der Grimmtotem zu Hauptmann Darill bei der Nordwacht.", progress = "Konntet Ihr die Pläne aufspüren?", completion = "<Hauptmann Darill wirft einen Blick auf die Schlachtpläne.>\n\nIch würde sagen, das ist eindeutig genug. Sie haben sich dazu entschlossen, die Siedlungen der Menschen hier in dieser Gegend zu bekämpfen. Ich bin überzeugt, dass Theramore ihr nächstes Ziel ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11145] = { id = 11145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Grimmtotem", description = "Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.\n\nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, {class}, aber bringt mir meine Männer lebend zurück.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 5 Gefangene von Theramore befreit.", completion = "Die befreiten Gefangenen kehren bereits aus dem Dorf der Schwarzhufe zurück. Die Informationen, die sie dem Hauptmann geben können, werden uns im nächsten Kampf gegen die Grimmtotem einen Vorteil verschaffen.\n\nIhr habt meinen Dank und den meiner Männer.", sourceObjectiveStatus = "unverified-source-field" }
quests[11146] = { id = 11146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenfänger", description = "Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.\n\nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. Ich an Eurer Stelle würde sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 6 Raptoren einfangt. Ihr könnt entweder Blutsumpfraptoren oder Blutsumpfkreischer einfangen.", progress = "Habt Ihr diese Raptoren schon eingefangen?", completion = "Scheint, als hättet Ihr ein paar Kratzer abbekommen! Auf jeden Fall seid Ihr in einer wesentlich besseren Verfassung als es die Grimmtotem sein werden, nachdem wir unsere neuen Raptorenfreunde auf sie losgelassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11147] = { id = 11147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Raptoren los", description = "Jetzt, da wir unsere Raptoren haben, besteht unser nächster Schritt darin, sie für einen Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu \"animieren\".\n\nIch habe hier noch eine übriggebliebene Lende von einem... nun, eigentlich ist es ja auch völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren werden sich um den Rest kümmern.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr den Raptorenköder bei der Windmühle im Dorf der Schwarzhufe platziert.", completion = "<Der Unteroffzier versucht erst gar nicht sein Grinsen zu unterdrücken.>\n\nGut, damit werden sie wohl den einen oder anderen Überfall aussetzen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11148] = { id = 11148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Grimmtotem", description = "Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager im Nordwesten.\n\nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen. Ausgehend von der Größe ihrer Angriffstrupps, schätzen wir jedoch, dass sich dort eine größere Streitmacht aufhält.\n\nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.", sourceObjective = "Hauptmann Darill bei der Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", progress = "Habt Ihr die Waffen im Dorf der Schwarzhufe erbeuten können?", completion = "<Hauptmann Darill inspiziert die Waffen, die Ihr ihm aus dem Dorf der Schwarzhufe gebracht habt.>\n\nEs gibt keinen Zweifel, sie entsprechen genau der Beschreibung. Allerdings gibt es da ein Problem - diese Waffen wurden nie im Kampf eingesetzt. Das Dorf der Schwarzhufe scheint nicht der einzige Posten der Grimmtotem in den Marschen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11149] = { id = 11149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Unterstützung", description = "Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich wüsste aber jemanden, der Euch behilflich sein könnte.\n\nTief im Morast, im Süden, liegt ein kleines Gehöft, das Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und angesehene Wahrsagerin. Folgt der Straße Richtung Süden bis zu ihrem Hof und bittet sie, Euch bei der Suche nach den Tätern, die für das Massaker beim Gasthaus Zur süßen Ruh verantwortlich sind, zu helfen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof.", completion = "Ihr wollt also, dass ich die Grimmtotem ausfindig mache, ja? Was würdet Ihr sagen, wenn ich der Meinung bin, dass das nicht nötig ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[11150] = { id = 11150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus Zur süßen Ruh niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", sourceObjective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Ich hoffe, dass die Grimmtotem die Botschaft verstanden haben. Jeglicher Versuch, hier wieder aufzukreuzen, wird mit weit mehr als nur einer Fackel bestraft. Dafür werden meine Schüler und ich sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11151] = { id = 11151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit im Namen der Familie Hyal", description = "Die Grimmtotem waren zwar lediglich eine Plage für mich, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus Zur süßen Ruh verantwortlich sind, gefunden und bestraft habt.\n\nEs ist zwar zu spät, um Jim Hyals Familie zu retten, aber vielleicht denken die Grimmtotem demnächst zweimal nach, bevor sie jemanden aus Theramore angreifen.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.", completion = "<Der Hauptmann hört sich Euren Bericht aufmerksam an.>\n\nWir haben James und seine Familie gerächt, aber selbst das kann den angerichteten Schaden nicht ersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11152] = { id = 11152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich Frieden", description = "Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder der Gerechtigkeit überantwortet wurden.\n\n<Hauptmann Mumm fertigt einen kleinen Blumenkranz an.>\n\nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Steine auf dem Friedhof genau nördlich der Tore von Theramore.", sourceObjective = "Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.", completion = "<Hauptmann Mumm lächelt, als ihr ihm von den Ereignissen beim Grab der Familie Hyal berichtet.>\n\nEs ist gut zu wissen, dass sie es verstehen. Ihr habt ihnen doch nichts von James erzählt, oder?\n\nIch werde ihm die Nachricht von seiner Frau überbringen lassen, aber ich bezweifle, dass er es verstehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11156] = { id = 11156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuber des Grollhornpostens", description = "Die Grimmtotem beim Grollhornposten im Norden werden mit jedem Tag dreister. In der Nacht kann man sie oft von ihren Taten singen hören, wie sie diejenigen vertrieben haben, die sich hier niederlassen wollten.\n\nSie haben fest vor, uns von Tabethas Hof zu vertreiben, obwohl sie schon Generationen von Schülern hier ausgebildet hat. Wir haben den Hof so gut es geht verteidigt, aber Lehrling Garion wurde bei dem letzten Angriff verletzt.\n\nGeht zum Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Die Überfälle müssen ein Ende nehmen.", sourceObjective = "Tötet 12 Grimmtotem des Grollhornpostens und kehrt zu Lehrling Morlann auf Tabethas Hof zurück.", completion = "<Lehrling Morlann nickt.>\n\nGut. Wie sagt man so schön? Ich werde ihre Gesellschaft nicht missen. Inmitten des Sumpfs würde man sich normalerweise etwas Zurückgezogenheit wünschen, oder nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[11158] = { id = 11158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsumpffedern", description = "Überrascht Euch Broggs Anwesenheit, {race}? Keine Sorge! Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könntet es auch werden.\n\nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für die Zerstörung unserer alten Heimat und den Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierher gekommen, um die Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe. Für das Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus dem Blutsumpfbau.", sourceObjective = "Bringt 5 Blutsumpffedern zu Brogg in Morastwinkel.", progress = "<Brogg sieht Euch hoffnungsvoll an.>\n\nHabt Ihr Federn für Brogg?", completion = "<Brogg nimmt die Federn entgegen.>\n\nBrogg ist zufrieden mit diesen Federn. Starke Magie. Brogg weiß nicht, wie die Raptoren sie mit Macht erfüllen, doch Raptorenfedern sind für Rituale immer am besten geeignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11159] = { id = 11159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Steinbrecherfeste", description = "Brogg hat das Totem fertig gestellt, mit dem Ihr den Geistern seiner Freunde Frieden geben könnt. Als die Drachkin über uns herfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok'Morokk. Seitdem hoffte er auf einen gemeinsamen Gegenangriff aller überlebenden Steinbrecher.\n\nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher im Norden. Verwendet es in der Nähe von Ogerskeletten, um ihre Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.", sourceObjective = "Brogg in Morastwinkel möchte, dass Ihr 10 Geister der Steinbrecher tötet, um sie so ihrer letzten Ruhe zu überantworten.", progress = "Brogg muss wissen, ob Ihr den aufgebrachten Geistern der Steinbrecher Frieden geschenkt habt?", completion = "Brogg ist für Eure Hilfe sehr dankbar, auch wenn es Oberanführer Mok'Morokk wohl nie sein wird. Wenigstens können sich die verbliebenen Steinbrecher jetzt auf die Probleme der Lebenden konzentrieren und die Toten ruhen lassen. Jetzt gibt es für Brogg nur noch eine Sache zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11160] = { id = 11160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Banner der Steinbrecher", description = "Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.\n\nBrogg weiß, dass das Banner tief im Ogerhort, dem heutigen Flammenbau, aufbewahrt wurde. Brogg braucht das Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben.\n\nDer alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Das Banner befindet sich tief in der Höhle. Seid vorsichtig, {name}.", sourceObjective = "Beschafft das Banner der Steinbrecher und bringt es Brogg in Morastwinkel.", progress = "Habt Ihr das Banner der Steinbrecher?", completion = "Ihr habt Broggs Dank, {name}. Brogg hat mit dem Klanbanner noch große Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[11161] = { id = 11161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz der Feindschaft", description = "Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.\n\nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leiche an. Denkt daran, dass nur tote Drachkin ihre Essenzen freigeben!\n\nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.", sourceObjective = "Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.", progress = "Habt Ihr die Essenzen? Brogg braucht sie, um seine toten Freunde zu rächen!", completion = "Ihr habt Broggs Dank, {name}. Wenn Brogg erst einmal ihre Magie dem Totem hinzugefügt hat, kann er endlich die Geister seiner gefallenen Freunde erlösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11162] = { id = 11162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung für den schwarzen Drachenschwarm", description = "Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. {name}, Ihr habt mir sehr dabei geholfen, mich auf diesen Moment vorzubereiten. Werdet Ihr mir auch weiterhin zur Seite stehen?\n\nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr auf eine Höhle trefft, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.\n\nBrogg und die Steinbrecher werden Ihr Land zurückerobern!", sourceObjective = "Stellt das Banner der Steinbrecher nahe des Eingangs zu Onyxias Hort auf, wartet auf ihre Reaktion und kehrt anschließend zu Brogg in Morastwinkel zurück.", progress = "Broggs Rache ist nahe!", completion = "<Brogg hört Euch aufmerksam zu, während Ihr ihm die Geschehnisse am Eingang zu Onyxias Hort schildert.>\n\nBrogg vermutete schon, dass Onyxia zu feige ist, um sich Euch persönlich entgegenzustellen. Sie ist keinen Deut besser als der schwarze Drachenschwarm, der auch nur angreift, wenn der Sieg schon sicher ist.\n\nBrogg ist Euch für Eure Hilfe sehr dankbar, {name}, und er wird nie vergessen, was Ihr für ihn getan habt. Brogg wird weiterhin dafür kämpfen, dass die Steinbrecher zurückerobern, was rechtmäßig ihnen gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[11163] = { id = 11163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agentin mit Herz", description = "<Donna sieht sich um und beginnt zu flüstern.>\n\n{name}, was ich Euch jetzt erzähle, muss streng vertraulich bleiben, verstanden?\n\nIch wurde von den Friedensbewahrern von Shattrath hierher entsandt, um mich in Budds Bande einzuschleusen. Ich muss gestehen, dass Ihr seit Eurer Ankunft mein Interesse geweckt habt und wohl einer meiner Hauptverdächtigen wart. \n\nAllerdings haben Eure Taten Euch von jeglichem Verdacht befreit. Tatsächlich werde ich Euch sogar dafür belohnen müssen, dass Ihr den wahnsinnigen Kriegsherrn Zul'jin bezwungen habt.", sourceObjective = "Meldet Euch bei Donna Brascoe, um eine Belohnung für Euer Heldentum in Zul'Aman zu erhalten. Donna hält sich momentan in den Geisterlanden, direkt außerhalb von Zul'Aman auf.", completion = "<Donna sieht sich um und beginnt zu flüstern.>\n\n{name}, was ich Euch jetzt erzähle, muss streng vertraulich bleiben, verstanden?\n\nIch wurde von den Friedensbewahrern von Shattrath hierher entsandt, um mich in Budds Bande einzuschleusen. Ich muss gestehen, dass Ihr seit Eurer Ankunft mein Interesse geweckt habt und wohl einer meiner Hauptverdächtigen wart. \n\nAllerdings haben Eure Taten Euch von jeglichem Verdacht befreit. Tatsächlich werde ich Euch sogar dafür belohnen müssen, dass Ihr den wahnsinnigen Kriegsherrn Zul'jin bezwungen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11164] = { id = 11164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger der verlorenen Hauer", description = "Hey Mann! Ihr seid neu hier, oder? Könnt Ihr mir 'nen Gefallen tun?\n\nBudd will seiner Waldtrollverkleidung den letzten Schliff verpassen. Meinte, dass er schon fast fertig ist und nur noch eine letzte Sache braucht. Hauer.\n\nMeine Kürschnerkünste wären hier reine Zeitverschwendung. Trollhauer ziehen... ah, bei sowas würde mir sofort übel werden. \n\nBringt mir 10 Trollhauer, alles klar?", sourceObjective = "Prigmon möchte, dass Ihr 10 Hauer eines Waldtrolls von Trollen in Zul'Aman einsammelt. Bringt sie zu ihm bei Budds Lager in den Geisterlanden.", progress = "Beeilt Euch, Mann!\n\nWenn ich Budd die Hauer nicht bald bringe, lässt er mich seine Maske allein in Zul'Aman testen!", completion = "Ahh... gut, genau danach habe ich gesucht!\n\nHier, der versprochene Lohn, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11165] = { id = 11165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Troll unter Trollen", description = "Hört zu, Mann, da gibt's noch was anderes, was Ihr für den alten Prigmon tun könnt.\n\nZungam, mein alter Taugenichts von Vetter, steckt in Zul'Aman fest. Er lebt auch noch - ich habe sein Rauchsignal erst letzte Nacht gesehen!\n\nIch sollte ihn eigentlich verrotten lassen, dafür, dass er mich in dieses ganze Schlamassel verwickelt hat... allerdings schuldet er mir noch 'ne Stange Geld.\n\nHelft ihm so gut wie möglich da raus, das Abkassieren könnt Ihr mir überlassen!", sourceObjective = "Prigmon möchte, dass Ihr seinen Vetter Zungam in Zul'Aman ausfindig macht und ihm zur Seite steht.", completion = "Ich bin frei!\n\nAls man mich erwischt hat, hat man mir zwar fast alles entrissen, aber hier - nehmt meine letzten Münzen als Dank für Eure Mühe.\n\nWenn Ihr was braucht, helfe ich Euch natürlich jederzeit aus, Mann. Das ist das Mindeste, was ich tun kann....", sourceObjectiveStatus = "unverified-source-field" }
quests[11166] = { id = 11166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das X markiert Euren Untergang!", description = "Wie konnten diese Narren nur versagen? Ich habe ihnen gesagt, dass sie vorsichtig sein müssen - sogar meine Karte und Verkleidungen habe ich ihnen gegeben, damit sie sich leichter einschleichen können. Ach, was soll's. Das Gute an der Sache ist, dass diese Gelegenheit jetzt Euch und Euren Freunden zuteil wird.\n\nWenn Ihr Euch richtig anstellt, dann seid Ihr auf dem besten Weg, ein Teil meiner Mannschaft zu werden und damit an all dem unermesslichen Ruhm teilzuhaben, der bald mein sein wird. Nicht, dass ich Euch brauchen würde, vergesst das nicht.\n\nEs gibt da noch einige Bereiche auf der Karte, die noch besser erforscht werden müssen, bevor unsere Ausgrabung wirklich beginnen kann...", sourceObjective = "Betretet Zul'Aman und erkundet Halazzis Kammer, Jan'alais Plateau und Akil'zons Plateau. Berichtet Budd bei seinem Lager in den Geisterlanden von den Details dieser Bereiche.", completion = "<Budd versucht, nicht die Fassung zu verlieren.>\n\nÄh - so, {name} - es war aber auch an der Zeit, dass Ihr, äh, wieder zurück seid. Ja - Ihr haltet das gesamte Unterfangen auf.\n\nNun, dann lasst uns mal die Karte beschriften...", sourceObjectiveStatus = "unverified-source-field" }
quests[11169] = { id = 11169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe der Grimmtotem", description = "Bevor ich während des letzen Angriffs der Grimmtotem verwundet wurde, hatte ich noch ein recht seltsames Totem an mich bringen können, welches unsere Feinde gegen uns eingesetzt haben.\n\nAnscheinend verschießt es im Gefecht Blitze aus wilder Energie. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.\n\nDie Wasserflächen, die den Hof umgeben, beherbergen eine ganze Reihe agressiver, scheckiger Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht die Krokilisken in Reichweite des Totems zu bekämpfen.", sourceObjective = "Lehrling Garion bei Tabethas Hof möchte, dass Ihr das erbeutete Totem an 10 scheckigen Staubsuhlerkrokilisken oder Staubsuhlerdolchrachen ausprobiert.", progress = "Wart Ihr mit dem Testen des Totems erfolgreich?", completion = "<Der Lehrling hört Euch aufmerksam zu, während Ihr ihm den Verlauf des Experiments schildert.>\n\nEin bisschen Dunst und ein paar Blitze? Das war alles? Hinter dem Totem muss noch mehr stecken! Die Grimmtotem würden so etwas doch nicht mit aufs Schlachtfeld bringen, wenn es keinen Nutzen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[11171] = { id = 11171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexlord? Pah!", description = "Ausgezeichnet! Meinem großen Auftritt in Zul'Aman steht fast nichts mehr im Weg.\n\nIhr habt gute Arbeit geleistet, {name}. Ich habe mit meiner Mannschaft gesprochen und sie scheint sich langsam mit Euch anfreunden zu können. Ich würde sagen, dass Ihr schon bald ein festes Mitglied der Gruppe sein könntet. Ihr müsst nur noch eine Sache erledigen - beseitigt diesen Hexlord.\n\nEs ist nichts weiter dabei, wirklich. Knöpft Euch diesen Schuft einfach vor, er wird wahrscheinlich sofort kehrt machen und abhauen. Gebrechlichere, ältere Trolle gleichen ihre Schwächen oft mit einem einschüchternden Titel aus, versteht Ihr?", sourceObjective = "Budd Winterhäldler in den Axthügeln möchte, dass Ihr Hexlord Malacrass in Zul'Aman tötet.", completion = "Endlich! Jetzt, da der leichte Teil der Arbeit erledigt ist, kann ich wenigstens einen weiteren Meilenstein in der Geschichte setzen. Vorerst muss ich mich aber noch einer kleinen Angelegenheit zuwenden - Euch...\n\nIch fürchte, {name}, dass es an der Zeit für mich ist, Euch gehen zu lassen. Ich glaube, dass Ihr Eure Leistung hier vollbracht habt, vielleicht seid Ihr sogar an Eure Grenzen gestoßen.\n\nSeid nicht traurig. Immerhin bedarf es für die Teilnahme an solch einem außerordentlichen Unterfangen schon sehr besonderer Individuen, die nicht gleich den Verstand verlieren. Hier, schaut doch mal, das ist ein kleines Andenken für Euch, damit Ihr mich nicht vergesst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11172] = { id = 11172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeppelinabsturz", description = "Vor kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Erst vor ein paar Tagen kam hier eine Abgesandte des Dampfdruckkartells wegen dieser Sache vorbei.\n\nSie war auf der Suche nach Informationen über die Fracht des Zeppelins und dessen Piloten Beezil, aber keiner von uns hat den Absturz wirklich beobachtet. Ich bezweifle, dass sie die Aufräumarbeiten am Wrack und die Bergung der Fracht alleine bewältigen kann.\n\nWenn Ihr etwas Zeit habt, solltet Ihr mal bei Beezils Wrack vorbeischauen. Ihr findet es östlich von hier, in der Nähe der Berge.", sourceObjective = "Sprecht mit Moxie Stahlgrill bei Beezils Wrack.", completion = "Also haben Euch diese einzelgängerischen Magier hierher geschickt? Wie kann ich sicher sein, dass Ihr auch wirklich vertrauenswürdig seid?\n\nSchätze, ich kann jede Hilfe gebrauchen und eigentlich gibt es hier draußen auch nicht viel, das einen Magier interessieren könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11173] = { id = 11173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reagenziendieb", description = "Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.\n\nNormalerweise versuche ich ihn einfach zu ignorieren, meistens vergebens. Dieses Mal möchte ich etwas anderes versuchen.\n\nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Sobald Ihr mir das Gift bringt, werde ich Morlanns Vorräte auffrischen, noch bevor er irgendetwas merkt.", sourceObjective = "Bringt 6 Phiolen Marschengift zu Lehrling Garion bei Tabethas Hof.", progress = "Habt Ihr das Gift bekommen? Morlann wird jeden Moment bemerken, dass nichts mehr da ist...", completion = "<Lehrling Garion überprüft das Gift.>\n\nAbsolut perfekt! Er wird den Unterschied nie bemerken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11174] = { id = 11174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrosionsschutz", description = "Seht Euch nur um! Alles ist voller Brühschlammer. Wenn wir nicht bald eine Möglichkeit finden, sie unter Kontrolle zu halten, werden sie das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!\n\nIch kann auf keinen Fall mit leeren Händen zurückkehren, {class}! Ihr müsst mir helfen, diese Brühschlammer aufzulösen, bevor sie alles zerstören!\n\nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Brühschlammer ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um es anzutreiben. Der Kern beim Hauptwrack funktionert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 10 Brühschlammer auflöst.", progress = "Habt Ihr irgendwelche Fortschritte bei Eurer Brühschlammerjagd gemacht?", completion = "Es sieht da draußen schon etwas ruhiger aus...\n\nIch schätze, es ist an der Zeit, die Bergungsarbeiten fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11177] = { id = 11177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler beim Irrlichtanwesen", description = "Es gibt da einen Burschen, die Einheimischen nennen ihn \"Sumpfauge\" Jarl, der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.\n\nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.\n\nDas Irrlichtanwesen befindet sich in der Gegend beim Hexenhügel. Folgt der Straße von Theramore aus in Richtung Nordwesten, Ihr werdet das Anwesen finden, bevor die Straße in Richtung Westen abbiegt.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", completion = "Runter von meinem Grundstück... es sei denn, hm, Ihr wollt dem alten \"Sumpfauge\" beim Kochen zur Hand gehen. Was sagt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11178] = { id = 11178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Kriegsherren", description = "Ihr begutachtet die Phiole mit dem pulsierenden Blut und Eure Gedanken schweifen zu dem launischen kleinen Mann außerhalb von Zul'Aman.\n\nIhr könnt es kaum erwarten, Budds Gesicht beim Anblick dieser Phiole zu sehen!", sourceObjective = "Bringt Zul'jins Blut zu Budd bei seinem Lager in den Geisterlanden, direkt außerhalb von Zul'Aman.", progress = "<Budd versucht seinen Unmut bei Eurer Ankunft zu verbergen.>\n\nIhr schon wieder...\n\nWie sage ich es Euch am besten... Ich bin einfach viel zu beschäftigt, als dass ich Euch während meiner Vorbereitungen noch länger zur Seite stehen könnte, {name}.\n\nGlaubt mir, {name}, es ist zu Eurem Besten. Vielleicht schafft Ihr es ja, nach vielen Jahren harter Arbeit und mit etwas Glück, Euch selbst einen Namen zu machen.\n\nFalls ja, dann könnt Ihr erzählen, dass alles bei dem unvergleichlichen Budd Winterhäldler begonnen hat!", completion = "Da... das Blut von Zul'jin selbst, sagt Ihr?\n\n<Budd reißt sich zusammen und spricht weiter.>\n\nNun gut, ich weiß diese Geste zu schätzen, {class}, aber ich hätte ihn natürlich selbst mit Leichtigkeit vernichten können. Er wird niemals so furchtbar gewesen sein, wie man in den Legenden sagte. So etwas wird oft völlig übertrieben, Ihr werdet das schon noch verstehen. Wahrscheinlich litt der alte Kerl bereits unter Arthritis!\n\nEgal, ich denke, dass dies das Mindeste war, was Ihr im Gegenzug für meine Güte habt tun können.\n\nVerschwindet jetzt - ich muss diese Phiole loswerden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11180] = { id = 11180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sucht den Hexenhügel heim?", description = "Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.\n\nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!", sourceObjective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr Informationen von 10 auferstandenen Gebeinen oder auferstandenen Geistern sammelt.", progress = "Was habt Ihr von den Spukgeistern erfahren können?", completion = "<Mordant holt ein kleines Blatt Papier und einen Stift hervor und beginnt, sich Notizen über Eure Berichterstattung zu machen.>\n\nIhr konntet herausfinden, dass sich die Geister an diesem Ort auf die Anzahl aller belaufen, die jemals auf diesem Land gelebt haben, und nicht nur auf die vorherigen Besitzer.\n\nEtwas hat sie zu Grunde gerichtet und getötet. Wer der Sache verfällt, erfährt die Wahrheit nicht, bis es zu spät ist. Wir müssen dem Ganzen ein Ende bereiten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11181] = { id = 11181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hexenfluch", description = "In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.\n\nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, {name}. Es könnte unsere letzte Hoffnung sein.", sourceObjective = "Bringt 9 Zweige Hexenfluch zu Mordant Grimsby beim Irrlichtanwesen.", progress = "Konntet Ihr ein paar Pflanzen finden? Wir müssen schnell handeln, bevor das Übel, das hinter dieser Heimsuchung steckt, in dieser Gegend vollends überhand nimmt.", completion = "<Mordant nimmt das Pflanzenbündel von Euch entgegen.>\n\nDiese entsprechen exakt der Beschreibung! Während Eurer Abwesenheit habe ich die Fackel vorbereitet. Jetzt müssen wir die Pflanzen nur noch hier am Ende befestigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11183] = { id = 11183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigungsritual des Hexenhügels", description = "Die Fackel ist fertig. Stellt sie am Ende des Docks auf und seid auf alles gefasst.\n\nIch weiß wirklich nicht, was der Rauch der Fackel bewirken wird... falls überhaupt etwas geschieht. Eigentlich hege ich für gewöhnlich Zweifel an dererlei Hokuspokus, aber wir haben keine andere Wahl. Viel Glück, Ihr und Jarl könnt es brauchen.", sourceObjective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr die Fackel am Ende des Docks aufstellt und alles bezwingt, was daraufhin erscheint.", progress = "Ist es vorbei?", completion = "Es hat funktioniert?\n\n<Mordant räuspert sich.>\n\nIch meine... es hat funktioniert! Jarl und ich stehen tief in Eurer Schuld, {name}. Jetzt muss ich mich nur noch um den schlechten Einrichtungsgeschmack meines Freundes kümmern. Ich befürchte, dass das nicht allzu einfach wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11184] = { id = 11184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlächterklaue der Gefräßige", description = "Reisende und Mitarbeiter des Dampfdruckkartells werden gebeten, den Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.\n\nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.\n\nDrazzit Tropfhahn wurde autorisiert, jeden, der der Bedrohung durch Schlächterklaue ein Ende setzt, großzügig zu entlohnen.", sourceObjective = "Tötet Schlächterklaue den Gefräßigen und meldet Euch anschließend bei Drazzit Tropfhahn in Morastwinkel.", completion = "Endlich hat sich jemand um diese Sache gekümmert. Ich dachte schon, dass ich die Belohnung verdreifachen müsste, bevor jemand diesen verdammten Raptor zur Strecke bringt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11185] = { id = 11185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief der Apothekerin", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, enthält alarmierende Beweise für das enge Bündnis der Grimmtotem mit den neuen Herren von Lordaeron.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nAndello Porter, der SI:7-Agent bei Tabethas Hof, sollte umgehend von diesem Brief erfahren.", sourceObjective = "Bringt den versiegelten Brief zu Andello Porter auf Tabethas Hof.", progress = "Was habt Ihr da, {class}?", completion = "<Andello liest den Brief, bestürzt über dessen Inhalt.>\n\nDies bestätigt lediglich unseren Verdacht, den wir seit langem über das Zusammenspiel von Horde und den Verlassenen hegen. Mit Hilfe der Magie und den Waffen der Verlassenen würden die Grimmtotem zu einem noch viel gefährlicheren Gegner werden. Das Gleichgewicht der Macht in Kalimdor könnte ernsthaft in Gefahr sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11186] = { id = 11186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Verrats?", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, deutet auf eine geheime Korrespondenz zwischen Unterstadt und den Anführern der Grimmtotem hin.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nVielleicht kann Euch Nazeer Blutlanze in Brackenwall sagen, was mit dieser Information geschehen soll.", sourceObjective = "Bringt den versiegelten Brief zu Nazeer Blutlanze in Brackenwall.", progress = "Was habt Ihr da, {class}?", completion = "Wenn es das ist, was es zu sein scheint, dann müssen die Verlassenen eine gute Erklärung dafür finden!\n\nDie Torheiten der Grimmtotem haben die Geduld des Kriegshäuptlings schon seit langem auf die Probe gestellt. Für gewöhnlich war es üblich, dass diese Angelegenheiten unter den {race} ausgemacht werden, aber das könnte nun anders aussehen.\n\nEs wird einige Zeit dauern, bis man den Verdächtigungen nachgegangen ist. Sprecht mit niemandem über das, was Ihr heute gesehen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11191] = { id = 11191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Leuchtturm", description = "Der alte Leuchtturm draußen im Osten ist schon seit langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, den ganzen Betrieb wieder zum Laufen zu bringen.\n\nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann wesentlich sanfter zu den Docks gelangen. Was kann ich dagegen noch einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?", sourceObjective = "Sprecht mit Babs Zischeldrill bei dem Leuchtturm auf der Insel östlich von Theramore.", completion = "Gut. Ich kann jede Hilfe gebrauchen. Als Allererstes möchte ich die Lampe wieder zum Leuchten bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11192] = { id = 11192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drescheröl", description = "Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.\n\n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>\n\nIch vermute, dass es sich hierbei um eine praktische, wenn auch unelegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Man findet sie genau unterhalb der Docks von Theramore.\n\nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?", sourceObjective = "Bringt 4 Behälter mit Drescheröl zu Babs Zischeldrill beim Leuchtturm in der Nähe von Theramore.", progress = "Konntet Ihr etwas Drescheröl auftreiben?", completion = "Nun, ich habe ja meine Zweifel, aber es ist im Moment eben die einzige Lösung. Sobald das Ganze wieder funktioniert, wird sich sicherlich etwas anderes zum Betreiben der Lampe finden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11193] = { id = 11193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimtückische Bewohner der Tiefe", description = "Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.\n\n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>\n\n\"Heimtückische Bewohner der Tiefe!\"\n\nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.\n\nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael \"Schmutz\" Fink. Er sammelt alte Bücher.", sourceObjective = "Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore.", progress = "Was darf es heute sein? Der Barsch ist ausgezeichnet.", completion = "Nun ja, mir dieses Buch zukommen zu lassen, war ganz schön aufmerksam von der alten Babs. Ich weiß nicht, ob Ihr ein wenig darin geblättert habt, aber in den Geschichten steckt schon die ein oder andere Wahrheit. Seefahrer erfinden sowas nicht einfach, versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11194] = { id = 11194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das wahr?", description = "Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut aufgelacht habt. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran ist?\n\nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr ganz sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.\n\nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in der Tidenbucht, welche südwestlich jenseits der Bucht der Düstermarschen liegt.", sourceObjective = "Sprecht mit Nat Pagle bei Nats Angelplatz in der Tidenbucht.", completion = "So, Ihr wollt also etwas über Meeresungeheuer wissen? Hmm... na gut, ich hätte da ein Angebot für Euch. Das Ganze beinhaltet aber reichlich Alkohol und Ihr werdet dabei ziemlich in Verlegenheit geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11195] = { id = 11195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel mit der Puppe", description = "Ich bin gerührt, {name}, is' kein Scherz, Mann. Ich kann mich nicht daran erinnern, dass <ein/eine:r> {race} Zungam jemals aus der Patsche geholfen hätte.\n\nDas hier habe ich einem der Wilden entwendet, als man mich festgebunden hat. Es sieht zwar nicht nach etwas Großartigem aus, aber wenn jemand den Wert einschätzen kann, dann ist das mein guter alter Freund Gaunah!\n\nSolltet Ihr hier lebend wieder rauskommen, dann stattet ihm einen Besuch in Shattrath ab, es lohnt sich.", sourceObjective = "Bringt die zerlumpte Voodoopuppe zu Gaunah in Shattrath.", progress = "Hey, {name}! Ich habe gehört, dass Ihr Euch einen Platz in Budds Mannschaft verschafft habt. Ihr werdet keine Zeit haben, dies zu bereuen, Kumpel, das kann ich Euch versprechen.\n\nWas habt Ihr denn da, Mann?", completion = "Hey, wo habt Ihr denn das her?\n\nNein, nein, sagt's nicht - das stammt vom Hexenfürst persönlich! Jetzt ist mir alles klar. Starkes Mojo! Der Träger dieses Relikts, egal wie oft er schon in Ungnade gefallen sein mag, wird vom Hochadel stets verehrt werden. Unglaublich!\n\n<Als Gaunah die Puppe in die Höhe hält, fällt ein kleiner, rostiger Glücksbringer von deren Hals. Der Troll will ihn gerade wegstecken, aber wendet sich Euch dann mit einem Funkeln in den Augen zu.>\n\nIch habe gerade kein Bares bei mir, Mann, aber nehmt doch bitte das hier...", sourceObjectiveStatus = "unverified-source-field" }
quests[11196] = { id = 11196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEMP X", description = "Hört zu, Mann, da gibt's noch was anderes, was Ihr für den alten Prigmon tun könnt.\n\nZungam, mein alter Taugenichts von Vetter, steckt in Zul'Aman fest. Er lebt auch noch - ich habe sein Rauchsignal erst letzte Nacht gesehen!\n\nIch sollte ihn eigentlich verrotten lassen, dafür, dass er mich in dieses ganze Schlamassel verwickelt hat... allerdings schuldet er mir noch 'ne Stange Geld.\n\nHelft ihm so gut wie möglich da raus, das Abkassieren könnt Ihr mir überlassen!", sourceObjective = "Prigmon möchte, dass Ihr seinen Vetter Zungam in Zul'Aman ausfindig macht und ihm zur Seite steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11198] = { id = 11198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt Tethyr!", description = "Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.\n\nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.", sourceObjective = "Major Mühlens bei den Docks von Theramore möchte, dass Ihr Tethyr bezwingt.", completion = "Gut gemacht, {name}! Ich muss gestehen, dass ich beim ersten Anblick des Ungeheuers zu zweifeln begann, ob wir die Docks wirklich verteidigen können. Ihr habt Eure Arbeit jedoch bravourös gemeistert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11200] = { id = 11200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein bloßer Zufall", description = "Wir haben die Ruinen des Gasthauses so gut es geht nach Beweisen abgesucht. Ich bin beunruhigt, was die Ergebnisse unserer Ermittlungen betrifft, aber wir müssen die Wahrheit erfahren.\n\nDie Hufabdrücke und der Schild mit Mosarns Prägung deuten darauf hin, dass die Grimmtotem ihre Finger im Spiel haben. Sie haben erst kürzlich eine Siedlung im Sumpf errichtet, das Dorf der Schwarzhufe im Nordosten. Reist zum Dorf der Schwarzhufe und sucht nach weiteren Waffen, die von Mosarn angefertigt wurden.", sourceObjective = "Krog in Brackenwall möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", progress = "Was konntet Ihr im Dorf der Schwarzhufe finden?", completion = "<Krog betrachtet die Waffen und die Rüstung, die Ihr ihm aus dem Dorf der Schwarzhufe mitgebracht habt.>\n\nDas ist ganz unverkennbar die Arbeit von Mosarn. Ihn weiter auszufragen würde zu viel Aufmerksamkeit erregen. Wie gut, dass wir bei Angelegenheiten mit den Grimmtotem etwas mehr Handlungsfreiheit haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11201] = { id = 11201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verschwörung der Grimmtotem", description = "Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Hochrangige Vertreter der Grimmtotem hießen bereits Morde und Entführungen gut, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten Ihr nächstes Ziel sein.\n\nDas Dorf der Schwarzhufe im Nordosten, in der Nähe des Blaumoors, ist eine große neue Siedlung der Grimmtotem. Ihre Anführer, die Ältesten, dürften alle Anordnungen von Donnerfels bei sich tragen. Versucht an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.", sourceObjective = "Bringt die Schlachtpläne der Grimmtotem zu Krog in Brackenwall.", progress = "Konntet Ihr die Pläne ausfindig machen?", completion = "<Krog überfliegt die Schlachtpläne.>\n\nIch bin mir jetzt ganz sicher, dass die Grimmtotem einen Angriff auf die Menschen planen. Allerdings weiß ich nicht, was ihre Absichten uns gegenüber sind. Die Handlungen der Grimmtotem haben in der Vergangenheit für gespannte Verhältnisse innerhalb der Horde gesorgt, doch der Kriegshäuptling hat die Lage bis jetzt immer entschärft.", sourceObjectiveStatus = "unverified-source-field" }
quests[11203] = { id = 11203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Tabetha auf", description = "Die Waffen, die Ihr im Dorf der Schwarzhufe gefunden habt, wurden außer zum Üben noch nie im Kampf eingesetzt. Dies bedeutet, dass die Grimmtotem, die für den Angriff auf das Gasthaus verantwortlich sind, noch immer auf freiem Fuß sind.\n\nIm Süden, im Herzen des Morasts, lebt die Hexe Tabetha. Sie ist zwar ein Mensch, doch in der Vergangenheit hat sie uns treue Dienste geleistet und einige unserer Magier ausgebildet.\n\nBittet sie, Euch beim Aufspüren der Grimmtotem, die für den Überfall auf das Gasthaus Zur süßen Ruh verantwortlich sind, zu helfen. Die Allianz soll nicht auf den Gedanken kommen, dass wir etwas damit zu tun hätten.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "<Tabetha lächelt.>\n\nKrog möchte, dass ich die Grimmtotem ausfindig mache, ja? Nun gut, dafür braucht es aber keine Magie.\n\nScheinbar haben wir einen gemeinsamen Feind. Die Grimmtotem haben in der Nähe einen Außenposten errichtet und sind mir und meinen Schülern ein ständiger Dorn im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[11204] = { id = 11204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Krog", description = "Hoffentlich konnte ich Euch weiterhelfen. Es tut mir leid, dass ich Euch keine bessere Auskunft geben konnte. Meine Lehrlinge und ich fertigen solch eine große Menge an Waffen und Rüstungen an, dass es fast unmöglich ist, detaillierte Informationen zu jedem Stück zu behalten.\n\nWir statten nicht nur die mutigen Verteidiger der Taurenländer aus, nein, die Grimmtotem hegen auch eine besondere Vorliebe für meine Arbeit. Ein erfahrener Krieger erkennt gutes Handwerk, wenn er es sieht.", sourceObjective = "Sprecht mit Krog in Brackenwall.", completion = "Er hat bestätigt, dass die Grimmtotem seine besten Kunden sind? Mosarn hat uns weit mehr geholfen als er ahnt. Mit dieser Menge an Hinweisen, die die Grimmtotem belasten, dürften wir unsere Hauptverdächtigen gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11205] = { id = 11205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus Zur süßen Ruh niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", sourceObjective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Unsere letzte Botschaft dürfte bei den Grimmtotem angekommen sein.\n\nWas Euch betrifft, so solltet Ihr Eurer Kontaktperson in Brackenwall von Eurem Erfolg berichten. Ich weiß, dass die Zerstörung des Gasthauses Zur süßen Ruh zwischen Horde und Allianz für Spannungen sorgen könnte. Sollten mir Ermittler von Theramore begegnen, werde ich ihne gerne berichten, dass die Grimmtotem eigenständig gehandelt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11206] = { id = 11206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Walten der Gerechtigkeit", description = "Ich bezweifle, dass die Grimmtotem ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus Zur süßen Ruh bestraft.\n\nDer Ermittler, der Euch entsendet hat, braucht davon nichts zu wisssen, aber die Horde muss die Grimmtotem nun endlich in ihre Schranken verweisen. Eines Tages werden sie die Horde noch in eine missliche Lage versetzen.\n\nWeder Lady Jaina noch Kriegshäuptling Thrall möchten einen weiteren Krieg, aber werden sie auch das Nötige tun, um solch eine Situation zu vermeiden?", sourceObjective = "Kehrt zu Krog in Brackenwall zurück.", completion = "<Krog hört sich Euren Bericht an.>\n\nIch bin beeindruckt, {name}. Ich hatte vermutet, dass die verbrecherischen Grimmtotem nicht so einfach auszumachen sind. \n\nTabethas Warnungen stoßen nicht auf taube Ohren, allerdings unterliegt es nicht meiner Verantwortung, die Grimmtotem zu bestrafen. Ich werde es natürlich in meinem Bericht an den Kriegshäuptling erwähnen. Sprecht mit niemandem über die Sache, bevor Thrall sich der Grimmtotem angenommen hat. Ihr habt gute Arbeit geleistet, indem Ihr das Rätsel um das Gasthaus Zur süßen Ruh gelöst und uns vom Verdacht der Einwohner von Theramore befreit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11207] = { id = 11207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Der Zeppelin hatte Morastwinkels Vorräte für die nächsten sechs Monate geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch auf Dauer ist das keine Lösung.\n\nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt, was die Sache ziemlich erschwert. Ohnehin denke ich, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir bei der Bergung helfen?", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.", progress = "<Moxie scheint beinahe wahnsinnig vor Sorge.>\n\nIst die Fracht intakt? Konntet Ihr irgendetwas bergen?", completion = "Wow! Ich hätte nie geglaubt, dass da draußen noch so viel intakte Fracht liegt. Keine Ahnung, welche Ausbeute Drazzit von uns erwartet, aber zunächst wird er sich mit diesem Fund zufrieden geben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11208] = { id = 11208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Drazzit", description = "Drazzit erwartet sicher bald Nachricht von mir, doch solange die Absturzstelle nicht gesichert ist, kann ich hier nicht weg. Würdet Ihr, sofern Ihr etwas Zeit erübrigen könnt, einen Teil der geborgenen Fracht nach Morastwinkel bringen?\n\nFalls Ihr den Weg nicht kennt: die Siedlung liegt südwestlich von hier, hinter den Ruinen der Steinbrecher. Ihr könnt auch die Straße, die von Tabethas Hof wegführt, nehmen. Nachdem Ihr in Morastwinkel angekommen seid, sucht nach einem Typen namens Drazzit Tropfhahn.", sourceObjective = "Bringt die Zeppelinfracht zu Drazzit Tropfhahn in Morastwinkel.", progress = "Ja?", completion = "<Drazzit nimmt die Fracht entgegen.>\n\nIch bin so hungrig, ich könnte glatt einen ganzen Drachen verschlingen! Schön, dass es Moxie endlich gelungen ist, einen Teil der Fracht hierher zu schaffen. Wir waren zuletzt sogar dazu verdammt, mit dem Oger um seine Jagdbeute zu würfeln, ansonsten wären wir verhungert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11209] = { id = 11209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nats Abmachung", description = "Ihr habt also eine Kopie von \"Heimtückische Bewohner der Tiefe\", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.\n\nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.\n\nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!", sourceObjective = "Nat Pagle bei Nats Angelplatz möchte, dass Ihr seinen neuen Köder ausprobiert.", progress = "Vergesst nicht, die Abmachung lautet \"Kommt nicht eher wieder, bevor Euch etwas gebissen hat\".", completion = "Nicht übel, aber wenn ich Ihr wäre, dann würde ich so schnell wie möglich ein Bad nehmen.\n\nSo, jetzt zu dem Meeresungeheuer...\n\nNehmt Euch ruhig ein oder zwei Bierchen in der Zwischenzeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11210] = { id = 11210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es ist wahr!", description = "Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.\n\nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...\n\nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit einem klugen Menschenverstand dergleichen tun.\n\nDas ist also Euer Plan! Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.", sourceObjective = "Sprecht mit Major Mühlens bei den Docks von Theramore.", completion = "<Ihr erzählt von Eurem Besuch bei Nat Pagle, lasst dabei den Teil mit dem Ködertest aber vorsichtshalber aus.>\n\nNun, es hört sich ganz so an, als ob wir genau wissen, was es zu tun gilt. Ich treffe schon einmal die Vorbereitungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11211] = { id = 11211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Morastwinkel", description = "Als diese Goblinfrau... wie war doch gleich ihr Name... Boxie, Foxy... Moxie, genau! Egal, jedenfalls erwähnte sie, als sie auf ihrem Weg zum Zeppelinwrack hier vorbeikam, dass die Siedlung Morastwinkel in Schwierigkeiten wäre.\n\nAnscheinend hatte der abgestürzte Zeppelin wohl Vorräte für die Siedlung geladen. Folgt einfach der Straße südlich von hier, vorbei an den Ruinen der Steinbrecher. Kurz danach solltet Ihr Morastwinkel erreicht haben.\n\nSprecht dort unten mit Drazzit Tropfhahn und seht, ob er nicht Eure Hilfe gebrauchen kann.", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Es war gut, dass Tabetha Euch hierher geschickt hat. Solange der Zeppelin noch nicht geborgen ist, muss ich sie um einige Nahrungsmittel bitten. Leider ist sie selbst gerade knapp an Vorräten. Oh, falls Ihr nach einer Herausforderung sucht: ich habe erst kürzlich ein Kopfgeld auf einen besonders gefährlichen Raptor ausgesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11212] = { id = 11212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Hof", description = "Tief im Herzen des Sumpfs lebt eine alte Frau namens Tabetha. Wir wussten noch nie wirklich viel über sie, außer dass sie älter ist, als sie scheint. Sie hat uns hier von Zeit zu Zeit geholfen und auch den Frieden zwischen der Horde und unseren Kräften schon oft bewahrt.\n\nNormalerweise hörten wir regelmäßig von ihr, aber seit kurzem ist es still geworden.\n\nKönntet Ihr einmal bei ihr vorbeischauen, falls Ihr Zeit habt? Folgt einfach der Straße jenseits der Nordwacht weiter Richtung Süden und in den Morast. Ihr könnt ihren Hof von der Straße aus sehen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "Gut, dass man Euch von Theramore hierher entsandt hat. Der von Eurem Freund gehegte Verdacht entspricht der Wahrheit. Wir haben ein paar neue Nachbarn... und dabei handelt sich nicht um die Sorte, der man gerne ein Stück Kuchen bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11213] = { id = 11213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht nach Tabetha", description = "Eine Menschenfrau namens Tabetha lebt auf einem kleinen Hof, fast inmitten der Marschen. Normalerweise würde ich mich nicht mit einem Menschen abgeben, aber ihre Hilfe hat sich schon so manches Mal als nützlich erwiesen.\n\nLeider habe ich seit geraumer Zeit nichts mehr von ihr gehört und ich würde mir wünschen, dass jemand zu ihrem Hof reist und nach dem Rechten sieht.\n\nWenn Ihr der Straße aus dem Dorf in Richtung Süden und anschließend ins Innere des Sumpfs folgt, werdet Ihr auf ihren Hof im Herzen des Morasts stoßen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "Welch Glück, dass Nazeer Euch hierher entsandt hat. Wir haben ein paar neue Nachbarn und seit sie ihr Lager hier aufgeschlagen haben, waren sie nichts als Störenfriede.", sourceObjectiveStatus = "unverified-source-field" }
quests[11214] = { id = 11214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission nach Morastwinkel", description = "Das Dampfdruckkartell hat vor kurzem im südlichen Teil der Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.\n\nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Würdet Ihr für uns dorthin reisen?", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "So, Theramore ist also an Geschäften mit uns interessiert? Nun, ein derartiges Angebot werde ich nicht ablehnen. Neue Vorräte sind hier nur schwer zu beschaffen, also sind neue Handelspartner stehts willkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11215] = { id = 11215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Morastwinkel", description = "Für den neuen Außenposten des Dampfdruckkartells im südlichen Teil der Marschen sieht es momentan nicht so gut aus. Der Zeppelin mit den Vorräten für Morastwinkel ist abgestürzt und nun fehlt es an Werkzeugen, Nahrung und medizinischen Versorgungsgütern.\n\nFolgt der Straße nach Süden in die Marschen. Bevor Ihr Morastwinkel erreicht, führt Euch die Straße zunächst noch an Tabethas Hof und den Ruinen der Steinbrecher vorbei. Bitte helft den Einwohnern von Morastwinkel, so gut Ihr könnt.", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Jede Hilfe ist willkommen! Wir richten uns hier gerade ein und versuchen, das Beste aus unserer Situation hier zu machen, bis die Vorräte des Zeppelins eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11216] = { id = 11216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzmagier Alturus", description = "Mein Mentor hat mich hierher geschickt, um nach Unterstützung zu suchen, aber unglücklicherweise darf ich mich nicht außerhalb des unteren Viertels aufhalten. Die Leute, die dieses Etablissement besuchen, sind leider alles andere als hilfreich.\n\nIhr scheint anders zu sein, begebt Euch wohl gerne auf Abenteuer. Wenn Ihr uns bei unserem Unterfangen unterstützen wollt, dann sprecht mit Erzmagier Alturus außerhalb von Karazhan, Medivhs alter Behausung.\n\nIch werde versuchen, mir in der Zwischenzeit Zutritt zum Rest der Stadt zu verschaffen. Man munkelt, dass sich ein ehemaliger Kollege von uns hier aufhält.", sourceObjective = "Sprecht mit Erzmagier Alturus außerhalb von Karazhan im Gebirgspass der Totenwinde.", completion = "Danke, dass Ihr Euch die Zeit genommen habt, um uns hier zur Hilfe zu kommen. Vor uns liegt eine Menge wichtiger Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11217] = { id = 11217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwindet den Drachen", description = "Nachdem der Zeppelin mitsamt unseren Vorräten abgestürzt ist, gehen uns langsam die Medikamente und Verbände aus.\n\nWir tun was wir können, aber inmitten all dieser Insekten, umgeben von Feinden, bleiben Verletzungen nicht aus. Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch unser Pflanzenvorrat geht ebenfalls zur Neige.\n\nMan nennt sie Drachenwinde und sie wächst im Drachendüster und im Drachensumpf östlich der Siedlung. Die Pflanze besteht aus gewundenen Stengeln und wenn man sie ansieht, scheint sie zu pulsieren.", sourceObjective = "Gizzix Rußgurgel in Morastwinkel möchte, dass Ihr ihm 8 Drachenwinden bringt.", progress = "Habt Ihr einige Drachenwinden gefunden?", completion = "Danke! Damit sollten wir eine Weile überleben können, bis Moxie mit den restlichen Vorräten von der Zeppelinabsturzstelle zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11219] = { id = 11219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht das Feuer!", description = "Die Kinder der Horde brauchen Eure Hilfe, {name}. Der kopflose Reiter, einst ein Paladin der Menschen und jetzt ein wahnsinniger Unhold, hat unser Dorf in Brand gesetzt! Ihr müsst diese Feuer löschen!\n\nSchnappt Euch einen Eimer Wasser und löscht die Flammen damit. Ihr könnt den Eimer auch an einen Verbündeten, der näher bei den Feuern steht, weiterreichen. Löscht alle Feuer und haltet den kopflosen Reiter auf!", sourceObjective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", completion = "Die Feuer sind erloschen! Ihr wart mit Eurer Brandwache erfolgreich! Hah!\n\nDer Angriff des kopflosen Reiters ist fehlgeschlagen, aber solange er und sein Kopf nicht vernichtet werden, wird er wieder zurückkehren.\n\nLasst uns bis dahin Trost in der Sicherheit finden, die Ihr uns und unseren Kindern beschert habt. Es war mir eine Ehre, heute Zeuge Eurer Taten zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11220] = { id = 11220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kopflose Reiter", description = "Solange der Kopf des kopflosen Reiters nicht vernichtet wird, wird sein verheerendes Wüten kein Ende nehmen.\n\nDer Reiter haust tief im unglückseeligen Kreuzgang des Scharlachroten Klosters in Tirisfal. Geht dorthin und sprecht diese Worte:\n\n Erhebe dich, Reiter\n Deine Zeit ist gekommen\n Heut' Nacht sei dein Leben\n Auf ewig genommen!\n\nDies wird den Unhold hervorrufen. Vernichtet den Kopf des Reiters und er wird uns nie wieder plagen.", sourceObjective = "Sucht nach dem Kürbisschrein des kopflosen Reiters.", completion = "Der Ursprung dieses Schreins ist unbekannt, aber es besteht kein Zweifel, wem hier gehuldigt wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[11222] = { id = 11222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Bolvar!", description = "Wir haben zwar noch nicht alle Antworten, die wir uns wünschen, aber es ist zwingend erforderlich, dass Ihr Hochlord Bolvar Fordragon sofort von Euren Entdeckungen berichtet!\n\nEr muss wissen, dass die Defias einen mächtigen Schutzherren in Sturmwind haben und mit dem Verschwinden von König Varian in Verbindung stehen!\n\nIch kann Euch mit Hilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit Hochlord Bolvar Fordragon in der Burg Sturmwind.", completion = "<Hochlord Bolvar hört sich Jainas Botschaft an.>\n\nSeid Ihr sicher? Das ist eine schwerwiegende Anschuldigung...", sourceObjectiveStatus = "unverified-source-field" }
quests[11223] = { id = 11223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Jaina", description = "Lasst Euch nicht von Lady Prestors Beteuerungen ablenken, {name}. Dass sie dieser Angelegenheit keine Beachtung schenkt, verwundert mich nicht, aber das ist eine andere Geschichte.\n\nWie ich schon sagte, ich danke Euch und Lady Jaina, dass Ihr mir von Euren Entdeckungen so eilig berichtet habt. Bitte richtet ihr aus, dass kein anständiger Bürger Sturmwinds ruhen wird, bevor unser König wieder unter uns weilt.\n\nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", completion = "Das sind ausgezeichnete Neuigkeiten, {name}! Ich hatte befürchtet, dass der Hochlord an der Aufrichtigkeit unserer Informationen zweifeln würde, aber meine Sorge war wohl unberechtigt.\n\nTheramore und die Allianz werden Euch für Eure Bemühungen reichlich belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11225] = { id = 11225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler des Hexenhügels", description = "Die Marschen scheinen seltsame Auswirkungen auf die Menschen zu haben. So mancher wurde schon wahnsinnig, nur weil er dort lebte.\n\nJeder, der sich im Irrlichtanwesen niedergelassen hat, wurde auf ganz besondere Weise verrückt. Bei dem jetzigen Besitzer, man nennt ihn \"Sumpfauge\" Jarl, machen sich bereits einige Anzeichen bemerkbar.\n\nIch weiß zwar nicht genau, was dort vor sich geht, aber ich wäre Euch sehr dankbar, wenn Ihr dort nach dem Rechten sehen würdet.\n\nDas Anwesen liegt am östlichen Ende des Sumpfs. Lauft Richtung Osten durch das Blaumoor und vorbei an der Nordwacht. Die Gegend, in der das Anwesen liegt, ist ein verwunschener Flecken und heißt Hexenhügel.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", completion = "Seid Ihr hierher gekommen, um mich auszuspionieren? Nein?\n\nDann seid Ihr vielleicht ein Liebhaber der guten Küche? Gut, ich kann Eure Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11242] = { id = 11242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei!", description = "Zorn hielt mich gefangen, {name}, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", sourceObjective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", progress = "Ihr habt etwas für mich, {name}?", completion = "Was ist das? Der Foliant von Thomas Thomson, sagt Ihr? Aber das ist doch der Name des kopflosen Reiters, bevor er dem Flucht zum Opfer fiel! Heißt das, seine Seele ist endlich frei? Bedeutet dies wirklich, dass er die guten Einwohner von Azeroth nie wieder heimsuchen wird? Was für ein Freudentag! {name}, von Euren Heldentaten wird man noch lange zu berichten wissen. Die Kinder und sogar ihre Kinder werden sich stets an Euren Namen erinnern!", sourceObjectiveStatus = "unverified-source-field" }
quests[11293] = { id = 11293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Gerstenbräus!", description = "Lasst alle wissen, dass die Gerstenbräus auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält! Ich werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder und Widderrennzügel für 4 Minuten borge. Verwendet die Zügel, um ihn anzutreiben, aber achtet drauf, ihn nicht zu sehr zu erschöpfen.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", completion = "Gut gemacht! Die Ankündigung wird unser Geschäft bestimmt ins Rollen bringen.\n\nWir hatten Euch ja auch eine Belohnung versprochen, hier ist sie. Die Gerstenbräus halten ihr Wort.\n\nOh, wenn Ihr die gute Kunde von den Gerstenbräus noch einmal verbreiten wollt, könnt Ihr gerne an einem anderen Tag wieder kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11294] = { id = 11294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Donnerbräus!", description = "Wir müssen die Leute wissen lassen, dass die Donnerbräus ihre Bitte nach gutem Gebräu erhört haben. Verbreitet die Kunde bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel. Ruft, was das Zeug hält!\n\nWir werden Euch das Ganze etwas erleichtern, indem wir Euch einen Rennwidder UND passende Zügel 4 Minuten lang borgen.\n\nAchtet darauf, nicht zu schnell zu reiten, denn Ihr werdet keine Apfelkisten in Eisenschmiede finden und wir können es nicht riskieren, den Marktschreiern der Gerstenbräus behilflich zu sein.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb der Bank, im Militärviertel, in der Halle der Forscher und im Mystikerviertel.", completion = "Gute Arbeit! Das wird es diesen arroganten Gerstenbräus aber zeigen.\n\nNa dann, wir haben Euch eine Belohnung versprochen und hier ist sie. Wir Donnerbräus belohnen Euch mit Preisen, die Gerstenbräus belohnen Euch mit faulen Sprüchen und falschen Versprechen.\n\nIhr habt Euch weise entschieden.\n\nWenn Ihr auch weiterhin den richtigen Weg einschlagen wollt, dann kommt an einem anderen Tag noch einmal vorbei und verbreitet die Kunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11318] = { id = 11318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Widderrennen... zumindest fast", description = "Ihr wollt also die Rennwidder testen? Nun, ich hoffe, Ihr seid auf Geschwindigkeit gefasst. Bevor ich Euch auf die Welt loslasse, müsst Ihr mir erst einmal beweisen, dass Ihr mit diesen feinen Tieren auch wirklich umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Rennzügel und lasse Euch auf einem Widder reiten. Zeigt mir, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten. Sprecht mit meinem Lehrling, Pol Bernruh, falls Ihr Anweisungen für den Umgang mit den Widdern benötigt.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", completion = "Nicht schlecht! Es dauert meist ein wenig, bis man seinen Widder zu kontrollieren versteht. Hat man den Dreh erstmal raus, würde man sich wünschen, dass jeder Widder ein Rennwidder wäre.\n\nWie bitte? \"Wo ist meine Belohnung?\". Ha, ha, ha... Ihr dürft mit dem schnellsten Widder am Rennen teilnehmen! Ihr wollt noch mehr? Na, wie wäre es damit...\n\nAls Belohnung dürft Ihr anderen hier auf dem Braufest aushelfen. Es gibt jede Menge zu tun... und Belohnungen für eifrige, junge Widderrennmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[11321] = { id = 11321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagte da jemand \"Souvenir\"?", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNa ja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11334] = { id = 11334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er schießt, er trifft!" }
quests[11335] = { id = 11335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", progress = "Wie ist die Lage, {name}? Gibt es Neuigkeiten von der Front?", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11336] = { id = 11336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", progress = "Wie ist die Lage, {name}? Gibt es Neuigkeiten von der Front?", completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11337] = { id = 11337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Der Kampf gegen die Horde kennt keine Grenzen, {name}. Sogar in der Scherbenwelt gibt es beständig Streitigkeiten über Gebietsansprüche und alter Hass wird von neuem entfacht. Krieg ist allgegenwärtig!\n\nBegebt Euch ins Auge des Sturms und stellt sicher, dass die Allianz, genau wie in Azeroth, obsiegen wird.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", completion = "Wir sind dem endgültigen Sieg über die Horde wieder einen Schritt näher gekommen. Niemals dürfen wir zulassen, dass der Feind sich einen Brückenkopf in dieser oder in irgendeiner anderen Welt sichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[11338] = { id = 11338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumküsser sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", completion = "Hervorragende Arbeit, {name}. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11339] = { id = 11339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte oder in Shattrath.", progress = "Ihr seid schon zurück? Bringt Ihr Nachricht von Sieg?", completion = "Ihr habt der Horde heute ehrenvoll gedient, {name}. Der heutige Sieg sichert uns tausend weitere Siege!", sourceObjectiveStatus = "unverified-source-field" }
quests[11340] = { id = 11340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, {name}. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte oder in Shattrath.", progress = "Ihr seid zurück! Bringt Ihr Nachricht über den Sieg?", completion = "Es gibt nichts Ehrenvolleres, als die feindlichen Invasoren aus dem Gebiet der Horde zu vertreiben. Ich verneige mich vor Eurem Mut und danke Euch dafür, dass Ihr unseren Streitkräften heute einen großen Dienst erwiesen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11341] = { id = 11341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Wo auch immer wir dem Feind begegnen, werden wir ihn bekämpfen und vernichten. Egal ob dies in Azeroth, in der Scherbenwelt oder irgendwo sonst auf der Welt getan werden muss.\n\nWir dürfen nicht zulassen, dass die Allianz ihre Position im Auge des Sturms weiter festigt. Bringen wir den Kampf also zu ihnen... denn morgen ist es vielleicht schon zu spät.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte oder in Shattrath.", progress = "Ihr seid zurück! Bringt Ihr Nachricht über den Sieg?", completion = "Ihr ehrt uns alle, {name}. Wir müssen dem Feind zeigen, dass wir ihn immer und überall bekämpfen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11342] = { id = 11342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertig Ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte oder in Shattrath.", progress = "Ihr seid zurück! Bringt Ihr Nachricht über den Sieg?", completion = "Die Horde steht in Eurer Schuld, {name}. Euer Mut und Einsatz während der Verteidigung unseres Landes macht uns alle stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[11345] = { id = 11345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise für Kugeln" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Nazans Reitgerte", description = "Der heutige Käufer interessiert sich für ein Stück, das sich momentan noch im Besitz des Reittiers von Illidans Herold befindet. Ich spreche natürlich von Vazruden dem Herold und seinem Drachenreittier Nazan.\n\nWenn Euch der Finderlohn angemessen erscheint, solltet Ihr Euch zum Bollwerk der Höllenfeuerzitadelle aufmachen und mir die Reitgerte des Drachen beschaffen.\n\nMeine Quellen versicherten mir, dass sich die Reitgerte im Besitz des Drachen höchstpersönlich befindet. Anscheinend verbot dieser seinem Herren die Benutzung der Gerte.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Nazans Reitgerte zu beschaffen. Bringt sie zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Reitgerte, bitte!", completion = "Wieder ein zufriedener Kunde. Der Gegenstand scheint in gutem Zustand zu sein, hervorragend. Ihr werdet entsprechend entlohnt werden.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostümierte Waisenmatrone", description = "Während der Schlotternächte werden von den Waisenhäusern der Menschen Ausflüge für die Waisenkinder organisiert. Die Kinder sollen Allianzdörfer auf dem Land besuchen. Die armen Kleinen würden so gerne einen wahren Helden wie Euch sehen!\n\nWarum stattet Ihr ihnen keinen Besuch ab? Ihr findet die Waisenkinder in Goldhain im Wald von Elwynn, in Kharanos in Dun Morogh und bei der Azurwacht auf der Azurmythosinsel. Sprecht mit der Aufsicht der Kinder, einer kostümierten Waisenmatrone, sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer kostümierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", completion = "Ihr seid hier, um die Kinder zu besuchen! Wie wundervoll! In ihrem kurzen Leben ist ihnen so viel Kummer widerfahren. Es ist gut, dass sie einen wahren Helden wie Euch sehen. Es hellt ihr Gemüt wirklich auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maskierte Waisenmatrone", description = "Während der Schlotternächte werden mit den Orcwaisenkindern Ausflüge zu zahlreichen Dörfern der Horde unternommen. Die Waisenmatronen dachten, dass es vielleicht gut für die Kinder wäre, wenn sie wahren Helden einmal bei der Arbeit zusehen könnten.\n\nWarum besucht Ihr sie nicht? <Ein mutiger/Eine mutige:c> {class} wie Ihr könnte ihre Gemüter mit Geschichten Eurer Heldentaten aufhellen! Geht entweder nach Klingenhügel in Durotar, Brill in Tirisfal oder zum Falkenplatz im Immersangwald. Sprecht mit der maskierten Waisenmatrone und sie wird Euch den Kindern vorstellen.", sourceObjective = "Sprecht mit einer maskierten Waisenmatrone in Klingenhügel, Brill oder beim Falkenplatz.", completion = "Die Kinder lieben es, wenn sie Helden bei ihrer Arbeit zusehen können. Ich hoffe, dass ein jedes dieser Kinder einmal ein starkes Mitglied der Horde sein und letztendlich in einer glorreichen Schlacht sterben wird!\n\nAh, der Gedanke an ein solch ehrbares Schicksal rührt mich zu Tränen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind alle Helden von Goldhain bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nEinige Wachen haben nördlich von hier ein kleines Lager für Übungen der Brandwache errichtet. Geht dorthin und löscht Feuer mit Hilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen oder das in der Nähe der Feuer stehende Fass verwenden.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", progress = "Hallo, {name}. Habt Ihr Euch im Feuerlöschen geübt? Vergesst das Übungslager im Norden nicht!", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Grunzer haben ein Übungslager zum Feuerlöschen außerhalb des Dorfes aufgebaut. In letzter Zeit fangen die Gebäude in Klingenhügel rasch Feuer - Ihr solltet helfen und Euch im Feuerlöschen üben!\n\nVerlasst Klingenhügel in Richtung Westen und biegt rechts ab, wenn Ihr an der Stadtmauer vorbei seid. Haltet nach dem Übungslager Ausschau. Schnappt Euch Wassereimer und löscht damit die Übungsfeuer.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Klingenhügel.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Werdet alle so stark und mutig wie er, dann werdet auch Ihr eines Tages für die Horde kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Keli'dans gefiederter Stab", description = "Die Geschmäcker sind sehr verschieden, nehmt zum Beispiel meinen neuesten Käufer.\n\nIn der Höllenfeuerzitadelle residiert ein Blutorc namens Keli'dan der Zerstörer. Dieser Orc ist im Besitz eines recht gewöhnlichen Stabes; nichts, was einen zweiten Blick wert wäre. Und doch ist es genau dieser Stab, den mein Kunde wünscht.\n\nWer bin ich schon, dass ich diesen Auftrag ablehnen könnte?\n\nAlso, wenn Ihr von mir entlohnt werden wollt, solltet Ihr Euch in den Blutkessel begeben, dort werdet Ihr Keli'dan und seinen Stab finden.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Keli'dans gefiederten Stab zu beschaffen. Bringt ihn zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ihr seid wieder hier... also müsst Ihr den Stab bei Euch tragen!", completion = "Möglicherweise werde ich noch einige frische Federn an den Stab anbringen lassen, bevor ich ihn seinem Käufer übergebe. Mit den ganzen Arakkoas in dieser Gegend sollte das jedoch kein großes Problem darstellen. Ein eher unwichtiges Detail und nichts, das mich davon abhalten könnte, Euch angemessen zu entlohnen.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Messerfausts Siegel", description = "Am heutigen Tage ist ein sehr reicher Sammler an mich herangetreten, dem es nach etwas besonders Einzigartigem verlangt.\n\nKriegshäuptling Kargath Messerfaust trägt sein persönliches Siegel, mit dem er alle offiziellen Dokumente abzeichnet, stehts bei sich. Ich möchte, dass Ihr es für mich beschafft.\n\nIhr findet ihn tief in den Zerschmetterten Hallen. Es besteht kein Zweifel, dass Ihr Euch zunächst durch eine recht beeindruckende Armee kämpfen müsst, bevor Ihr das Siegel in den Händen haltet. Aber ich glaube fest an Euren Erfolg!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Messerfausts Siegel zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich hörte Gerüchte, nach denen der Kriegshäuptling seine Hände durch Waffen hat ersetzen lassen. Ist das wahr?", completion = "Wahrlich eine beeindruckende Akquisition; eine, die es wert ist, dass die Barden noch in Jahrzehnten darüber berichten. Hier, Ihr habt Euch diese Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zenturionen der Zerschmetterten Hand", description = "Zweifelt Ihr an Eurem Meister? Gut, dann verstehen wir uns, ja?\n\nEs ist das Blut der Zenturionen der Zerschmetterten Hand, nach dem es mich verlangt. Sucht sie in den Zerschmetterten Hallen der Höllenfeuerzitadelle.\n\nWenn Euch die Belohnung lieb ist, werdet Ihr erst zurückkehren, nachdem Ihr sie alle getötet habt.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Zenturionen der Zerschmetterten Hand zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ihr habt Euch Eure Belohnung in der Tat verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Das Herz von Quagmirran", description = "Ich habe einen recht ungewöhnlichen Auftrag für Euch. Eine bestimmte wohlhabende Persönlichkeit, mit der ich in außerweltlichem Kontakt stehe, interessiert sich für ein besonders makaberes Stück.\n\nGenau genommen verlangt sie das Herz von Quagmirran.\n\nWie ich hörte, verfügt dieses Biest gleich über drei Herzen, doch ich denke, eines dürfte für unsere Zwecke ausreichend sein. Soweit ich informiert bin, ruht Quagmirran in einem tiefen See in den Sklavenunterkünften des Echsenkessels.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm das Herz von Quagmirran zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich vertraue darauf, dass Ihr eine Möglichkeit findet, das Herz sicher hierher zu bringen!", completion = "Wenn ich es mir recht überlege, dann ist es eigentlich eine Schande, dass ich Euch nicht darum gebeten habe, mir alle Herzen zu bringen. Vielleicht beim nächsten Mal. Wie auch immer, Ihr habt Euch Euren Anteil redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Ei der Schattenmutter", description = "Unter den Marschenläufern in den Zangarmarschen gibt es stets nur eine oberste Mutter. Man nennt sie die Schattenmutter und wenn sie stirbt, schlüpft ihre Nachfolgerin aus einem der hinterbliebenen Eier.\n\nEiner meiner Käufer interessiert sich für eben diese Eier. Beiläufig erwähnte er etwas davon, dass das geschlüpfte Wesen eine hervorragende Ergänzung für seinen Zoo wäre.\n\nWenn Euch meine Bezahlung angemessen erscheint, solltet Ihr in den Tiefensumpf aufbrechen und die Schattenmutter töten, um an das Ei zu gelangen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm ein Ei der Schattenmutter zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Sprechen wir uns wieder, weil Ihr das Ei habt? Fantastisch, lasst es mich sehen!", completion = "Ist es nicht fantastisch, wie sehr man das Leben in diesem Ei spüren kann? Ich werde mich beeilen und es rechtzeitig zu seinem Käufer bringen müssen. Wir wollen doch nicht, dass es hier bei uns schlüpft, nicht wahr?\n\nEure Bezahlung steht bereit.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Die Aufzeichnungen des Kriegsherren", description = "Vielen ist bekannt, dass Kriegsherr Kalithresh ein hervorragender Stratege ist, doch nur wenige wissen, dass er sein gesamtes Wissen auch niedergeschrieben hat.\n\nEiner meiner Kunden hat davon erfahren und nun wünscht er diese Aufzeichnungen in seinen Besitz zu bringen.\n\nDaher möchte ich Euch bitten, in die Dampfkammer des Echsenkessels einzudringen, um das Buch für mich zu beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Aufzeichnungen des Kriegsherren zu beschaffen. Bringt sie zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Mein Kunde wird langsam ungeduldig. Ich nehme an, er möchte das strategische Wissen des Kriegsherren zur Lösung eines seiner laufenden Konflikte einsetzen.", completion = "Tatsächlich glaube ich, dass mein Kunde nicht genügend Zeit aufbringen kann, um das Buch in seiner Gesamtheit zu studieren. Nun gut, überlassen wir das ihm. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Myrmidonen des Echsenkessels", description = "Mah'duun hat gehört und verstanden. Jetzt sollt Ihr sein Werkzeug sein.\n\nMir wurde offenbart, dass die Myrmidonen des Echsenkessels vernichtet werden müssen. Sucht in den klammen Räumen der Dampfkammer unter dem Echsenkessel nach ihnen.\n\nIch erwarte nichts Geringeres als ihre vollständige Vernichtung.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 14 Myrmidonen des Echsenkessels zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Ich nehme an, es war ein Kampf ganz nach Eurem Geschmack? Die Belohnung wird Euch ebenfalls zusagen.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Die Kopfschmuckfedern von Ikiss", description = "Kürzlich ist eine Taurenfrau an mich herangetreten, deren Ehemann schon bald in den Stand eines Häuptlings erhoben wird. Sie würde ihn gerne mit einer besonderen Verzierung für seinen Federkopfschmuck überraschen.\n\nGenau genommen hätte sie gerne die Kopfschmuckfedern des niederträchtigen Klauenkönigs Ikiss.\n\nWenn Euch meine ausgesetzte Belohnung angemessen erscheint, solltet Ihr zu den Sethekkhallen von Auchindoun aufbrechen und Ikiss einen Besuch abstatten.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm die Kopfschmuckfedern von Ikiss zu beschaffen. Bringt sie zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Häuptlingszeremonie findet bald statt, beeilt Euch.", completion = "Diese Federn werden dem Kopfschmuck des Häuptlings den letzten Schliff geben. Ihr habt Euch Eure Bezahlung redlich verdient, {class}.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Shaffars wundersames Amulett", description = "Heute möchte ich Euch mit einer persönlichen Angelegenheit beauftragen. Aber keine Sorge, die Belohnung macht die Gefahr wieder mehr als wett.\n\nMeine Familie hat noch eine Rechnung mit Nexusprinz Shaffar und seinen Anhängern offen. Sollte mir sein Amulett in die Hände fallen, wäre dies ein sicheres Zeichen dafür, dass sich jemand seiner angenommen hat.\n\nWenn Euch meine Belohnung angemessen erscheint, solltet Ihr zu seinen Gemächern in der Managruft von Auchindoun aufbrechen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Shaffars wundersames Amulett zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Nur wenige wissen, dass Shaffar seine magische Macht ausschließlich aus diesem Amulett bezieht. Ohne es ist er machtlos.\n\nWenn es sich also in Eurem Besitz befindet, lässt dies nur den Schluss zu, dass er tot ist.", completion = "<Eine Woge der Zufriedenheit scheint von dem Windhändler auszugehen.>\n\nGut, es freut mich, von seinem Ende zu hören. Wer weiß, vielleicht gelingt es mir sogar, die Geheimnisse des Amuletts für mich zu nutzen und wenn nicht, werde ich es zu einem angemessenen Preis verkaufen.\n\nIch schätze diese Belohnung ist mehr als ausreichend.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Seelenedelstein des Exarchen", description = "In dem Bestreben, die nekromantischen Künste besser zu verstehen, werden in der Auchenaikrypta von Auchindoun eine Unzahl von abscheulichen Experimenten durchgeführt. Zahlreich sind die Geister derer, die in den finsteren Hallen gefoltert und ermordet wurden.\n\nEiner meiner Kunden wünscht die Befreiung eines dieser gequälten Geister. Nach meinen Informationen ist dieser Geist in einem Seelenedelstein gefangen, der sich im Besitz von Exarch Maladaar befindet.\n\nSucht ihn mit gebotener Schnelligkeit in der Krypta auf und bringt mir seinen Edelstein.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Seelenedelstein des Exarchen zu beschaffen. Bringt diesen zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Könnt Ihr Euch vorstellen, für alle Ewigkeit in einem Edelstein gefangen zu sein?", completion = "Ihr seid wahrlich ein Held, {name}. Ich bin mir sicher, dass mein Kunde einen Weg finden wird, um den Geist seiner Geliebten aus dem Edelstein zu befreien. Eure Belohnung für diese hervorragende Arbeit wartet bereits auf Euch.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Murmurs Flüstern", description = "Wenn ich Euch eingeweiht habe, werdet Ihr diesen Auftrag mit Sicherheit nicht mehr annehmen wollen.\n\nEiner meiner besonders exzentrischen Kunden befasst sich mit der Erforschung toter Existenzen. Wenn man diversen Gerüchten Glauben schenkt, zerstörte das als Murmur bekannte Wesen die letzte Welt von der es beschworen wurde vollständig. Der Professor würde gerne das so genannte 'Flüstern' dieser Kreatur analysieren, um zu verstehen, wie Murmur so eine Zerstörung verursachen konnte.\n\nWürdet Ihr für mich in das Schattenlabyrinth in Auchindoun eindringen und das 'Flüstern' für mich beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Murmurs Flüstern zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich bin mir nicht einmal sicher, welche Form ein Flüstern in der körperlichen Welt annimmt, aber der Professor versicherte mir, dass Ihr es erkennen werdet, wenn Ihr es seht.\n\nVielleicht ist es so etwas wie der Kehlkopf des Wesens?", completion = "Ich fürchtete schon, Ihr würdet nicht mehr zurückkehren. Ich hoffe doch, der Kampf gegen Murmur hat Euch nicht taub werden lassen?\n\nHier ist Eure Belohnung. Der Professor wird zweifellos sehr zufrieden sein. Ich fürchte mich nur davor, was er mit diesem Gegenstand anfangen wird.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Bösartige Ausbilderinnen", description = "Mah'duun hat vernommen, dass die Grausamkeit der sechsarmigen Dämonen im Schattenlabyrinth beispiellos ist.\n\nBegebt Euch nach Auchindoun, sucht und tötet sie alle.\n\nWenn Ihr scheitert, bemüht Euch nicht, mich ein zweites Mal aufzusuchen.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 3 bösartige Ausbilderinnen zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", progress = "Habt Ihr die Ausbilderinnen alle getötet? Nein?\n\nHabe ich Euch nicht aufgetragen, erst zurückzukehren, wenn alle tot sind?", completion = "Ich bin sehr zufrieden. Auch der, der über den Nether zu mir spricht, ist hoch erfreut. Mah'duun hat Eure Belohnung bereits vorbereitet.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache ist schmackhaft", description = "Heute Abend koche ich für eine ganz besondere Festgemeinschaft. Einer der Gäste flog vor kurzem in Skettis herum, als er plötzlich von einem riesigen Kaliri erfasst wurde und zu Boden fiel. Er brach sich dabei sein Bein.\n\nFür seine 'Gute Besserungs'-Feier soll nun etwas ganz Besonderes auf dem Speiseplan stehen: Kalirieintopf.\n\nIch werde Euch meinen Topf zur Verfügung stellen und es wird Eure Aufgabe sein, den Eintopf zu kochen. Das Rezept ist an sich recht einfach, Ihr benötigt nur einen riesigen Kaliriflügel und einige gekochte Doppelwarper.", sourceObjective = "Der Rokk im unteren Viertel von Shattrath hat Euch darum gebeten, mit Hilfe seines Kochtopfs einen Kalirieintopf zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Rieche ich da etwas zu essen?", completion = "Oh, das riecht aber lecker! Ich hoffe, Ihr habt dem Vogel einen guten Kampf geliefert.\n\nBitte, nehmt Euch ruhig etwas von meinen speziellen Vorräten. Jemand mit Eurem Talent sollte damit etwas anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Kopf des Epochenjägers", description = "Die Geschmäcker meiner Kunden variieren von banal zu sehr exotisch. Manchmal wollen sie mit den exotischen Gegenständen, die ich ihnen beschaffe, sehr banale Dinge anstellen.\n\nMein momentaner Kunde gehört zu dieser Sorte. Er, dessen Name hier unerwähnt bleiben soll, wünscht sich nichts sehnlicher, als den Kopf des Epochenjägers an seiner Wand aufzuhängen.\n\n{class}, Ihr müsst einen Weg finden, um zurück durch die Zeit ins alte Hügelland zu reisen und besagten Kopf für unseren Trophäen sammelnden Kunden beschaffen.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Kopf des Epochenjägers zu beschaffen. Bringt diesen zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Der Kopf des Epochenjägers... wie kommt jemand bloß auf die Idee, sich diesen an die Wand hängen zu wollen?\n\nSelbst wenn, dann geht man doch selbst auf die Jagd. Was soll man denn den eigenen Freunden erzählen, wenn sie einem Fragen über den Kampfverlauf stellen?\n\nBleibt höchstens eine Notlüge.", completion = "Wie ich sehe, seid Ihr wieder gesund und munter im Hier und Jetzt angekommen.\n\n<Der Windhändler sieht sich um.>\n\nMir scheint, dass sich nichts verändert hat. Auf der anderen Seite, würde ich es wahrscheinlich gar nicht merken.\n\nEin sauberer Schnitt, mein Kunde wird zufrieden sein. Hier ist Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superheißes Ragout", description = "Ich versuche gerade, etwas ganz Besonderes zu kreieren. Aber um ehrlich zu sein, bin ich mittlerweile eher ein Theoretiker geworden. Irgendwie ist mir mein Sinn für Abenteuer abhanden gekommen.\n\nIhr aber... Ihr erinnert mich irgendwie an mich selbst in jungen Jahren. Bereit, sich der Welt mit Schwert und Bratpfanne zu stellen.\n\nIch möchte, dass Ihr meinen Lieblingskochtopf nehmt und Euch zum Schergrat aufmacht. Füllt ihn mit ein paar Rippchen und Knusperschlangen - natürlich gekocht, für die Extraportion Würze. Zum Schluss erhitzt Ihr das Ganze über einem abyssischen Leichnam. Dies ist die einzige Wärmequelle, die heiß genug ist, um dieses Gericht perfekt zu garen.", sourceObjective = "Der Rokk im unteren Viertel von Shattrath hat Euch darum gebeten, mit Hilfe seines Kochtopfs ein Dämonenragout Surprise, zwei Rippchen der Mok'Nathal und eine Knusperschlange zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Verlief mein kleines Experiment erfolgreich?", completion = "Nun sieh mal einer an...\n\n<Als der Rokk ein wenig von Eurem Gericht probiert, zeichnet sich auf seinem Gesicht eine Mischung aus Entzücken und abnormen Schmerzen ab.>\n\nHeiliger A'dal ist das lecker! Ein Koch mit Eurem Talent braucht stets die richtigen Zutaten! Hier, bedient Euch aus meinen Vorräten und macht mich stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaziös", description = "War ja klar! Ich denke meine Vorräte sind lückenlos und sofort kommt jemand um die Ecke, der etwas Ausgefallenes haben möchte: Manabeere Surprise.\n\nUnglücklichweise findet man Manabeeren nur in den Biokuppeln des Nethersturms. Aber macht Euch nicht die Mühe, auf der Sturmsäule zu suchen - dort ist alles abgeerntet.\n\nEs bedarf eines wahren Meisters der Kochkunst, um nur die besten Beeren zu pflücken, also enttäuscht mich nicht!", sourceObjective = "Der Rokk im unteren Viertel von Shattrath möchte, dass Ihr 15 Manabeeren in den Biokuppeln im Nethersturm sammelt.", progress = "Hattet Ihr Erfolg?", completion = "Noch nie sah ich so saftige Beeren! Ich fühle mich schon vom bloßen Hingucken geistig gestärkt.\n\nWarum nehmt Ihr nicht etwas von meinen Fisch- und Fleischvorräten? Anscheinend habe ich eh keine Verwendung mehr dafür. Sicherlich werdet Ihr daraus etwas ganz Besonderes kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppe für die Seele", description = "Irgendetwas liegt in der Luft. Noch nie hatte ich so viele Bestellungen für meine berühmte Suppe - sie weckt die inneren Geister und streichelt die Seele.\n\nIch erkenne einen Koch, wenn ich einen sehe! Würdet Ihr mir im Austausch gegen eine kleine Gewinnbeteiligung ein wenig aushelfen?\n\nHier, nehmt meinen Kochtopf, sammelt etwas Grollhuffleisch und ich verrate Euch ein kleines Geheimnis. Was glaubt Ihr, macht meine Suppe so angenehm für die Seele? Es hat nichts mit Hühnchen zu tun! Es liegt daran, dass ich sie beim Ahnengrund in Nagrand koche, um alles Geisterhafte, das in der Luft schwebt, einzufangen.", sourceObjective = "Der Rokk im unteren Viertel von Shattrath hat Euch darum gebeten, mit Hilfe seines Kochtopfs eine spirituelle Suppe zu kochen. Kehrt anschließend zu ihm zurück.", progress = "Was riecht hier so gut?", completion = "Das ist eine feine Ladung spirituelle Suppe. Es fehlt nur noch etwas Pfeffer für den richtigen Geschmack!\n\nHier, wie versprochen, Euer Anteil. Und weil Ihr so gute Arbeit geleistet habt, dürft Ihr Euch noch an meinen Vorräten bedienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Aeonus' Stundenglas", description = "Einige meiner Kunden sind wirklich verrückt. Es gibt Dinge, denen man nachjagt und andere, über die man nicht einmal nachdenken sollte!\n\nMein heutiger Kunde ist der Inbegriff von Größenwahn! Er verlangt nichts Geringeres als Aeonus' Stundenglas.\n\nJa, Ihr habt richtig gehört, das Stundenglas von Aeonus, seines Zeichens Angehöriger des Ewigen Drachenschwarms!\n\nAber wer bin ich schon, dass ich widersprechen könnte? Insbesondere bei der Menge Gold, die er mir geboten hat. Also, seid Ihr bereit, die Höhlen der Zeit aufzusuchen und in den schwarzen Morast zu reisen, um das Stundenglas zu beschaffen?", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Aeonus' Stundenglas zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "An Eurer Stelle wäre ich mit Zeitreisen sehr vorsichtig. Schließlich wollt Ihr ja nicht versehentlich einen Eurer eigenen Vorfahren töten und so Eure eigene Existenz in der Gegenwart auslöschen!", completion = "Seltsam, dass der Sand in diesem Ding noch immer aufwärts fließt. Ich schlage vor, wir schaffen es lieber schnellstmöglich zu seinem neuen Besitzer.\n\nIch muss Euch für diese gute Arbeit danken, {class}. Ihr habt Euch Eure Belohnung redlich verdient.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Fürsten der Zeitenrisse", description = "Mah'duun weiß, was zu tun ist. Mah'duun weiß, dass Ihr Fürsten der Zeitenrisse töten müsst. Doch Mah'duun ist sich des Zeitpunkts nicht sicher.\n\nDas klingt alles sicherlich sehr seltsam für Euch, doch die Stimme im Wind sagte mir auch nicht viel mehr.\n\nBegebt Euch in die Höhlen der Zeit und reist in den schwarzen Morast. Dort wird sich Euch alles offenbaren.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Fürsten der Zeitenrisse zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Anscheinend habt Ihr Euren Weg in die Vergangenheit und wieder zurück gefunden. Eure Fähigkeiten als {class} sind bemerkenswert. Die Belohnung gehört Euch.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Warpzweigsplitter", description = "Vor kurzem trat eine Druidin der Kaldorei mit einer herzzerreißenden Bitte an mich heran. Gut, sie hatte auch eine ganze Menge Gold bei sich...\n\nEs scheint, als versuchten die Streitkräfte von Darnassus ein arkanes Urtum namens Warpzweig neu zu erschaffen. Dieses gigantische Baumwesen hat sich wohl verirrt oder wurde von der Verderbnis durchdrungen, na ja, jedenfalls hält es sich zurzeit in der Botanika der Festung der Stürme auf.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm einen Warpzweigsplitter zu beschaffen. Bringt diesen zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Schwierigkeiten die Botanika zu finden? Ihr könnt sie gar nicht verfehlen, sie ist ein Teil der Festung der Stürme am östlichen Rand des Nethersturms.", completion = "Oh, Ihr habt es tatsächlich geschafft! Er ist so klein. Unglaublich, das Warpzweig aus diesem kleinen Ding neu erstehen soll und wie man mir sagte, ist es ein ziemlich langwieriger Prozess, den die Druiden da vor sich haben.\n\nEgal, wie versprochen, habe ich hier Eure Belohnung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Kanalisierer der Sonnensucher", description = "Mah'duun wurde offenbart, dass die Kanalisierer der als Sonnensucher bekannten Kampfeinheit heute getötet werden müssen.\n\nIhr findet sie in der Botanika der Festung der Stürme.\n\nIhr wollt das Kopfgeld? Also tötet sie!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 6 Kanalisierer der Sonnensucher zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Mit den Kanalisierern ist es aus. Der, der aus dem Nether zu mir spricht ist zufrieden und Ihr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Pathaleons Projektionsgerät", description = "Ich habe stets angenommen, Pathaleon könnte sein Abbild nur mit Hilfe von Magie an die verschiedensten Orte in der Scherbenwelt projizieren. Offensichtlich lag ich damit falsch.\n\nMein neuester Kunde verriet mir, dass der Blutelf stattdessen ein mechanisches Gerät verwendet, um mit den diversen Offizieren von Kael'thas zu kommunizieren. Wenn ich es richtig verstanden habe, stahl er es von einigen Zaxxisrebellen im Nethersturm.\n\nMein Kunde wünscht, dieses Projektionsgerät zu besitzen. Also, warum stattet Ihr Pathaleon nicht einen Besuch ab? Ihr findet Ihn in der Mechanar der Festung der Stürme.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Pathaleons Projektionsgerät zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Es ist ja nicht so, dass die Projektionstechnologie alleine schon etwas Besonderes wäre, aber die Reichweite dieses Modells ist enorm und bisher unerreicht!", completion = "Ich bin versucht, es für mich zu behalten und meinem Kunden sein Geld zurückzuzahlen. Mit diesem Gerät könnte ich meine Geschäfte über noch größere Entfernungen abwickeln.\n\n<Der Windhändler seufzt.>\n\nAber ich kann meinen guten Ruf nicht so leichtfertig aufs Spiel setzen.\n\nWo wir schon von meiner Reputation reden, vielen Dank, dass Ihr mir dabei geholfen habt, sie zu wahren. Hier ist Eure Bezahlung.\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zerstörer der Sturmschmiede", description = "Im Inneren der Mechanar gibt es eine Vielzahl mechanischer Konstrukte und man hat Mah'duun mit ihrer Vernichtung beauftragt.\n\nBetretet die Festung der Stürme, sucht die Zerstörer der Sturmschmiede und vernichtet sie.\n\nKehrt anschließend zurück, um Eure Belohnung zu erhalten.", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Zerstörer der Sturmschmiede zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle vernichtet wurden.", progress = "<Der Netherpirscher scheint sich über Eure Anwesenheit zu wundern.>\n\nDie Zerstörer sind noch längst nicht alle vernichtet.", completion = "Mah'duun liebt es, gegen Konstrukte zu kämpfen! Sie sind nicht so fehlerbehaftet wie organische Lebewesen.\n\nIhr habt Euch die Belohnung verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Horizontiss' Schriftrolle", description = "Meinem heutigen Kunden verlangt es nach etwas besonders Ausgefallenem.\n\nMan erzählt sich, dass Herold Horizontiss ein Jünger der Alten Götter sei. Des Weiteren soll er stets eine Schriftrolle bei sich tragen, die die Anweisungen der Götter für ihn enthalten, alles Leben im Universum in ihrem Namen zu unterwerfen.\n\nObwohl er die Schriftsprache der Rolle nicht entziffern können wird, wünscht mein Kunde dennoch, diese zu besitzen.\n\nDringt in die Arkatraz der Festung der Stürme ein und beschafft sie für mich, {class}!", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm Horizontiss' Schriftrolle zu beschaffen. Bringt sie zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Es muss ganz schön gefährlich sein, sich in die Angelegenheiten der Alten Götter einzumischen.\n\nNaja, besser Ihr als ich!", completion = "Bevor ich den Zorn der Alten Götter auf mich ziehe, hüte ich mich lieber davor, die Schriftrolle überhaupt zu berühren. Ich werde einen meiner Assistenten mit der Zustellung beauftragen.\n\nIhr habt Eure Belohnung mehr als verdient, {class}, und ich wünsche Euch für die Zukunft alles Glück der bekannten Welt!\n\nKommt morgen wieder und ich werde einen weiteren Auftrag für Euch bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Schildwachen der Arkatraz", description = "Die Schildwachen der Arkatraz sind wahnsinnig geworden. Die Gefangenen laufen Amok und die Wachen greifen all jene an, die helfen wollen.\n\nMah'duun vernimmt im Raunen des Netherwindes die Stimme des Sprechers. Der Sprecher befiehlt die Vernichtung der Schildwachen.\n\nBringt diese Aufgabe zu Ende und die heutige Belohnung gehört Euch!", sourceObjective = "Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Schildwachen der Arkatraz zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden.", completion = "Vielleicht wenden die Naaru sich nach der Vernichtung der Schildwachen an das Konsortium, um Ersatz anzufordern? Mah'duun weiß es nicht und es interessiert ihn auch nicht.\n\nIhr habt Euch Eure Belohnung redlich verdient.\n\nKehrt morgen zu mir zurück, wenn die Winde Mah'duun ihren Willen offenbart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein.", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11400] = { id = 11400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestwidder", description = "Wenn Ihr Pol Bernruh, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", sourceObjective = "Bringt den Handstempel \"Ehrenbrauer\" zu Pol Bernruh in der Nähe des Eingangs zum Braufestplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[11401] = { id = 11401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11403] = { id = 11403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei!", description = "Zorn hielt mich gefangen, {name}, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", sourceObjective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Durotar, Brill oder beim Falkenplatz.", progress = "Schön, Euch wiederzusehen, {name}. Ich bin sicher, die Kinder freuen sich schon auf die Geschichten über Eure Heldentaten.", completion = "Was sagt Ihr? Dieser heilige Foliant gehörte einst einem gefallenen Paladin der Allianz. War er der kopflose Reiter? Also wurde er endlich besiegt?\n\nWas für ein glorreicher Tag, {name}! Eure Legende wird wachsen! Möge man noch von Euch berichten, wenn die Schreckensherrschaft des kopflosen Reiters längst vergessen ist.", sourceObjectiveStatus = "unverified-source-field" }
